quests[5511] = { id = 5511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlüssel zur Scholomance", sourceObjective = "Tja, da ist er, {name}, der fertige Skelettschlüssel. Ich bin eigentlich absolut sicher, dass dieser Schlüssel Euch Zutritt zur Scholomance verschaffen wird. Es gibt aber nur eine Möglichkeit, um absolut sicher zu sein, dass er wirklich funktioniert. Verschwendet keine Zeit darauf, es auszuprobieren, sage ich.\n\nViel Glück. Mögen Eure Siege Euch auch weiterhin Ruhm und Macht bringen, während Ihr die Scholomance in Schutt und Asche legt!", sourceObjectiveStatus = "unverified-source-field" }
quests[5513] = { id = 5513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mäntel der Dämmerung", description = "Euer hervorragenden Dienste für die Argentumdämmerung haben sich herumgesprochen, {name}. Wir sind geehrt, Euch in unseren Reihen zu wissen. Ich wurde ermächtigt, Euch einige der wertvollsten Gegenstände der Dämmerung anzubieten - unsere Mäntel des Magiewiderstands.\n\nWenn Ihr einen Mantel mit Eurer Schulterpanzerung verwendet, könnt Ihr euren Widerstand gegen die Kräfte der Magie auf eine von fünf mögliche Arten verbessern. Als Zeichen der Hingabe für unsere Sache, erbitte ich von Euch nicht weniger als zehn unserer Ehrenmarken, um Zugriff auf die Mäntel zu erhalten.", sourceObjective = "Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Knackschloss an der Kapelle des Hoffnungsvollen Lichts, Östliche Pestländer.", progress = "Ah, edler {class}!  Habt Ihr die Ehrenmarken um die ich Euch gebeten habe? Sobald Ihr mir die Marken übergebt, habt Ihr die Möglichkeit unsere Mäntel zu erwerben.", completion = "Hervorragend - Euer Tribut an die Argentumdämmerung wurde wohlwollend zur Kenntnis genommen, {name}. Nun, da wir dies hinter uns gebracht haben, bin ich erfreut Euch unsere Mäntel zum Erwerb anbieten zu können. Solange Ihr Euren momentanen Status mit uns aufrecht erhaltet, könnt Ihr die Mäntel der Dämmerung bei jedem bevollmächtigten Rüstmeister der Argentumdämmerung erwerben.\n\nFür die Dämmerung, Bruder!", sourceObjectiveStatus = "unverified-source-field" }
quests[5514] = { id = 5514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sold reimt sich auf...", description = "Der Goblin, mit dem Ihr sprechen müsst, ist Krinkle Goldstahl. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der Tanariswüste, hausieren. Er dürfte der Einzige sein, der die Form herstellen kann, die wir benötigen, und seine Dienste werden nicht billig sein. Wir bitten Euch, tief in die Tasche zu greifen, indem Ihr die Gebühr zahlt, die er fordert.\n\nIch bin Apotheker, kein Bankier. Wenn ich Gold herumliegen hätte, wäre ich sicher nicht hier.\n\nIch schätze, ich hab meine Gedanken mal wieder laut ausgesprochen. Upps.\n\nGadgetzan erwartet Euch! Viel Glück!", sourceObjective = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goldstahl in Gadgetzan.", progress = "Ja, ich weiß, wer Ihr seid, und ich weiß, warum Ihr hier seid. Dithers hat mich benachrichtigt, bevor Ihr gekommen seid. Lasst uns zum Geschäft kommen, ja?\n\nIch habe eine Form, die Ihr für den Skelettschlüssel verwenden könnt, aber sie wird Euch teuer kommen - fünfzehn Goldstücke im Voraus, keine Verhandlungen. Ich werde die Skelettfragmente für Euch in die Form packen und ich werde Euch auch beibringen, wie der Schaft des Schlüssels ohne jegliche Kenntnisse der Schmiedekunst zu schmieden ist... alles kostenlos.\n\nWer sagt da noch, dass Söldner keine billigen Angebote machen würden!", completion = "Dithers sagte, dass Ihr die Sachen liefern würdet, und das habt Ihr auch getan! Ein Handel ist ein Handel; dann werde ich jetzt mal die Fragmente für Euch in die Form packen.\n\nHat Dithers sie bereits mit Magie erfüllt? Hervorragend... anderenfalls wäre es für Euch ein langer Weg zurück zum Bollwerk gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5515] = { id = 5515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krastinovs Tasche der Schrecken", description = "Ein großes Gewicht wurde von unseren Herzen genommen, {name}, aber Eure Aufgabe ist noch nicht vollendet. Krastinovs Meister, Kirtonos, lebt immer noch.\n\nBevor Ihr aber Kirtonos gegenübertretet, müsst Ihr Euch zuerst eine Methode besorgen, mit der Ihr ihn beschwören könnt.\n\nEs heißt, dass Jandice Barov das Blut Unschuldiger von Krastinov zu Kirtonos bringt.\n\nSucht sie in den versunkenen Katakomben der Scholomance und streckt sie nieder. Bringt alle Hinweise zurück, die Ihr findet.", sourceObjective = "Sucht nach Jandice Barov in Scholomance und vernichtet sie. Entnehmt ihrer Leiche Krastinovs Tasche der Schrecken. Bringt die Tasche zu Eva Sarkhoff.", progress = "<Eva verschwimmt immer wieder mal mehr, mal weniger.>", completion = "Die Tasche der Schrecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[5517] = { id = 5517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Chromatische Mantel der Dämmerung", description = "<Bruder/Schwester> {name} -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", sourceObjective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Knackschloss an der Kapelle des Hoffnungsvollen Lichts, Östliche Pestländer.", progress = "Seid gegrüßt, mächtiger {class}!  Habt Ihr die Ehrenmarken, um die ich bat? Wenn ihr mir die Marken übergebt, werde ich Euch Euren eigenen Chromatischen Mantel der Dämmerung aushändigen.", completion = "Sehr beeindruckend, {name} - der Chromatische Mantel der Dämmerung gehört nun Euch!\n\n Solange die Argentumdämmerung Euch gegenüber \"Ehrfürchtig\" eingestellt ist, habt Ihr jederzeit die Möglichkeit weitere Chromatische Mäntel zu erwerben. Ab sofort könnt Ihr sie bei jedem Rüstmeister der Dämmerung erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[5518] = { id = 5518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ogeranzug der Gordok", description = "Wenn Ihr versuchen wollt gegen den König dieser Bruchbude zu kämpfen - und ich denke, dass Ihr genau das vorhabt - dann müsst Ihr erstmal an Hauptmann Krombruch vorbei. Sicher könnt Ihr ihn einfach töten. Doch vielleicht wollt Ihr diesen Oger ja am Leben lassen.\n\nEs stellt sich nur die Frage, wie? Nun, ich bin hier schon eine ganze Weile und ich denke, dass ich Euch einen Ogeranzug anfertigen kann, der ausreicht, um diese Kerle zu täuschen. Das einzige Problem wird seine Stabilität sein - zehn Minuten sind das Maximum. Besorgt mir alles was ich brauche und Ihr bekommt einen Ogeranzug. Ich warte hier solange...", sourceObjective = "Bringt 4 Runenstoffballen, 8 Stücke unverwüstliches Leder, 2 Runenfaden und etwas Ogergerbemittel zu Knot Zwingschraub. Momentan ist er im Gordokflügel von Düsterbruch angekettet.", progress = "Von allen Zutaten die ich für die Herstellung des Anzugs brauche, ist das Ogergerbemittel sicherlich am schwersten zu beschaffen; doch eine Etage höher sollte noch etwas zu finden sein. Ok, ist schwer zu sagen, wenn einen diese Gefangenenkugel hier festhält...\n\nNa egal, bringt mir die benötigten Sachen und ich mache Euch einen so guten Ogeranzug, das Captain Kromcrush Euch für einen seiner Oger hält.", completion = "Das sollte gehen. Ein Schnitt hier, eine Stich da... - das wird ein richtiges Meisterwerk!  <Ein breites Grinsen zeichnet sich im Gesicht des Goblins ab.>\n\nHier, damit seid Ihr vorbereitet. Denkt daran - der Ogeranzug ist alles andere als haltbar. Nachdem Ihr ihn angezogen habt, bleiben Euch zehn Minuten bevor er auseinanderfällt und dann ist's aus mit der Täuschung! Benutzt ihn erst kurz bevor Ihr Kromcrush begegnet. Und nicht vergessen... Er wird zwar denken das IHR einer seiner Oger seid, doch schützt er nicht Eure Gruppenmitglieder!", sourceObjectiveStatus = "unverified-source-field" }
quests[5519] = { id = 5519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ogeranzug der Gordok", progress = "Ihr braucht einen weiteren Ogeranzug, richtig?  Da ich wohl so schnell nirgendwo hingehe - bringt mir einfach die gleichen Sachen, um die ich Euch zuvor gebeten habe und ich fertige Euch einen weiteren Ogeranzug an.", completion = "Bitte sehr, {name} - Zieht dieses Ding an und Ihr habt zehn Minuten Zeit, um zu tun, was immer Ihr wollt. Alles gute!\n\nOh, und falls Ihr einen Schlüssel findet der mich hier herausholen könnte,  LASST ES MICH VERDAMMT NOCHMAL WISSEN!!!" }
quests[5521] = { id = 5521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Chromatische Mantel der Dämmerung", description = "<Bruder/Schwester> {name} -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", sourceObjective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Funkellicht im Zugwindlager in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5522] = { id = 5522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leonidas Bartholomäus", description = "Ich habe eine Botschaft von meinem Meister Vectus erhalten. Na ja, die Botschaft war nicht wirklich von Vectus... sie war von jemandem namens Leonidas Bartholomäus. Ich kenne Leonidas nicht, aber er kannte meinen Meister, und niemand kennt meinen Meister, außer er lässt es zu.\n\nLeonidas sagt, dass Vectus die Dracheneier will. Er möchte, dass Ihr sie ihm zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern bringt.\n\nDas tut weh! Warum Ihr? Vertraut Vectus mir nicht? Ach, egal... nehmt einfach die Eier und berichtet Leonidas, dass ich getan habe, was unser Meister befahl.", sourceObjective = "Bringt die gefrorenen Eier zu Leonidas Bartholomäus in den Östlichen Pestländern.", progress = "Ihr seid also derjenige, der an der Blackrockspitze Böses im Schilde führt, ja? Habt Ihr, worum ich gebeten habe?", completion = "Ah, sehr gut. Ihr kennt die böse Macht nicht, für die Ihr gearbeitet habt, aber nun werdet Ihr die Wahrheit erfahren. Und fürchtet Euch nicht - ich bin kein Diener dieses Meisters. Ich bin Leonid Barthalomew, bekannt als 'der Geachtete' bei meinen Brüdern der Argentumdämmerung.\n\nIch habe Tinkee mit einer List dazu gebracht, Euch und die Dracheneier zu mir zu schicken. Und es ist gut, dass mein Trick erfolgreich war, denn wenn diese Eier das geplante Ziel erreicht hätten, wäre eine große Macht in die Hände des Feindes gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5524] = { id = 5524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Chromatische Mantel der Dämmerung", description = "<Bruder/Schwester> {name} -, Eure Taten im Namen der Argentumdämmerung sind zu zahlreich um sie noch aufzuzählen. Als Anerkennung für Eure Taten, werde ich mich von einem unserer wertvollen chromatischen Mäntel der Dämmerung trennen - Er schützt den Träger gleichzeitig gegen alle Formen der Magie. Nur die Stärksten und Besten der Dämmerung haben ein Anrecht auf einen Chromatischen Mantel der Dämmerung!\n\nBringt mir fünfundzwanzig Ehrenmarken als Zeichen Eurer Hingabe und Ihr erhaltet von mir den feinsten unserer Mäntel.", sourceObjective = "Bringt 25 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5525] = { id = 5525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreit Knot!", progress = "Sie nennen ihn den Gordokfesselschlüssel - Naja, zumindest tun es diese \"Tonnenweise Spaß auf zwei Beinen\"-Oger. Ich denke einer der Oger müsste ihn haben, leider weiß ich nicht genau welcher. Möglicherweise ist die Chance größer, dass einer der Wachen ihn hat...\n\nWas erzähle ich da? - sicher habt Ihr ihn schon, oder? Ist es der da??!", completion = "Vielen Dank, dass Ihr mich befreit habt! Ihr seid meine Nummer eins.\n\n Ich hab's doch gewusst, dass ich mein Leben nicht als Ogerhappen beende!" }
quests[5526] = { id = 5526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Splitter der Teufelsranke", description = "Euer Wissen über Eldre'Thalas – Düsterbruch – in Feralas wird nun gebraucht, {name}. Im Ostteil der zerstörten Stadt erstreckt sich das Herrschaftsgebiet von Alzzin dem Wildformer. Begebt Euch mit der gebotenen Eile und Tapferkeit dorthin.\n\nDie verderbte Frucht des Gedeihens, die Teufelsranke, sollte sich in Alzzins Nähe befinden. Versucht so viel wie möglich von der Essenz der Teufelsranke zu erlangen, wenn er fällt. Versiegelt diese in dem Reliquiar und bringt es zu mir.\n\nViel Glück und Cenarius' Kraft sei mit Euch!", sourceObjective = "Sucht die Teufelsranke in Düsterbruch und nehmt einen Teufelsrankensplitter mit Euch. Aller Wahrscheinlichkeit nach werdet Ihr Alzzin den Wildformer töten müssen, um an die Teufelsranke zu gelangen. Benutzt das Reliquiar der Reinheit, um darin den Splitter sicher zu versiegeln, und bringt das versiegelte Reliquiar zu Rabine Saturna in Nachthafen auf der Mondlichtung.", progress = "Mit dem versiegelten Reliquiar der Reinheit in unserem Besitz, wird es uns nicht nur möglich sein, eine verderbte Gefahr aus dieser Welt zu bannen. Stattdessen können wir sie sogar in Ruhe studieren. Vielleicht entdecken wir mit der Zeit neue Wege, um die Besudelung der Verderbnis zu bekämpfen, welche Azeroth seit jeher bedroht.\n\nIch bin sicher, dass Milli es so gewollt hätte...", completion = "Es ist vollbracht, {class}. Der Zirkel des Cenarius steht in Eurer Schuld. Der Krieg ist noch lange nicht zu Ende, doch mit Eurer Hilfe haben wir eine große Schlacht gegen die Mächte gewonnen, die uns die Verdammnis bringen wollen.\n\nBitte akzeptiert dies als Zeichen unserer ewigen Dankbarkeit. Wisset {name}, dass der Zirkel des Cenarius Euch für diese Tat als einen Helden willkommen heißt. Habt dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[5527] = { id = 5527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Reliquiar der Reinheit", description = "Zuerst müssen wir einen Behälter finden, in dem eine sehr stark verderbte Substanz transportiert werden kann, ohne das der Träger Nebenwirkungen davonträgt. Meines Wissens nach, gibt es nur einen Gegenstand der geeignet ist, darin etwas so abscheuliches wie eine Teufelsranke aufzubewahren: ein Reliquiar der Reinheit.\n\nTief in der Einöde von Silithus befinden sich die Überreste des Nachtelfenpostens Südwind. Vor vielen, vielen Jahren gab es dort ein Reliquiar. Wenn wir Erfolg haben wollen, müsst Ihr die Ruinen durchsuchen, in der Hoffnung dort ein Reliquiar der Reinheit zu finden.", sourceObjective = "Reist nach Silithus und sucht in den Ruinen des Südwindpostens nach einem Reliquiar der Reinheit. Sollte Eure Suche Erfolg haben, kehrt zu Rabine Saturna in Nachthafen auf der Mondlichtung zurück.", progress = "Ein Requiliar der Reinheit ist schon für sich alleine ein Artefakt. Nur wenige wurden je hergestellt und von fast allen sagt man, dass sie im Laufe der Zeit verloren gingen.\n\n Ich muss gestehen, dass ich nun schon eine ganze Weile von dem Requiliar beim Südwindposten wusste. Ehrlich gesagt, mit den aufkommenden Unruhen in Silithus, dachte ich unser Geheimnis als das zu beIassen, was es ist - ein Geheimnis. Wenn zuviel bekannt würde, täte dies nur die Aufmerksamkeit des Feindes erregen.\n\nLeider ist die Zeit der Selbstgefälligkeit jetzt vorbei, insbesondere was die Situation in Eldre'Thalas angeht. Wir müssen handeln!", completion = "Ihr seid in der Tat so einfallsreich wie man sich erzählt. Der Zirkel des Cenarius ist gesegnet, Euch auf unserer Seite zu haben.\n\nMit dem Reliquiar in unseren Händen, empfinde ich das erste mal Erleichterung. Es fällt mir jetzt leichter darum zu bitten, dass Ihr Euch nicht nur einen bösartigen Dämonen gegenüber stellt, sondern Ihr sollt vielmehr noch, einen gefährlichen Gegenstand bergen...", sourceObjectiveStatus = "unverified-source-field" }
quests[5528] = { id = 5528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gordokgeschmackstest", sourceObjective = "Ihr jetzt de' Big Boss hier. Also kriegen freie Kostproben meiner besseren Gebräue! Diese Tränke werden Euch verstärken UND Euch Schädel weghauen! Das ist da' guta Zeug, Chef... Ihr versuchen und dann Kreeg glauben!", sourceObjectiveStatus = "unverified-source-field" }
quests[5529] = { id = 5529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchte Jungtiere", description = "Die Argentumdämmerung hat kürzlich erfahren, dass die Geißel ihren eigenen verseuchten Drachenschwarm erschafft! Wir müssen sie stoppen - wenn die Geißel eine Großdrachenstreitmacht auf die Beine stellt, wird sie unbehelligt ganz Azeroth verwüsten!\n\nIhre Totenbeschwörer züchten verseuchte Großdrachen in Scholomance, in der Mitte des Darromersees.\n\nBegebt Euch zur Scholomance und tötet so viele Jungtiere wie nur möglich...bevor sie größer werden können!", sourceObjective = "Tötet 20 verseuchte Jungtiere und kehrt dann zu Betina Moppelzink bei der Kapelle des Hoffnungsvollen Lichts zurück.", completion = "Gut gemacht, {name}! Es wird lange dauern, bis sie ein weiteres Gelege von Großdrachen züchten können.\n\n... Zumindest hoffe ich das!", sourceObjectiveStatus = "unverified-source-field" }
quests[5531] = { id = 5531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betina Moppelzink", description = "Die Eier, die Ihr gebracht habt, sollten in Experimenten der Geißel verwendet werden, um einen verseuchten Drachenschwarm zu erschaffen. Diese gefrorenen schwarzen Dracheneier wären für ihre Studien unersetzlich gewesen und hätten ihren Zeitplan sicherlich beschleunigt.\n\nNun ist es an der Zeit, dass wir ihre Forschung beenden.\n\nBringt die gefrorenen Eier zu Betina Moppelzink da draußen. Sie ist in Wissenschaft und Alchemie sehr bewandert und hat eine Waffe hergestellt, die wir gegen die Geißel einsetzen können. Mit Eurer Hilfe werden wir ihnen einen schweren Schlag versetzen.", sourceObjective = "Bringt die gefrorenen Eier zu Betina Moppelzink.", progress = "Hallo, {name}! Ich habe gehört, Ihr seid mit einigen Dracheneiern hier? Na, dann lasst sie uns mal ansehen!", completion = "Da sind sie ja! Und in einem so hübschen Behälter. Die perfekte Größe!\n\nWir werden diese Eier an einem sicheren Ort aufbewahren, damit wir sie später untersuchen können, aber jetzt benötigen wir das Ding, in dem Ihr sie hergebracht habt.\n\nIch habe ein Gerät mit einer sehr speziellen Verwendung gebaut: Es dient dazu, die untoten Gelehrten von Scholomance zu vernichten. Sie studieren Großdrachen in ihren Bemühungen, einen verseuchten Drachenschwarm zu schaffen, und wir müssen ihre Fortschritte stoppen.\n\nIch nenne das Gerät Dämmerungstrickfalle, weil ... na ja, ich nicht sicher bin, ob es funktioniert!\n\nWürdet Ihr es für uns herausfinden?", sourceObjectiveStatus = "unverified-source-field" }
quests[5533] = { id = 5533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomance", description = "Auf der Insel Darrowehr liegt die Scholomance - ein elendes Zentrum der Totenbeschwörung und des Bösen der Geißel. Unser Feind lebt im Inneren und führt unaussprechliche Taten der Verderbtheit an nichts ahnenden Opfern aus... zumindest vermuten wir das. Eine Tür versperrt den Weg, und ganz gleich was wir versuchen, der Zutritt ist nur mit dem richtigen Schlüssel möglich.\n\nAlchemist Arbington weiß viel über die Scholomance und hat eine Idee, wie ein Schlüssel zu erlangen ist. Ihr habt mir Euren Wert bewiesen und nun vertraue ich Euch diese Aufgabe an. Sprecht mit ihm über diese Angelegenheit.", sourceObjective = "Sprecht mit Alchemist Arbington an der Zugwindspitze, westliche Pestländer.", completion = "Grüße, {class}. Ich habe einen Großteil meiner Studien der Scholomance gewidmet und glaube, dass ich eine Möglichkeit kenne, wie Ihr einen Schlüssel erlangen könnt, der Euch nach Belieben durch die Vordertür bringt.\n\nIch kann mir nur vorstellen, welch schreckliche Dinge im Inneren zu sehen sein werden, {name}. Ich weiß nicht, wie Ihr heroischen Typen das manchmal ertragt ...", sourceObjectiveStatus = "unverified-source-field" }
quests[5534] = { id = 5534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kim'jaels 'fehlende' Ausrüstung", description = "Was?! Was?!\n\nDas war nicht gut genug für Euch? Wisst Ihr, wie teuer diese Sprengstoffe sind? Die kosten... ach, egal. Ihr wollt also echtes Geld machen, ja? Na dann... so läuft das im Geschäftsleben: Ihr beweist, dass Ihr ein wertvoller Angestellter seid und dann werdet Ihr entsprechend belohnt, nachdem Ihr schön brav durchgehalten habt.\n\nFalls Ihr also ein \"wertvoller\" Angestellter seid, dann begebt Euch zu den Ruinen von Eldarath und bringt mir irgendeine Rune, nach der diese Blutelfen gesucht haben. Anscheinend befindet sie sich im Besitz der Naga.", sourceObjective = "Sucht, in den Ruinen von Eldarath irgendeine Rune, die die Naga in ihrem Besitz haben, und bringt sie Kim'jael in Azshara.", progress = "Also, {name}? Wo ist die Rune? Ihr seid doch ein guter Angestellter, nicht wahr? Ihr seid doch hier, um zu helfen?\n\nZwingt mich nicht, noch mal zu überdenken, ob ich Euch das zahle, was wir vereinbart haben. Was? Oh, wir haben gar nichts vereinbart? Na toll ... dann lasst Euch Zeit ... wisset nur, dass es wesentlich weniger sein wird, wenn Ihr lange braucht.", completion = "Haha! Großartig!\n\nIch werde bestimmt herausfinden, wofür das ist und warum Magus Rimtori - die Kuh, die mich angeheuert hat - es haben wollte. Ha! Jetzt habe ich Euch, ihr stinkenden Blutelfen! Kim'jael! Ha! Denen werde ich zeigen, wer hier die Ratten sind!\n\nDas war prima, {name}. Heißen Dank. Hier, nehmt diese Münze und verschwindet ... ich muss mich an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5535] = { id = 5535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spirituelle Unruhe", description = "Vor langer Zeit gehörten die Hochgeborenen zu den mächtigsten Schülern des Arkanen, die die Nachtelfen je hervorgebracht hatten. Die Verderbnis, die mit solchen Studien einhergeht, brachte großes Unglück über die Gesellschaft der Nachtelfen und wirkte sich in großem Umfang auf Azeroth aus... wie Ihr sicherlich wisst.\n\nIch habe den Schildwachen versprochen, dass ich die Geister aus ihren sterblichen Banden befreie, wenn ich sie finde. Wenn Ihr dasselbe tun würdet, kann ich Euch sicherlich belohnen.\n\nDie Geister spuken im Schattensangschrein, von hier aus im Nordosten.", sourceObjective = "Vernichtet 6 Erscheinungen einer Hochgeborenen und 6 Lichlinge eines Hochgeborenen, bevor Ihr zu Loh'atu in Azshara zurückkehrt.", completion = "Gut gemacht, {class}. Danke für Eure Hilfe. Die Geister haben ihren Frieden und die Bedrohungen, die ihr Verlangen nach dem Arkanen angezogen hat, wurden dezimiert.\n\nIch bin sicher, dass beide Seiten des Konflikts, der Azeroth verheert, sehen werden, dass Ihr über solchen Dingen steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[5536] = { id = 5536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Land voller Hass", description = "Die Satyrn, entstellte und böse Aspekte der Nachtelfen, infizieren jetzt die hochheiligen Länder, die einst von Cenarius bereist wurden. Ich kann nicht für die Nachtelfen sprechen, wenn es um die ganzen Gräueltaten geht, die diese dämonischen Kreaturen begangen haben, aber ich habe der Erdenmutter einen Eid geschworen, den Elfen zu helfen, das Land von solch einer Plage zu befreien.\n\nIch bin sicher, dass Ihr Euch beweisen würdet, wenn Ihr mir bei der Reinigung helfen würdet.\n\nNordöstlich von hier könnt Ihr den Haldarrklan finden. Kehrt zu mir zurück, nachdem Ihr Euch gegen ihre Stärke bewiesen habt.", sourceObjective = "Tötet 6 Satyrn der Haldarr, 2 Schwindler der Haldarr sowie 2 Teufelsanbeter der Haldarr und kehrt dann zu Loh'atu an der Grenze zum Eschental zurück.", progress = "Wie läuft Eure Schlacht gegen die Satyrn, {class}?\n\nSind sie so stark, wie Ihr dachtet? Stärker? Oder vielleicht waren sie nichts angesichts Eurer eigenen Macht?", completion = "Gut gemacht, {class}. Ich sehe, dass Ihr nicht nur geschickt, sondern auch schlau seid. Solche Kreaturen zu besiegen ist ein Zeugnis Eurer Loyalität zu den Geschöpfen der Erdenmutter, auch wenn Ihr sie nicht als Eure Gottheit anerkennt. Man findet sie in allen Dingen auf diesem Planeten und darüber hinaus. Ihre Augen, eines dunkel und eines hell, ziehen über den Himmel und blicken immer auf uns herab.\n\nBitte, nehmt diesen kleinen Stapel Münzen als Wertschätzung dessen, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5537] = { id = 5537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skelettfragmente", description = "Um in die Scholomance zu gelangen, benötigt ihr einen Dietrich. Er muss aus den Überresten eines Skeletts geschmiedet werden- eigentlich aus mehreren - und er darf nur durch die stärksten Metalle in einer geeigneten Form gehärtet werden. Ein Signet der Macht von einem Wesen, das das Portal zur Scholomance natürlich öffnen kann, gibt dem Schlüssel seine endgültige Funktion.\n\nAber eines nach dem anderen, {name}. Wir benötigen Skelettfragmente für das Schmieden des Schlüssels. Skelette innerhalb von Andorhal sollten den gewünschten Effekt bringen, aber die außerhalb der Mauern könnten vielleicht auch ausreichen.", sourceObjective = "Bringt 15 Skelettfragmente zu Alchemist Arbington an der Zugwindspitze in den Westlichen Pestländern.", progress = "So morbid es vielleicht klingt, aber wir werden einen guten Vorrat geeigneter Skelettfragmente benötigen, um die äußere Schicht des Schlüssels herzustellen. Man nennt so etwas nicht umsonst Skelettschlüssel, wisst Ihr.", completion = "Das wird funktionieren, {name}! Jetzt bin ich dran... ich werde sie mit einem geeigneten Härter tränken, wodurch sie den starken Schmiedeprozess überstehen werden, den sie schließlich durchlaufen müssen.\n\nDer nächste Schritt wird sein, eine geeignete Form für den Schlüssel zu bekommen. Ich kenne einen Goblin-Schmied in Tanaris, der in der Vergangenheit Formen für ähnlich makabre Dinge hergestellt hat. Er arbeitet für den üblichen Auftraggeber der Goblins - den höchsten Bieter.", sourceObjectiveStatus = "unverified-source-field" }
quests[5538] = { id = 5538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sold reimt sich auf...", description = "Der Goblin, mit dem Ihr sprechen müsst, ist Krinkle Goldstahl. Er geht mit seinen Fertigkeiten bei den höchsten Bietern in Gadgetzan, in der Tanariswüste, hausieren. Er dürfte der Einzige sein, der die Form herstellen kann, die wir benötigen, und seine Dienste werden nicht billig sein. Wir bitten Euch, tief in die Tasche zu greifen, indem Ihr die Gebühr zahlt, die er fordert.\n\nIch bin Alchemist, kein Bankier. Wenn ich Gold herumliegen hätte, wäre ich sicher nicht hier.\n\nIch schätze, ich hab meine Gedanken mal wieder laut ausgesprochen. Upps.\n\nGadgetzan erwartet Euch! Viel Glück!", sourceObjective = "Bringt die magieerfüllten Skelettfragmente sowie 15 Goldstücke zu Krinkle Goldstahl in Gadgetzan.", progress = "Ja, ich weiß, wer Ihr seid, und ich weiß, warum Ihr hier seid. Arbington hat mich benachrichtigt, bevor Ihr gekommen seid. Lasst uns zum Geschäft kommen, ja?\n\nIch habe eine Form, die Ihr für den Skelettschlüssel verwenden könnt, aber sie wird Euch teuer kommen - fünfzehn Goldstücke im Voraus, keine Verhandlungen. Ich werde die Skelettfragmente für Euch in die Form packen und ich werde Euch auch beibringen, wie der Schaft des Schlüssels ohne jegliche Kenntnisse der Schmiedekunst zu schmieden ist... alles kostenlos.\n\nWer sagt da noch, dass Söldner keine billigen Angebote machen würden!", completion = "Arbington sagte, dass Ihr die Sachen liefern würdet, und das habt Ihr auch getan! Ein Handel ist ein Handel; dann werde ich jetzt mal die Fragmente für Euch in die Form packen.\n\nHat Arbington sie bereits mit Magie erfüllt? Hervorragend... anderenfalls wäre es für Euch ein langer Weg zurück zur Chillwindspitze gewesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5541] = { id = 5541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Munition für Schlingerschuss", description = "Hegnar Schlingerschuss verkauft Gewehre an der Straße nach Ambossar. Scharfschützen und Mörsertrupps verbringen viel Zeit damit, in der Nähe seines Geschäfts zu üben, und er braucht ständig neue Munition.\n\nAber... die letzte Munitionskiste, die ich ihm geschickt habe, ist unterwegs verloren gegangen. Mein Kurier sagte, er lagerte nahe des Graufelsbaus, als Wendigos ihn davonjagten... und der Dummkopf hat Schlingerschuss' Munition zurückgelassen!\n\n{name}, könnt Ihr diese Munition beschaffen und zu Schlingerschuss bringen? Er wartet darauf und ihm gehen bestimmt bald die Vorräte aus.", sourceObjective = "Bringt Schlingerschuss' Munition zu Hegnar Schlingerschuss in Dun Morogh.", progress = "Ich hoffe, Ihr seid nicht wegen Munition hier, denn ich habe fast keine mehr!", completion = "Wunderbar, mehr Munition! Die Lieferung vom alten Loslor ist endlich da! Na ja, die Munition mag etwas verspätet ankommen, aber wie schon mein Großvater mir immer gesagt hat: Besser spät als nie!\n\nVielen herzlichen Dank, {name}. Ich habe bereits Käufer, die begierig auf dieses Zeug warten!", sourceObjectiveStatus = "unverified-source-field" }
quests[5542] = { id = 5542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenhunde", description = "Wenn Ihr hier bleiben wollt, bitte ich Euch nur, Euren Unterhalt zu verdienen. Wir haben hier viele Plagegeister, denen etwas 'Disziplin' gut tun würde.\n\nIhr könnt mit den Seuchenhunden und den kleinen Seuchenhunden beginnen.\n\nViel kann ich Euch im Gegenzug nicht anbieten, aber ein warmes Mahl und ein wenig Konversation wäre Euch garantiert, wenn Ihr erfolgreich seid.", sourceObjective = "Erschlagt 20 kleine Seuchenhunde, 5 Seuchenhunde und 5 rasende Seuchenhunde. Kehrt zu Tirion Fordring zurück, sobald Ihr die Aufgabe erfüllt habt.", completion = "Gut gemacht, {name}. Kommt. Ruht Euch aus. Lasst uns essen und von längst vergangenen Tagen sprechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[5543] = { id = 5543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutgefärbter Himmel", description = "Wehe jenen, die töricht genug sind, in die Pestländer zu wandern. Alle Arten der Verderbtheit bewohnen diese Wälder - von den fanatischen Anhängern des Scharlachroten Kreuzzugs, die jeden töten, der nicht das Zeichen der Kreuzzügler trägt, bis hin zur mordlustigen Geißel, die ihre Anzahl vergrößern will, indem sie ihre Ränge mit Untoten füllt.\n\nSogar die Tierwelt wurde in wilde, menschenfressende Bestien verwandelt. Ich bitte Euch, die zu vernichten, die vom Firmament aus zuschlagen: die Seuchenfledermäuse.", sourceObjective = "Erschlagt 30 Seuchenfledermäuse und kehrt zu Tirion Fordring zurück.", completion = "Ihr seid ein leuchtendes Beispiel des Anstands, {race}! Es ist lange her, dass ich das Blut von Helden in meinen Adern gefühlt habe. Eure Taten der Tapferkeit sind wahrlich erhebend!", sourceObjectiveStatus = "unverified-source-field" }
quests[5544] = { id = 5544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aassammlung", description = "Meine Essensvorräte gehen zur Neige, {race}. Ich schäme mich zuzugeben, dass ich möglicherweise nicht genug Nahrung habe, um sie mit Euch zu teilen.\n\nKönnt Ihr einem alten Mann bei einer einfachen Aufgabe helfen? Hier in der Umgebung sind Aaswürmer die einzigen Tiere, die von den Verheerungen der Seuche unbeeinflusst blieben. Wenn sie auch ziemlich langweilig schmecken, kann das Fleisch der Würmer doch leicht monatelang aufbewahrt werden. Ich werde einige hundert Pfund benötigen, um meine Vorräte für den kommenden Winter aufzustocken!", sourceObjective = "Sucht nach den Aaslarven und Aasverschlingern dieses Gebiets. Erschlagt sie und sammelt ihr Fleisch. Kehrt zu Tirion Fordring zurück, wenn Ihr 15 Scheiben Aaswurmfleisch gesammelt habt.", progress = "Ihr werdet Euch an den Geschmack gewöhnen, {race}.", completion = "Möge das Licht über Euch wachen! Gesegnet seid Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[5545] = { id = 5545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündel Probleme", description = "Ich habe hier ein echtes Problem. Ich habe einen Liefertermin für eine Bestellung Holz und mir läuft die Zeit davon. Die Wölfe und Bären nördlich von hier haben meine Arbeiter von den Holzbündeln verjagt, die sie bereits gefällt hatten.\n\nIch habe bereits mit Stellvertreter Rainer darüber gesprochen, dass die Tiere entfernt werden müssen, aber ich brauche jemanden, der das Holz für mich holt. Wenn Ihr acht Holzbündel für mich holen würdet, könnte ich den Termin vielleicht noch einhalten.", sourceObjective = "Bringt 8 Holzbündel zu Raelen beim Holzfällerlager des Osttals.", progress = "Der Termin kommt immer näher, {class}. Beeilt Euch bitte und holt diese Holzbündel.", completion = "Exzellent! Dank Euch sollte ich die Bestellung rechtzeitig zusammenstellen können. Um Euch meine Dankbarkeit zu zeigen, würde ich Euch gern ein paar Münzen als Entschädigung für Eure Mühen anbieten.\n\nVielen Dank und lebt wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[5561] = { id = 5561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kodozusammentrieb", description = "Bibbly glaubt, dass er der einzige Goblin in Desolace sei, der weiß, wie man Geld macht. Tja, die einzige Karawane, die mutig genug ist, diese Gebiete zu bereisen, verlässt sich auf mich. Nachdem ich gelernt habe, wie man alternde Kodos mit meinem Kodokombobulator verjüngt und kontrolliert, sind die Karawanenbesitzer Cork und Rigger mit mir eine Partnerschaft eingegangen.\n\nNehmt den Kombobulator und wendet ihn auf jeden beliebigen alten oder alternden Kodo an; er wird das Biest in einen gezähmten Kodo verwandeln und es zwingen, Euch zu folgen. Wenn Ihr einen Kodo gezähmt habt, bringt ihn zu mir her.", sourceObjective = "Bringt 3 gezähmte Kodos sowie den Kodokombobulator zu Smeed Schraubenbuddel bei Schraubenbuddels Lager.", progress = "Die Karawane wird bald hier sein; habt Ihr die fünf gezähmten Kodos, um die ich gebeten hatte?", completion = "<Smeed Scrabblescrew beginnt zu zählen.>\n\nDrei, vier und fünf... hervorragend, ich habe um fünf gezähmte Kodos gebeten und ich habe fünf gezähmte Kodos bekommen... Ich werde reich sein... ja, sehr reich. Ich würde zu gern den Ausdruck auf Bibblys grünem Gesicht sehen, wenn er von meinem Erfolg hört!", sourceObjectiveStatus = "unverified-source-field" }
quests[5581] = { id = 5581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portale der Legion", description = "Seht - die Hand von Iruxos.\n\nIch habe sie selbst einem der Anführer der Brennenden Klinge abgenommen.\n\nIhr müsst sie besitzen, wenn die Dämonenportale beim Zirkel der Mannoroc gebannt werden sollen... und genau darum bitte ich Euch nun.\n\nDie Bedrohung durch die Dämonen steigt stetig und wir müssen diese Portale schließen, um die Flut der Dämonen, die in diese Welt eindringen, zu stoppen.", sourceObjective = "Verbannt 6 Portale beim Zirkel der Mannoroc und kehrt dann zu Felgur Zweischneid zum Geistwandlerposten zurück.", progress = "Habt Ihr die Dämonenportale in Mannorocs Koven verbannt?", completion = "Ich muss Euch loben, {name}. Eure Bemühungen haben beim Kampf gegen die dämonische Bedrohung sehr geholfen, und ganz Azeroth ist jetzt sicherer.", sourceObjectiveStatus = "unverified-source-field" }
quests[5582] = { id = 5582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesunde Großdrachenschuppe", description = "Dies ist eine Schuppe von einem verseuchten Großdrachen-Jungtier. Aber im Gegensatz zu den anderen pockennarbigen, eiternden Schuppen an dem kleinen Biest ist diese rare Schuppe gesund und unbeschädigt.\n\nBetina Moppelzink wird eine Probe davon für Forschungen haben wollen.", sourceObjective = "Bringt die gesunde Großdrachenschuppe zu Betina Moppelzink bei der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", progress = "{name}, habt Ihr mir etwas zu zeigen?", completion = "Exzellent! Das wird für meine ständigen Studien der Machenschaften der Geißel unschätzbar sein. Vielen Dank, {name}, und falls Ihr noch mehr von diesen Schuppen findet, bringt sie mir bitte!", sourceObjectiveStatus = "unverified-source-field" }
quests[5601] = { id = 5601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwester Pamela", description = "Ich bin während des großen Krieges aus Lordaeron geflohen und hatte das Glück, entkommen zu können, bevor die Geißel durch meine Heimat fegte und sie zu einem verseuchten Alptraum machte! Ich hatte Glück, aber meine Familie nicht. Ich fürchte, dass sie während der Schlacht von Darroheim getötet wurden.\n\nDarroheim ist ein Dorf in den Östlichen Königreichen, eingebettet in die südlichen Hügel dessen, was heutzutage Östliche Pestländer genannt wird. Würdet Ihr Euch dorthin begeben und nach meiner Familie suchen? Ich vermisse sie so sehr, besonders meine kleine Schwester Pamela.\n\nBitte, sucht sie für mich!", sourceObjective = "Sucht Pamela Rotpfad in Darroheim.", completion = "Wo ist meine Schwester Jessica? Sie ist vor langer Zeit fortgegangen, als ich noch ein kleines Mädchen war. Sie weinte so sehr, als sie fort ging. Ich weiß nicht, warum sie geweint hat! Vielleicht ist sie hingefallen und hat sich ihren Zeh gestoßen.\n\nAls Jessica hier war, haben wir immer gespielt und getanzt und hübsche Blumen rund um das Haus gepflückt. Und manchmal haben wir uns versteckt, wenn wir gesehen haben, dass Papa kam. Dann sind wir aus dem Versteck gekommen und haben ihn überrascht!\n\nKomm zurück, Jessica! Wenn du zurückkommst, dann kommt Papa vielleicht auch und wir können wieder zusammen spielen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[5621] = { id = 5621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Mondes", description = "Ich brauche Eure Hilfe, {name}. Ich kann hier nicht weg, denn ich muss hier die anderen Schüler unterweisen, doch Ihr könntet einer unserer verwundeten Schildwachen direkt südlich von Dolanaar helfen. Sie wurde beim Patrouillieren der Stadt verletzt und benötigt unsere Hilfe. Ihr Name ist Shaya.\n\nWenn Ihr sie findet, heilt ihre Wunden, und stärkt dann ihren Körper mit Euren Zaubern. Das wird sie zumindest etwas länger vor Schaden bewahren, wenn es wieder hart auf hart kommt. Kehrt zu mir zurück, nachdem Ihr Eure Pflicht gegenüber Elune erfüllt habt.", sourceObjective = "Sucht die Schildwache Shaya und heilt ihre Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Laurna Morgenglanz in Dolanaar zurück.", completion = "Ihr habt Eure Sache gut gemacht und Elune gedient. Dafür danke ich Euch.\n\nBitte, nehmt diese Robe als ein Zeichen meiner Dankbarkeit. Sie bedeutet, dass Ihr Euch einen Platz in unserem Orden verdient habt. Wenn Ihr wollt, tragt sie mit Stolz, doch wie auch immer Ihr Euch entscheidet - wir werden Euch immer als einen der unsrigen anerkennen.\n\nGeht mit Elune, {name}, und danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[5622] = { id = 5622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune geneigt", description = "{name}, sobald Eure Aufgaben hier im Laubschattental abgeschlossen sind, müsst Ihr nach Dolanaar reisen. Dort werdet Ihr Laurna Morgenglanz finden. Sie wird Euch weiter in den Dingen Elunes unterweisen und bei ihr werdet Ihr Euch Eure ersten Gewänder verdienen, die Eure Position als <Priester/Priesterin> von Elune kennzeichnen.\n\nSeid vorsichtig und möget Ihr auf Euren Reisen beschützt werden.", sourceObjective = "Sprecht mit Laurna Morgenglanz in Teldrassil.", completion = "Ich freue mich, dass Shanda Euch zu mir geschickt hat, {name}. Junge {class} die Wege von Elune zu lehren, macht mir große Freude.", sourceObjectiveStatus = "unverified-source-field" }
quests[5623] = { id = 5623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Licht geneigt", description = "Ich grüße Euch, <junger Priester/junge Priesterin>. Die Zeit ist gekommen, mehr über unsere Religion zu lernen. Nachdem Ihr Eure Aufgaben hier in Nordhain abgeschlossen habt, sucht bitte Priesterin Josetta in Goldhain auf. Sie kann Euch noch mehr beibringen und hat gehört, dass Ihr in den Wegen des Lichts gut voranschreitet. Sie freut sich darauf, Euch weiter unterrichten zu können.", sourceObjective = "Sprecht mit der Priesterin Josetta im Wald von Elwynn.", completion = "Schön, dass Ihr angekommen seid, {name}. Wir haben viel über Eure Zukunft und Euren Pfad im Licht zu bereden.", sourceObjectiveStatus = "unverified-source-field" }
quests[5624] = { id = 5624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Lichts", description = "Normalerweise stelle ich den Gefolgsleuten des Lichts eine kleine Herausforderung, um ihre Fertigkeiten zu prüfen. Ich möchte sehen, ob sie es wert sind, ihre ersten Roben zu tragen - sie sind ein Zeichen, dass die Kirche <den Priester/die Priesterin> nach außen hin trägt und unterstützt.\n\nDoch hier ist die Situation etwas anders. Einer der Bürger von Goldhain sah eine verletzte Wache nahe dem See östlich von hier. Er heißt Roberts. Sucht ihn, heilt ihn, stärkt seinen Körper und kehrt hierher zurück. Wenn Ihr das für mich tun könnt, dann werde ich Eure Prüfung als bestanden ansehen.", sourceObjective = "Sucht die Wache Roberts und heilt seine Wunden mithilfe von 'Blitzheilung'.", progress = "Wie Ihr vielleicht schon erfahren habt, ist unsere Heilmagie lebenswichtig für das Überleben unseres Volkes in diesen harten Zeiten... insbesondere für Abenteurer und Helden, die zu Waffen und Magie greifen, um die verschiedensten Gefahren zu bekämpfen.\n\nIhr tätet gut daran, Euch immer der Wichtigkeit dieser Fertigkeit zu erinnern. Dies, zusammen mit 'Seelenstärke', sorgt dafür, dass Eure Kameraden im Kampf wesentlich fähiger sein werden, denn sie können dann eine größere Anzahl Treffer aushalten.\n\nLasst keinen abschätzig über die Macht Eurer Magie reden.", completion = "Ausgezeichnet, {name}. Mit einer weiteren gesunden Wache, die dort draußen die Stadt unterstützt, werden wir viel sicherer sein. Ich freue mich zu sehen, dass Ihr bereits lernt, Eure Fähigkeiten weise einzusetzen. Wenn Ihr irgendwann einmal glaubt, für eine weitere Ausbildung bereit zu sein, dann kommt bitte zu mir zurück. Doch fürs Erste nehmt diese Robe hier. Andere werden dann wissen, dass Ihr unserem Orden angehört. Wenn Ihr sie nicht tragen wollt, ist auch das in Ordnung. Später wird es weitere Prüfungen geben und diese Robe ist dafür nicht erforderlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[5625] = { id = 5625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder des Lichts", description = "Normalerweise wird etwa zu dieser Zeit die Macht in einem von Euch geprüft, um zu sehen, ob er würdig genug ist, jene Roben zu tragen, die seinen Platz in der Kirche anzeigen. Doch um ehrlich zu sein, gibt es wichtigere Dinge, um die ich mich kümmern muss. Bürger von Kharanos kamen gerade hierher und erzählten mir von einem verletzten Gebirgsjäger direkt außerhalb der Stadt im Süden - sein Name ist Dolf.\n\nWenn Ihr Dolf heilt und ihm 'Seelenstärke' gebt, werde ich das als erfolgreiche Prüfung ansehen. Wie klingt das?", sourceObjective = "Sucht den Gebirgsjäger Dolf und heilt seine Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Maxan Anvol in Kharanos zurück.", completion = "Gut gemacht, {name}. Ihr tragt das Licht in Euch, so viel ist klar.\n\nHier, nehmt diese Robe. Sie dient als Zeichen Eurer Rolle innerhalb der Kirche und wird den Leuten dabei helfen, Euch als {class} zu erkennen - tragt sie, wann immer Ihr möchtet.\n\nIhr werdet Euch später weiteren Prüfungen unterziehen müssen. Tut, was Ihr könnt, um etwas über Eure Fähigkeiten und Eure Möglichkeiten zu erfahren. Versucht Euch einmal allein an ein oder zwei Kämpfen und dann mit anderen Reisenden zusammen.\n\nUnd keine Sorge ... in Euch steckt sehr viel Macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[5626] = { id = 5626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Licht geneigt", description = "He! {name}! Habt Ihr einen Moment Zeit?\n\nIhr seid dem Licht jetzt lange genug gefolgt, um den Weg zu Maxan Anvol in Kharanos zu finden. Er wird Euch mehr über den Weg beibringen, dem Ihr folgt, und wenn Ihr Euch als würdig erweist, wird er Euch Eure ersten Roben geben, die Eure Position als <Priester/Priesterin> kennzeichnen.\n\nAlso dann mal los! Sobald Ihr hier fertig seid, geht durch den Tunnel - er wird auf Euch warten.", sourceObjective = "Sprecht mit Maxan Anvol in Dun Morogh.", completion = "Ach, Branstock hat Euch also geschickt? Gut, gut! Er hat Recht, es ist Zeit, dass Ihr einen größeren Schritt ins Licht tut. Es wird Euren Charakter formen und Euch stärker machen... und das ist, was Ihr mehr als alles andere braucht: Kraft des Körpers... Kraft des Willens.", sourceObjectiveStatus = "unverified-source-field" }
quests[5627] = { id = 5627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sterne von Elune" }
quests[5628] = { id = 5628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Ah, ja, hallo, {name}? Ich freue mich, dass Ihr auf ein kurzes Gespräch hereinschaut. Ihr seid weit fort von zu Hause, und das in so jungen Jahren - ich bewundere einen solchen Ehrgeiz. Ich wünschte, ich hätte den Mut gehabt, durch die Welt zu reisen, als ich noch jünger war.\n\nEine Priesterin Eures Ordens war vor nicht allzu langer Zeit hier und hat nach Euch gesucht. Sie sagt, Ihr müsstet dringend in den Tempel des Mondes in Darnassus zurückkehren und mit Priesterin Alathea sprechen - es hatte etwas mit Eurer Ausbildung zu tun. Ich würde nicht zu lange trödeln, wenn es irgendwie geht.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5629] = { id = 5629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Hallo, {name}. Ich weiß, dass Ihr damit beschäftigt wart, unserem Volk zu helfen, aber Ihr müsst Euch auch Zeit für Euch selbst nehmen. Die Priesterin Alathea hat jemanden hergeschickt, um nach Euch zu suchen. Es scheint, dass Ihr die Aufmerksamkeit unserer Ältesten erregt habt, und sie sind der Meinung, dass Ihr für größere Dinge bereit seid. Begebt Euch zum Tempel des Mondes in Darnassus und sucht dort nach Alathea. Sie wird Euch erwarten. Viel Glück, und möge Elune mit Euch sein.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", completion = "Wunderbar, Ihr seid zurückgekehrt, {name}. Es erfreut Tyrande und mich immer, wenn diejenigen, die wir ausgebildet haben, in die Welt hinausziehen und sicher zu uns zurückkehren. Wie ist es Euch ergangen? Segnet Elune Eure Reisen immer noch? Vielleicht könnt Ihr mir mehr über Eure Reisen berichten, wenn wir über die Angelegenheiten gesprochen haben, die vor uns liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5630] = { id = 5630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Hallo, <Bursche/Mädel>. Es ist gut zu sehen, dass Ihr entfernte Länder weit und breit bereist. Ich will Euch nicht beleidigen, aber viele Eurer Art vertragen das kalte Klima normalerweise nicht gut. Schön zu sehen, dass Ihr aus härterem Holz geschnitzt seid.\n\nVor nicht allzu langer Zeit war eine Eurer Priesterinnen hier und hat nach Euch gesucht - sie sagte so etwas in dem Sinne, dass Ihr eine Priesterin Alathea im Tempel des Mondes in Darnassus aufsuchen solltet. Sagte, es wäre wichtig und Ihr solltet Euch bald dorthin begeben.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5631] = { id = 5631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Eine Priesterin hat kürzlich unsere Hallen besucht und Euch gesucht, {race}. Sie sagte, sie hätte den Auftrag, Euch zu finden, und dass Ihr so bald wie möglich zum Tempel des Mondes in Darnassus zurückkehren solltet. Wenn Ihr ankommt, sucht Priesterin Alathea auf - sie wird Euch mehr berichten.\n\nDas Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5632] = { id = 5632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Oh, aber ja, natürlich. Hallo, {name}. Eine Botin von Eurem Orden war vor nicht allzu langer Zeit hier und hat nach Euch gesucht. Sie erwähnte, dass in Darnassus etwas Wichtiges geschieht und dass Ihr so bald wie möglich zum Tempel des Mondes zurückkehren sollt. Wenn Ihr dort ankommt, sprecht mit Priesterin Alathea. Ich glaube, es hat etwas damit zu tun, dass Ihr so gute Fortschritte beim Verständnis unserer Bräuche macht.\n\nWie gesagt, kehrt nach Darnassus zurück, sobald Ihr könnt.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5633] = { id = 5633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimkehr", description = "Seid gegrüßt, <Bursche/Mädel>. Es ist schön, Euch hier in unseren großen Hallen zu sehen. Ein Segen sei mit Euch und Eurer Art.\n\nWährend Ihr durch unsere Länder gereist seid, kam eine Priesterin Eures Tempels her, die nach Euch suchte. Sie sagte, dass Ihr so bald wie möglich zum Tempel des Mondes zurückkehren sollt. Es tut mir leid, dass ich Euch nicht mehr berichten kann, aber es klang wichtig. Wenn Ihr zum Tempel kommt, sprecht mit Priesterin Alathea.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5634] = { id = 5634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", sourceObjective = "Ihr habt dem Licht einen großen Dienst erwiesen, indem Ihr ein leuchtendes Beispiel für diejenigen wurdet, die durch dieses gefährliche Land und in die Ferne reisen. Bitte, nehmt diese Lektion als Dank für all das an, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5635] = { id = 5635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Ihr habt die Aufmerksamkeit unserer Vorgesetzten erregt, {name}. Sie bitten, dass Ihr so bald wie möglich zur Kathedrale des Lichts in Sturmwind reist. Anscheinend sind sie der Meinung, dass Ihr Euch bereits würdig erwiesen habt und bereit seid, Eure Ausbildung weiterzuführen. Wenn Ihr dort anlangt, sucht nach der Hohepriesterin Laurena. Sie kann Euch weitere Anweisungen geben. Viel Glück, und möge das Licht mit Euch sein.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", completion = "Schön, dass Ihr angekommen seid, {name}. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5636] = { id = 5636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Elune segne Euch, {race}. Ich hoffe, dass Euer Licht Euch findet und Euch heute gut schützt.\n\nEiner Eurer Priester war vor nicht allzu langer Zeit hier und suchte nach Euch. Er erwähnte, dass Ihr sobald wie möglich zur Kathedrale des Lichts zurückkehren und mit der Hohepriesterin Laurena sprechen sollt. Es scheint, als hättet Ihr Euch wacker geschlagen, dass Ihr eine solche Aufmerksamkeit erlangt. Ich würde hier nicht allzu viel Zeit verbringen - Eure Leute brauchen Euch.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5637] = { id = 5637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Die Zeit ist für Euch gekommen, nach Sturmwind zu gehen, {name}. Die Hohepriesterin Laurena in der Kathedrale des Lichts möchte mit Euch sprechen. Es muss etwas sehr Gutes oder sehr Schlechtes sein, wenn die Hohepriesterin Euch persönlich dort sehen will, aber ich denke, dass Ihr selbst nur Gutes getan habt und dass es eine gute Sache ist, dass sie mit Euch sprechen möchte.\n\nVerschwendet hier aber nicht allzu viel Zeit. Ich an Eurer Stelle würde mich umgehend auf den Weg machen.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", completion = "Schön, dass Ihr angekommen seid, {name}. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5638] = { id = 5638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Vor kurzer Zeit kam einer Eurer Priester her und suchte nach Euch, {race}. Er sagte, dass ich Euch zur Kathedrale des Lichts schicken solle, wenn ich Euch sehen würde. Er sagte, es sei sehr wichtig, aber ich an Eurer Stelle würde mir trotzdem nicht allzu viele Sorgen machen. Seine Haltung erschien positiv...als ob es gute Neuigkeiten wären. Auf jeden Fall solltet Ihr Euch beeilen, wenn Ihr meine Meinung wissen wollt.\n\nElune sei mit Euch, {race}.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5639] = { id = 5639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Ihr werdet in Sturmwind gebraucht, {name}! Die Hohepriesterin dort, Laurena, sagt, es sei an der Zeit für Euch zu beweisen, dass Ihr der nächsten Stufe Eurer Ausbildung würdig seid. Verschwendet nicht zu viel Zeit auf dem Weg dorthin. Ihr könnt sie in der Kathedrale des Lichts im Zentrum der Stadt finden. Überbringt Ihr meine Wünsche und beweist, wie würdig Ihr eines solchen Rufes seid. Das Licht sei mit Euch, {name}.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", completion = "Schön, dass Ihr angekommen seid, {name}. Es gibt viele Dinge, die wir erörtern müssen, aber noch wichtiger ist Eure Ausbildung in den Dingen des Lichts.\n\nEs gibt Lektionen, die alle Diener des Lichts lernen müssen. Wenn Ihr bereit seid, werden wir nun damit beginnen, einige davon zu erörtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5640] = { id = 5640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweifeltes Gebet", description = "Gepriesen seien Elune und Euer Licht, {name}.\n\nZurzeit erlernen viele unseres Ordens Fähigkeiten, die ihren Glauben an Elune widerspiegeln. Wenn ich mich nicht irre, gilt das Gleiche auch für Euren Orden.\n\nWenn Eure Angelegenheiten in Darnassus abgeschlossen sind, solltet Ihr eine Eurer Hohepriesterinnen zur weiteren Ausbildung aufsuchen.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5641] = { id = 5641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchtlos", sourceObjective = "Aus Euch könnte ein großartiger {class} werden, {name}. Leistet weiter so gute Arbeit!\n\nIhr habt bereits bewiesen, dass Ihr bereit für die Schlacht seid. Vielleicht ist es an der Zeit, Euch ein wenig mehr beizubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5642] = { id = 5642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwache", description = "In Orgrimmar geht etwas Wichtiges vor, {name}.\n\nNormalerweise sind die Boten, die hier durchkommen und nach Trollpriestern suchen, recht umgänglich. Dieses Mal schienen sie jedoch in großer Eile zu sein. Trödelt nicht zu lange in Donnerfels herum. Ich würde so schnell wie möglich zum Tal der Geister zurückkehren.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5643] = { id = 5643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwache", description = "Wie viele unserer eigenen Priester werdet Ihr von Eurem Stamm durch die Initiationsriten geführt. Diese Riten lehren Priester häufig besondere Fähigkeiten, die wichtig für ihr Überleben sind. Ich spüre, dass die Zeit jetzt an Euch ist, jetzt, in diesem Augenblick. Ihr müsst zum Tal der Geister in Orgrimmar zurückkehren und mit Ur'kyo sprechen. Was er Euch lehrt, kann für die Zukunft sehr wichtig sein.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", completion = "Einer der wichtigsten Initiationsriten für einen {class} unseres Glaubens liegt vor uns, {name}. Ich werde Euch mehr erklären... Ihr seid dazu bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[5644] = { id = 5644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingende Seuche", description = "Ah, ein wundervoller Tag für Euch, {name}. Aufgrund der Lektionen, die Ihr gelernt habt, kann ich sehen, dass die Zeit gekommen ist, Euch zu Aelthalyste zurückzuschicken. Es gibt Dinge, die nur sie Euch beibringen kann, und auch das nur, wenn Ihr Euch als würdig erweist.\n\nIch werde die Überraschung für Euch nicht verderben, aber ich erinnere mich daran, wie es war, als ich ein junger Priester war und etwas über die wahre Macht lernte...die göttliche Macht. Ja, das waren noch Zeiten.\n\nKehrt zu Aelthalyste nach Unterstadt zurück, {name}. Sie erwartet Euch im Kriegsviertel.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", completion = "Gut, Ihr seid zurückgekehrt, und das nicht einen Moment zu spät. Wir haben große Dinge zu erörtern, {name}. Eure Fähigkeiten werden stärker und wir müssen sicherstellen, dass Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[5645] = { id = 5645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchtlos", description = "{name}, Euer Hohepriester Rohan erwartet Euch zu einer Audienz in Eisenschmiede. Beeilt Euch, Eure nächste Prüfung rückt schnell näher. Auch wenn ich wünschte, dass ich Zeuge der besonderen Riten Eures Volkes sein könnte, ist mein Platz doch hier. Aber möge das Licht während Eurer Reisen mit Euch sein. Rohan sollte sich noch im Mystikerviertel befinden, wenn Ihr die Stadt erreicht. Er wird Euch erwarten.", sourceObjective = "Sprecht mit Hohepriester Rohan in Eisenschmiede.", completion = "Es ist schön, dass Ihr gekommen seid, {name}. Unser Volk ist stolz und stark und es wird Zeit, dass Ihr nicht nur lernt, selbst stolz und stark zu sein, sondern auch, solche Gefühle und Vertrauen in anderen zu wecken. Seid Ihr bereit, Bursche?", sourceObjectiveStatus = "unverified-source-field" }
quests[5646] = { id = 5646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingende Seuche", description = "Aelthalyste bezeugt unserem Volk großen Respekt, indem sie unsere Leute zur weiteren Ausbildung zu mir schickt, und nun tue ich dasselbe für ihren Stamm.\n\nKehrt nach Unterstadt zurück, {name}. Dort, im Kriegsviertel, wartet sie auf Euch und ist bereit, Euch mehr über Euer Volk und seine Wege zu lehren. Begebt Euch dorthin und zögert nicht lange.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", completion = "Gut, Ihr seid zurückgekehrt, und das nicht einen Moment zu spät. Wir haben große Dinge zu erörtern, {name}. Eure Fähigkeiten werden stärker und wir müssen sicherstellen, dass Ihr bereit seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[5647] = { id = 5647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furchtlos", description = "Euer Volk ist sehr stark, {name}. Wir sind stolz darauf, Euch Verbündete nennen zu können. Mit jedem Sonnenuntergang nähert Ihr und Eure Art Euch nicht nur Euren wahren Wurzeln, sondern seid auch immer sicherer, dass Ihr in sehr vielen Belangen auf dem richtigen Weg seid. Das muss Euch ein so wunderbares Gefühl geben.\n\nErst vor Kurzem erhielten wir eine Nachricht aus Eisenschmiede. Sie besagte, dass Ihr dorthin zurückkehren und mit dem Hohepriester Rohan im Mystikerviertel sprechen sollt. Ich würde ihn nicht warten lassen. Möge Elune Eure Reisen leiten.Ihr erlernt:", sourceObjective = "Sprecht mit Hohepriester Rohan in Eisenschmiede.", sourceObjectiveStatus = "unverified-source-field" }
quests[5648] = { id = 5648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder der Spiritualität", description = "Ihr seid bereit für Eure erste Prüfung, {name}. Südlich von Klingenhügel, direkt vor der Stadt, wurde eine Grunzerin verletzt, als sie einige von Prachtmeers alten Truppen bekämpfte. Es geht ihr nicht allzu gut und es wäre wirklich gut, wenn einer unserer Art ihr helfen könnte. Sucht sie - ihr Name ist Kor'ja -, heilt ihre Wunden und gebt ihr den Segen unserer Vorfahren.\n\nWenn Ihr das tut, sehe ich das als ausreichenden Beweis dafür an, dass Ihr bereit seid, unseren Pfad weiter zu beschreiten.", sourceObjective = "Findet die Grunzerin Kor'ja und heilt ihre Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt sie danach mit 'Machtwort: Seelenstärke' und kehrt dann zu Tai'jin in Klingenhügel zurück.", completion = "Gut, Kor'ja lebt also und zieht los, um unsere Stadt gegen diese bösartigen Menschen zu verteidigen. Ich wünsche mir oft, mich an die Schlachten vergangener Tage zurückzuerinnern; als Macht noch im Kampf gezeigt wurde und es oftmals der Weise war, der diejenigen vernichtete, die sich nur auf ihre Stärke verließen.\n\nIhr habt Eure Sache meiner Meinung nach gut gemacht, {name}. Nehmt jetzt diese Robe. Ob sie hilft oder ob sie Euch egal ist, Ihr habt sie Euch jedenfalls verdient, und ich bin stolz, Euch Bruder zu nennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5649] = { id = 5649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Spiritualität geneigt", description = "Ja, Mann. Unser Volk hat sich der Horde angeschlossen, weil sie gut für uns ist. Die da sind loyal und lehren uns viel über Dinge wie Ehre. Aber unsere alten Gewohnheiten sterben nur langsam. Die Orcs mögen nicht alle unsere Traditionen billigen, aber das bedeutet nicht, dass wir einige davon nicht im Geheimen ausüben können.\n\nIhr wisst das, und darum schicke ich Euch zu Tai'jin in Klingenhügel. Sie wird Euch mehr über unsere Geschichte lehren. Sie wird Euch in den Wegen unseres Stammes unterrichten. Geht zu ihr, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Tai'jin in Durotar.", completion = "Ahhh... Ihr seid also endlich zu Tai'jin gekommen. Das ist gut.\n\nIhr wisst bereits, dass wir nicht der gleiche Stamm sind, der sich einst der Horde angeschlossen hat. Wir sind jetzt viel stärker. Wir sind stärker, weil wir uns anpassen - das hat uns die Horde gelehrt. Wir besiegen unsere Feinde nicht mehr, um durch sie dann an Kraft zu gewinnen; jetzt gewinnen wir an Kraft und besiegen dann unsere Feinde.\n\nDer Unterschied mag fein sein, aber Ihr werdet es lernen. Ihr werdet es sehen. Der Stamm zählt auf Euch, dass Ihr solche Dinge lernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5650] = { id = 5650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewänder der Dunkelheit", description = "Unsere Macht beziehen wir aus der Dunkelheit und dem Schatten, {name}, doch das ist nicht Eure einzige Rolle. Ihr habt erkannt, dass es von Vorteil ist, sich in der Heilkunst auszukennen. Das ist weise. Doch bevor Ihr die Dunkelheit kennen lernen könnt, müsst Ihr erst das Licht kennen. Und daher habe ich eine Prüfung für Euch.\n\nNördlich des Friedhofs befindet sich eine verwundete Todeswache - Todeswache Kel. Er hat uns seit geraumer Zeit vor Gnollen beschützt und braucht Heilung. Doch Ihr müsst auch seinen Körper stärken, bevor er seinen Dienst wieder aufnehmen kann. Tut beides mit Euren Zaubern und kehrt dann zu mir zurück.", sourceObjective = "Findet die Todeswache Kel und heilt seine Wunden mithilfe von 'Geringes Heilen' (Rang 2). Belegt ihn danach mit 'Machtwort: Seelenstärke' und kehrt zum dunklen Kleriker Beryll in Brill zurück.", completion = "Ihr habt meine Prüfung mit Leichtigkeit bestanden. Gut.\n\nBald werdet Ihr bereit sein, mehr Verantwortung zu übernehmen, und dieser Weg wird Euch zu dunkleren Kräften führen... Kräfte, die kein {class} eines anderen Volkes besitzt.\n\nNehmt diese Robe als Symbol Eures Standes. Ihr habt sie Euch verdient. Wenn Ihr sie nicht tragen wollt, dann sei es so, Ihr könnt damit tun, was Ihr wollt. Ich und andere wie wir werden Euch immer Anerkennung dafür zollen, was Ihr in unseren Reihen erreicht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5651] = { id = 5651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dunkelheit geneigt", description = "Es gibt viele Lektionen, die die Verlassenen durch Erfahrung gelernt haben... Dinge, die einige Völker allenfalls erahnen können. Und obwohl unser Weg in Dunkelheit liegt, werdet Ihr feststellen, dass sehr viele Dinge sowohl vom Licht als auch von der Dunkelheit abhängen. Eure Lektionen sollen Euch lehren, beides zu nutzen... mit Umsicht. Aber beachtet meine Worte: vergesst nie, wir wurden in die Verderbnis gezwungen und der Fäulnis überlassen wie ein Stück Aas. Die Dunkelheit ist unser Heim.\n\nSucht den Dunklen Kleriker Beryll in Brill auf, wenn Ihr bereit seid, mehr zu erfahren.", sourceObjective = "Sprecht mit dem Dunklen Kleriker Beryll in Tirisfal.", completion = "Endlich seid Ihr da. Euer Glaube allein wird Euch nicht helfen, die Aufgaben zu bewältigen, die vor Euch liegen. Etwas Dringlichkeit und ein wenig Ehrgeiz helfen auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[5652] = { id = 5652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", sourceObjective = "Ihr tätet gut daran, diese Lektion zu beachten. Die Verhexung der Schwäche wird Euch im Kampf von großem Nutzen sein. Später werde ich Prüfungen für Euch bereithalten, mit Hilfe derer Ihr Euch weiterentwickeln und Euren Wert für den Stamm beweisen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5654] = { id = 5654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", description = "Es ist an der Zeit, Euch mit Ur'kyo zu treffen, {name}. Er befindet sich im Tal der Geister in der Stadt der Orcs. Geht dorthin und sprecht mit ihm. Es ist an der Zeit, dass Ihr mehr über die alten Wege unserer Art lernt. Es wird Zeit, dass Ihr in den Kreis eingeführt und zu einem wahren Priester unseres Stammes gemacht werdet.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", completion = "Ah, gut, da seid Ihr ja. Wir können Eure Ausbildung in den alten Wegen beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5655] = { id = 5655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", description = "Ich wurde hergeschickt, um sicherzustellen, dass Ihr Euch nicht zu sehr von der Heimat entfernt, {name}. Sie haben mich geschickt, um sicherzustellen, dass Ihr nach Hause zurückkehrt, da Ur'kyo, der größte unserer Priester, mit Euch zu sprechen wünscht. Begebt Euch dorthin. Begebt Euch zum Tal der Geister in der Stadt der Orcs und sprecht mit Ur'kyo. Er wartet auf Euch.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5656] = { id = 5656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", description = "Es erwärmt immer mein nicht sterbendes Herz, Priester aus allen Kulturen zu sehen, die durch die Welt ziehen. Zu wissen, dass Macht existiert, die nicht arkan und sehr wohl in unserer Reichweite ist. Daher ist es mir eine Ehre, Euch nach Hause zu schicken, {name}.\n\nUr'kyo, Euer großer Priester in Orgrimmar, bittet um Eure Anwesenheit. Ihr findet ihn im Tal der Geister.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5657] = { id = 5657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verhexung der Schwäche", description = "Nach Hause. Kehrt nach Hause zurück, {race}.\n\nEuer spiritueller Anführer Ur'kyo bittet Euch, zu ihm zurückzukehren und mit ihm über den Weg zu sprechen, den Ihr geht.\n\nBegebt Euch zum Tal der Geister in der großen Hordenstadt Orgrimmar. Dort werde Ihr ihn finden.", sourceObjective = "Sprecht mit Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5658] = { id = 5658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", sourceObjective = "Ah, junger {class}, ich bin froh, dass Ihr hierher zurückgekehrt seid. Ich würde Euch gerne eine Lektion lehren, die Ihr besser nicht vergessen solltet. Seid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[5660] = { id = 5660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", description = "Ihr seid weit weg von zu Hause, {class}. Ihr werdet dort gebraucht, dort, in Eurer Stadt unter dem Boden. Eure Meisterin, diejenige, die Ihr Aelthalyste nennt, braucht Euch dort. Genau wie bei meinem Stamm gibt es dort Dinge, die Ihr nur von ihr lernen könnt. Bleibt nicht zu lange hier. Ihr solltet Euch zum Kriegsviertel begeben, so schnell ein Zeppelin Euch tragen kann.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5661] = { id = 5661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", description = "Ihr seid weit weg von zu Hause, hier im Dorf der Bluthufe, {name}. Ich wurde hierher geschickt, um Priester meines eigenen Stammes zu finden und sie zurückzuschicken, um mit unseren Anführern zu sprechen, aber das bedeutet nicht, dass ich Euch nicht auch helfen kann.\n\nIch habe gehört, dass der Geist Eurer führenden Priesterin möchte, dass alle Verlassenen zu ihr kommen - es gibt Dinge, die Ihr lernen müsst.\n\nTrefft Euch mit Aelthalyste im Kriegsviertel, in Eurer Stadt.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5662] = { id = 5662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", description = "Mein Respekt gilt Euch und Eurer Art, {name}. Normalerweise lehre ich nur die meines eigenen Stammes. Eure Lektionen kommen von Aelthalyste in der Stadt, die einst Lordaeron genannt wurde.\n\nIhr solltet zur ihr zurückkehren, wenn Ihr die Fähigkeiten erlernen wollt, die Euch von anderen Glaubensrichtungen abgrenzen.\n\nBegebt Euch ins Kriegsviertel in Unterstadt und sucht dort nach Eurer Meisterin.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5663] = { id = 5663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berührung der Schwäche", description = "Aelthalyste schickte eine Nachricht an alle ihre Priester. Wir sollen die Jüngeren unseres Ordens für die weitere Ausbildung nach Unterstadt schicken. Wenn Ihr Euch wahrlich zu unseren Gläubigen zählt, dann solltet Ihr auch dorthin zurückkehren.\n\nIhr könnt Aelthalyste im Kriegsviertel in Unterstadt finden.", sourceObjective = "Sprecht mit Aelthalyste in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5672] = { id = 5672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Anmut", sourceObjective = "Indem Ihr Euch Elune und unserem Volk widmet, habt Ihr einen Status erreicht, den nicht alle von uns erlangen können. Es ist Tradition, dass Euch nun noch größere Fähigkeiten für Eure Hingabe gelehrt werden sollen. Nehmt Ihr an?", sourceObjectiveStatus = "unverified-source-field" }
quests[5673] = { id = 5673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Anmut", description = "Ihr wisst, dass Ihr jederzeit zu jedem unserer Lehrer Zugang habt, {name}, aber es gibt einige Dinge, die wir nicht an Euch weitergeben können. Eines dieser Dinge sind die Lehren der Göttin Elune. Sie verleiht ihren Getreuen spezielle Fähigkeiten, und wenn ich mich nicht irre, ist es an der Zeit, dass Ihr nach Hause zu Eurem Tempel des Mondes zurückkehrt, um geprüft zu werden.\n\nKehrt dorthin zurück, wenn Ihr könnt, und sprecht mit der Priesterin Alathea.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", completion = "Elune segne Euch für Eure schnelle Rückkehr zu uns. Dies ist eine bedeutende Zeit für Eure Ausbildung und eine Zeit, die unser gesamter Orden sehr ernst nimmt. Wenn Ihr Euch von Eurer Reise hierher erholt habt, dann lasst es mich wissen. Wir können dann die Fortführung Eurer Ausbildung erörtern und die Frage, wohin Euch Euer Weg als Nächstes führen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[5674] = { id = 5674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Anmut", description = "Ein wunderbarer Tag ist gekommen, {name}. Ihr habt das Alter erreicht, in dem unsere <Priester/Priesterinnen> in Fähigkeiten ausgebildet werden, die nur die Nachtelfen kennen. Aber es ist nicht an mir, Euch auszubilden. Ihr müsst zum Tempel des Mondes zurückkehren und mit der Priesterin Alathea sprechen, sobald Ihr Eure Angelegenheiten hier abgeschlossen habt. Sie wird Euch prüfen, um sicher zu sein, dass Ihr bereit seid, und erst dann wird sie Euch Elunes Anmut lehren.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5675] = { id = 5675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Anmut", description = "Die Zeit verrinnt, <Bursche/Mädel>. Es ist an der Zeit, dass Ihr nach Darnassus heimkehrt. Die Priesterin Alathea ließ uns wissen, dass Ihr dorthin zur Ausbildung zurückkehren sollt. Es scheint, als wärt Ihr bereit, getestet zu werden, so wie jene, die dem Licht dienen. Ihr solltet Euch dorthin begeben, sobald Ihr könnt. Alatheas Nachricht besagte, dass sie im Tempel des Mondes auf Euch wartet. Viel Glück.", sourceObjective = "Sprecht mit der Priesterin Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5676] = { id = 5676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rückkopplung", sourceObjective = "Wir waren gezwungen, einige Magien zu lernen, um uns vor dem zu schützen, was üblicherweise unser stärkster Feind genannt wird: dem Arkanen.\n\nIch würde Euch einen Zauber beibringen, um Euch und Euren Kameraden bei der Verteidigung gegen diejenigen zu helfen, die diese Macht einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5677] = { id = 5677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rückkopplung", description = "So gern ich Euch auch unsere eigenen speziellen Lehren des Lichts zeigen würde, so ist dies doch nicht an uns. Ihr müsst zurück nach Sturmwind, zu Eurer eigenen Art, {name}... zumindest vorerst. Glaubt mir, es war nicht böse gemeint. Wenn Ihr zur Hohepriesterin Laurena in die Kathedrale des Lichts zurückkehrt, werdet Ihr verstehen, worüber ich spreche... Die Zeit ist für Euer Volk gekommen, Euch auf die Zukunft vorzubereiten, Euch von den anderen abzuheben, die einem ähnlichen Weg folgen.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5678] = { id = 5678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Rückkopplung", description = "Es ist an der Zeit für Euch, nach Sturmwind zurückzukehren. Eure Vorgesetzten dort haben Euch zur Ausbildung zurückgerufen. Und obwohl mich das ein wenig verstört, so sind Euer Volk und meines doch Verbündete und ich würde niemals Verrat an diesem Bündnis begehen.\n\nIch möchte Euch gegenüber offen sein...Mein Argwohn jeglicher arkanen Magie gegenüber, möge sie nun göttlich inspiriert sein oder nicht, ist immer noch stark in mir.\n\nIhr werdet verstehen, wovon ich spreche, wenn Ihr zu Eurer Kathedrale des Lichts zurückkehrt. Sprecht mit der Hohepriesterin Laurena, wenn Ihr dort ankommt.", sourceObjective = "Sprecht mit der Hohepriesterin Laurena in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[5679] = { id = 5679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlingende Seuche", sourceObjective = "Ich würde Euch 'Verschlingende Seuche' beibringen, wenn Ihr Euch bereit dazu fühlt, {name}. Dieser Spruch ist nicht gerade von kleiner Macht und wird Euch in den kommenden Schlachten helfen. Übt damit - es wird später Prüfungen dazu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[5680] = { id = 5680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenwache", sourceObjective = "Eure Riten werden bald kommen. Fürs Erste lehre ich Euch einen Zauber, der Euch von großem Nutzen sein wird, wenn Ihr mit Euren Feinden kämpft.", sourceObjectiveStatus = "unverified-source-field" }
quests[5713] = { id = 5713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schuss, ein Treffer", description = "Ich war mit einer wichtigen Nachricht auf dem Weg nach Lor'danel, als ich von dem Furbolg Marosh und seinen Fährtenlesern angegriffen wurde. Während des Angriffs wurde ich vergiftet, wodurch ich kaum noch stehen konnte. Ich kann ein Gegengift herstellen, aber es wird eine Zeit dauern, bis es bereit ist.\n\nIch möchte Euch bitten, mich zu verteidigen, bis ich das Gegengift anwenden kann. Ich werde Euch, so gut es geht, mit meinem Bogen helfen.\n\nFalls wir überleben, kann ich meine Botschaft nach Lor'danel überbringen, während Ihr mit Onaeya bei Maestras Posten sprecht, um sie von diesem Vorfall zu unterrichten.", sourceObjective = "Schützt die Schildwache Aynasha und sprecht dann mit Onaeya bei Maestras Posten im Eschental.", completion = "Ihr bringt sehr willkommene Neuigkeiten, {class}. Es ist gut zu hören, dass Aynasha lebt, und ich danke Euch dafür. Ich hoffe, dass Ihr eine Belohnung für Eure edlen Bemühungen annehmt. Möge Elune über Euch wachen und Euren Weg erleuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[5721] = { id = 5721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Darroheim", description = "Nun, {name}, Ihr werdet an der Schlacht von Darroheim teilnehmen und Joseph Rotpfad retten.\n\nPlatziert dieses Reliktbündel auf dem Marktplatz von Darroheim, und die Geister von Darroheim werden sich erheben. Nehmt an der Schlacht teil und sorgt dafür, dass die folgenden zwei Dinge eintreten: Davil muss den Tod von Horgus überleben und Rotpfad muss überleben, um erst verdorben und dann besiegt zu werden.\n\nNachdem Ihr den verderbten Rotpfad besiegt habt, wird seine Seele gerettet sein. Sprecht mit ihm und kehrt dann zu seiner Tochter Pamela zurück.", sourceObjective = "Legt das Reliktbündel auf den Marktplatz von Darroheim.\n\nVerhindert Davil Lichterscheins Tod, bis Horgus stirbt.\n\nVerhindert Hauptmann Rotpfads Tod, bis Rotpfad der Verderbte erscheint.\n\nBesiegt Rotpfad den Verderbten.\n\nSprecht mit dem Geist von Joseph Rotpfad, sobald er auf dem Marktplatz erscheint, und sprecht dann mit Pamela in ihrem Zuhause.", completion = "Der Kampf ist vorüber! Ich habe meinen Vater zu mir flüstern hören. Er hat alle Geister verjagt und sagt, dass er nach Hause käme! Ich bin so froh!\n\nEr sagte außerdem, dass ich Euch willkommen heißen sollte, wenn Ihr zu uns nach Hause kommt, daher habe ich Euch etwas Tee zubereitet!\n\nIch hoffe, Ihr mögt ihn mit viel Zucker!", sourceObjectiveStatus = "unverified-source-field" }
quests[5722] = { id = 5722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach dem verloren gegangenen Ranzen", description = "Die Troggs sind nicht das Einzige, das Magatha im Flammenschlund interessierte. Sie hatte gehört, dass einer ihrer Diener, ein gewisser Maur Grimmtotem, im Abgrund etwas Sonderbares gefunden haben soll, nur leider schaffte er es nicht mehr, lebend herauszukommen, um ihr davon zu berichten. Sie möchte, dass Maurs Leiche - falls sie noch existiert - geborgen wird...und auch jegliche Hinweise auf das, was er entdeckt haben könnte, als er versuchte, mit den Troggs zu sprechen.\n\nBringt Magatha Gegenstände, die sie interessieren könnten, dann wird sie sich bestimmt mit einer Belohnung nicht kleinlich zeigen.\n\nBegebt Euch noch einmal in den Abgrund im dunkelsten Teil von Orgrimmar.", sourceObjective = "Sucht im Flammenschlund nach Maur Grimmtotems Leiche und durchsucht sie nach interessanten Gegenständen.", completion = "Der Körper scheint von Keulen oder Fäusten übelst zugerichtet worden zu sein, jedoch ist der Großteil der Kleidung und Ausrüstung offenbar noch vorhanden. Die Troggs scheren sich anscheinend nicht besonders um materielle Dinge.\n\nIhr beginnt, den Körper nach etwas Interessantem zu durchsuchen, das Magatha helfen könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[5723] = { id = 5723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kraft des Feindes wird auf die Probe gestellt", description = "Unter der Stadt Orgrimmar haben stämmige Kreaturen, als Troggs bekannt, damit begonnen, sich aus den Tiefen unterhalb der lavagefüllten Tunnel an die Oberfläche zu wühlen. Wie es ihrer grundgütigen Art entspricht, hatte Magatha Frieden mit diesen Kreaturen schließen wollen, doch die Troggs stürzten sich auf ihre Diplomaten und töteten sie. Magatha lässt sich eine solche Behandlung des Taurenvolks nicht gefallen und betrachtet die Kreaturen jetzt als eine Gefahr für die gesamte Horde.\n\nSie bittet Euch, der Gefahr durch die Troggs ein Ende zu machen, bevor sie die Horde von unten überwältigen. Geht zum Flammenschlund und vernichtet sie alle.", sourceObjective = "Sucht in Orgrimmar nach dem Flammenschlund, tötet dann 8 Flammenschlundtroggs und 8 Schamanen der Flammenschlundtroggs und kehrt anschließend zu Rahauro in Donnerfels zurück.", completion = "Ich freue mich, dass Ihr Magathas Auftrag so ernst genommen habt. Ich danke Euch, {name}. Den Troggs wird es jetzt bestimmt schwerer fallen, an die Oberfläche zu gelangen, denn ihre Zahl wurde beträchtlich reduziert.\n\nVielleicht können wir uns in der Zukunft etwas Zeit nehmen und herausfinden, woher diese Kreaturen kamen und was sie eigentlich wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5724] = { id = 5724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederbeschaffung des verloren gegangenen Ranzens", description = "Unter dem Körper des Tauren findet Ihr einen Ranzen. Er hält ihn immer noch fest an sich gedrückt, als hätte er ihn beim Angriff der Troggs schützen wollen.\n\nIhr befreit den Ranzen aus seinem Klammergriff und verstaut ihn bei Eurer eigenen Ausrüstung, dann bereitet Ihr Euch darauf vor, die Tunnel zu verlassen und zu Rahauro in Donnerfels zurückzukehren.", sourceObjective = "Bringt den Grimmtotemranzen zu Rahauro nach Donnerfels.", progress = "Habt Ihr irgendwas gefunden, {name}? Jeder Hinweis darauf, warum einer ihrer Klanangehörigen unnötig sterben musste, wäre hilfreich.", completion = "Ausgezeichnet, {name}. Danke.\n\nMagatha sagte mir, dass Ihr dies hier bekommen sollt, wenn Eure Suche nach ihrem Klanangehörigen erfolgreich war. Bitte, nehmt das als Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[5725] = { id = 5725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht zu Zerstören...", description = "Viele Angehörige der Legion bedenken ihre Anhänger mit Geschenken, wie Ihr bestimmt wisst. Manche dieser Geschenke wären nach Ansicht der Dunklen Fürstin besser in der Hand von Leuten aufgehoben, die... weniger Visionen haben.\n\nEine Sekte des Schattenrates, die sich die Sengende Klinge nennt und sich in den Höhlen unterhalb Orgrimmars versteckt, ist ein Musterbeispiel dafür. Die Fürstin sagte mir, dass Mitglieder der Sengenden Klinge in den Besitz zweier sehr mächtiger Zauberbücher gelangt seien... und sie möchte sich diese Bücher von ihnen 'borgen'. Ihr werdet sie ihr beschaffen.", sourceObjective = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Varimathras nach Unterstadt.", progress = "Ich muss mich noch um Hunderte anderer Dinge kümmern, {class}. Habt Ihr die Bücher?", completion = "Gut, {class}. Ihr habt der dunklen Fürstin gut gedient. Mit Eurer unablässigen Beharrlichkeit und Eurem Ehrgeiz habt Ihr viel für die Untertanen der Fürstin geleistet. Besucht mich irgendwann einmal wieder. Vielleicht habe ich dann ja neue Aufgaben für Euch, die der dunklen Fürstin bei ihren Versuchen, den Lichkönig zu stürzen und die Geißel endgültig zu befreien, helfen könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[5726] = { id = 5726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Eines werde ich in meinen Reihen auf keinen Fall dulden, {name}: Verräter. Ich wäre allerdings töricht, würde ich meine Trümpfe einfach so ausspielen. Die Geschwüre der Verderbnis in unserem Land würden nicht tief genug herausgeschnitten und die Infektion würde sich noch verschlimmern.\n\nAber Ihr, ein junger Abenteurer, könntet dorthin gehen, wo es meinen Agenten nicht möglich ist... könntet die Wahrheit ans Licht bringen... herausfinden, wer wirklich hinter dieser Bestie steckt.\n\nWenn Ihr mutig genug seid, geht zur Knochenhöhle östlich von Orgrimmar, besorgt mir das Insigne eines Offiziers der Brennenden Klinge dort und kehrt zu mir zurück.", sourceObjective = "Bringt ein Insigne des Leutnants zu Thrall nach Orgrimmar.", progress = "Habt Ihr die Insignie schon, {name}?\n\nSie wäre ein wichtiges Hilfsmittel, damit Ihr dort eindringen könnt, wo ich die größte Gefahr für die Horde vermute und damit wir in unserer neuen Heimat endlich Frieden finden.\n\nIhr werdet sehen, wie komplex das Netz sein kann, das Menschen und Orcs gemeinsam weben können, wenn sie von Gier und Machthunger angetrieben werden. All die geheimen Pläne, die Verderbnis, all das wird dann klar werden. Ihr werdet Euch in der Mitte eines Krieges wiederfinden, von dem Ihr gar nicht wusstet, dass er überhaupt existiert.", completion = "Gut, {name}! Die Geister seien gepriesen. Vielleicht seid Ihr derjenige, der mich endlich von meinen größten Sorgen befreien kann! Wer hätte gedacht, dass jemand, der so jung und doch so mutig ist, sich erheben und unsere Sache verfechten würde? Ihr erinnert mich an mich selbst, als ich noch jünger war. Ich werde dafür sorgen, dass Ihr den gerechten Lohn für Eure Mühen bekommt, falls wir den aufziehenden Sturm überleben.\n\nWeitere Lobeshymnen heben wir uns für später auf. Bis jetzt habt Ihr nicht viel geleistet im Vergleich zu dem, was Euch noch erwartet... aber es ist ein guter Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[5727] = { id = 5727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Und jetzt lasst uns sehen, ob das Insigne, das Ihr gefunden habt, der Mühe wert ist.\n\nIn der Stadt gibt es einen Hexenmeister, der seiner Meinung nach mein Vertrauen genießt. Er weiß allerdings nicht, dass ich gewahr bin, wem er wirklich die Treue hält. Tatsächlich ist er der Anführer der Brennenden Klinge. Aber stürzt Euch jetzt nicht übereilt in einen Kampf mit ihm. Er könnte nützlich sein und wir werden ihn gegen unsere Feinde einsetzen.\n\nBringt dieses Insigne zu ihm in die Kluft der Schatten hier in Orgrimmar. Sprecht mit ihm, seht, ob er Euch für einen der Ihren hält, und kommt dann zu mir zurück.", sourceObjective = "Bringt Neeru Feuerklinge das Insigne des Offiziers und sprecht mit ihm. Seht, ob er Euch glaubt, dass Ihr ein Mitglied der Brennenden Klinge seid, und kehrt dann zu Thrall nach Orgrimmar zurück.", progress = "Also, {class}? Hat er uns unsere Finte abgenommen oder ist die Sache doch schlimmer, als ich zuerst angenommen habe?\n\nWenn wir uns für Neeru als nützlich erweisen, wird uns das die Unterwanderung des Schattenrates erleichtern. Wir werden an eine Menge Informationen herankommen, die wir nutzen können, um all jene auszurotten, die das zu zerstören versuchen, was wir in Durotar aufgebaut haben.", completion = "Exzellent! Sehr eindrucksvoll, {class}!\n\nWas Euch heute gelungen ist, ist nur der erste Schritt zur Legung eines noch größeren Fundaments - eines Fundaments, auf dem wir die endgültige Zerstörung des Schattenrates aufbauen.\n\nErzählt mir alles, was er gesagt hat... und lasst auch nicht ein einziges Wort aus, denn es könnte wichtiger sein, als Ihr glaubt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5728] = { id = 5728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Hmmm, Anführer der Sengenden Klinge... das beunruhigt mich zutiefst. Wenn sie es sind, die für Neeru zählen, dann sollten sie auch unser erstes Ziel sein. Dieser Satyr... Bazzalan, und der andere, den Neeru erwähnte... Was war er doch gleich, ein Hexenmeister? Sie müssen vernichtet werden.\n\nKehrt zur Kluft der Schatten zurück und begebt Euch in den Flammenschlund, {name}. Findet diese beiden Anführer der Sengenden Klinge und tötet sie. Aber seid vorsichtig, damit Neeru nicht erfährt, wer das getan hat. Er muss Euch auch weiterhin für <seinen Kampfgenossen/seine Kampfgenossin> halten.", sourceObjective = "Tötet Bazzalan und Jergosh den Herbeirufer, bevor Ihr zu Thrall nach Orgrimmar zurückkehrt.", completion = "Schön, dass Ihr zurück seid, {name}. Ein paar derer, die mir immer noch treu ergeben sind, haben mich sofort davon unterrichtet, dass die Höhlen unter Orgrimmar in Aufruhr sind, nachdem die Anführer vernichtet wurden. Berichten zufolge soll Neeru ziemlich beunruhigt sein. Es scheint, als hätten wir seiner Rüstung eine Delle verpasst. Ich kann sagen, dass ich doch recht zufrieden bin ... auch mit einem kleinen Sieg wie diesem.", sourceObjectiveStatus = "unverified-source-field" }
quests[5729] = { id = 5729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Ich glaube, unser nächster Schritt sollte sein, Euch in Neerus Nähe unterzubringen. Falls er wirklich so beunruhigt ist, wie die Berichte vermuten lassen, könnten wir zwei Fliegen mit einer Klappe schlagen. Erstens könntet Ihr mehr über den Rat oder zumindest die Sengende Klinge in Erfahrung bringen, und zweitens könnte er Euch möglicherweise genug vertrauen, um Euch zu bitten, ihm zu helfen. Vielleicht wird er Euch für jemanden halten, der die Lücken füllt, die der Tod der Anführer gerissen hat.\n\nKehrt zur Kluft zurück und sprecht noch einmal mit ihm, aber haltet Euch bedeckt.", sourceObjective = "Sprecht mit Neeru Feuerklinge in Orgrimmar.", completion = "Was ist? Oh, Ihr seid es, {class}... Verzeiht mir. Ich bin so wütend wie ein tollwütiger Kodobulle... aber daran bin ich wahrscheinlich selbst schuld. Ich habe Reisende zum Ragefireabgrund geschickt und hätte doch wissen müssen, dass sich daraus Probleme ergeben könnten. Es scheint, als hätten ein paar von Thralls Weltverbesserern Bazzalan und Jergosh überrumpelt und erschlagen. Ein äußerst ungünstiger Zeitpunkt, aber daran ist jetzt nichts mehr zu ändern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5730] = { id = 5730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgene Feinde", description = "Ihr seid einer meiner Offiziere! Macht Euch bereit, {class}. Ich werde Euch bald benötigen.\n\nDie Zeit, die ich für die Sengende Klinge aufgebracht hatte, war jetzt vielleicht reine Zeitverschwendung, aber das bedeutet nicht, dass die restlichen Pläne des Schattenrates darunter leiden müssen. Ich werde tun, was ich kann, um den Schaden hier im Flammenschlund zu begrenzen. In der Zwischenzeit sollen meine Agenten im Brachland und im Eschental mit der Arbeit an unserem neuesten Geheimplan beginnen. Kommt bald zu mir zurück.", sourceObjective = "Sprecht in Orgrimmar mit Thrall und berichtet ihm, was Ihr erfahren habt.", completion = "Ashenvale? Hmm, ich hatte nichts von der Anwesenheit des Rates oder der Burning Blade in Ashenvale gewusst. Meine Spione werden das untersuchen, {name}. Das habt Ihr gut gemacht.\n\nJetzt ruht Euch erst einmal aus und beschäftigt Euch mit anderen Aufgaben. Ich werde Euch bald wieder benötigen.\n\nLok-Tar Ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[5741] = { id = 5741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Szepter des Lichts", description = "Die Anhänger der Brennenden Klinge in der Festung Donneraxt im Osten sollen Gerüchten zufolge das Szepter des Lichts von den Naga beschafft haben. Die Legenden besagen, dass das Szepter dazu fähig ist, ganze Städte unter den Ozeanen verschwinden zu lassen. Wir dürfen nicht zulassen, dass die Brennende Klinge solche Macht besitzt.\n\nUm das zu verhindern, müsst Ihr selbst das Szepter bergen! Es ist im Besitz eines Sehers der Brennenden Klinge, der das Szepter in einem der Wachtürme der Feste Donneraxt studiert.", sourceObjective = "Besorgt das Szepter des Lichts und bringt es zurück zu Azore Aldamort am Turm in Ethel Rethor.", progress = "Habt Ihr das Szepter des Lichts?", completion = "Das geheimnisvolle Szepter des Lichts! Dass Ihr es beschafft habt, hat eine große Bedrohung von der Welt abgewendet. Gut gemacht, {class}, gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[5742] = { id = 5742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlösung", description = "Ihr habt sehr hart gearbeitet. Ruht Eure müden Knochen aus und erlaubt mir, mich korrekt vorzustellen.", sourceObjective = "Hört Euch an, was Tirion Fordring zu sagen hat.", progress = "Bitte setzt Euch und hört meine Geschichte.", completion = "Fordring zu erlösen wird sehr schwierig sein. Seid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[5761] = { id = 5761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtung der Bestie", description = "Die vorrangige Aufgabe, die mir unser großer Kriegshäuptling übertragen hat, ist die Vernichtung der Kreaturen, die dafür verantwortlich sind, dass sich der dämonische Einfluss in der großen Stadt unseres Herrschers einnisten konnte. Die Kultisten der Brennenden Klinge sind eine Gefahr, aber es gibt auch noch andere. Die Anhänger der Sengenden Klinge zum Beispiel, die sich im Flammenschlund niedergelassen haben, versuchen insgeheim unschuldige Mitglieder der Horde auf ihre Seite zu ziehen.\n\nUm sie aufzuhalten, muss ihr Anführer beseitigt werden - eine Teufelswache namens Taragaman der Hungerleider.\n\nTötet ihn, und sein Herz wird Thrall beschwichtigen, dessen bin ich mir sicher.", sourceObjective = "Begebt Euch in den Flammenschlund und erschlagt Taragaman den Hungerleider. Bringt anschließend dessen Herz zu Neeru Feuerklinge nach Orgrimmar.", progress = "Habt Ihr die Bestie getötet? Er ist mit Sicherheit der Anführer der Searingblade im Ragefireabgrund.", completion = "Ha! Ihr habt es geschafft! Thrall wird hocherfreut sein.\n\nIch werde dafür sorgen, dass das Herz in die richtigen Hände kommt.\n\nJetzt allerdings solltet Ihr erst einmal Euren Sieg feiern. Ich werde indes Thrall von Eurem Erfolg berichten.\n\nVielen Dank für Eure Hilfe, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[5762] = { id = 5762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hemet Nesingwary Jr.", description = "Ich habe hier eine Sendung für einen alten Kunden von mir, Hemet Nesingwary Jr., ein Zwerg. Die Sendung war wochenlang unterwegs und Hemet ist schon längst wieder weg. Er sagte, dass er ins Schlingendorntal gehen wolle, um die Bestien dort zu jagen, aber er ließ mir etwas Geld da und wollte, dass ich ihm seine Sendung schicke, sobald es mir möglich sei. \n\nJunior ist ein reicher Zwerg und man sollte sich mit den Reichen ruhig gut stellen, findet Ihr nicht auch? Also... könntet Ihr die Sendung für mich zustellen?\n\nWie ich hörte, hat er im Schlingendorntal nördlich von Grom'gol ein Lager aufgeschlagen.", sourceObjective = "Bringt Kravels Kiste zu Hemet Nesingwary Jr. ins Schlingendorntal.", progress = "Ist das da Wüstenstaub an Eurem Kragen?\n\nHm... wenn mich meine Nase nicht täuscht, würde ich sagen, das ist gar kein Wüstenstaub, sondern Wüstensalz! Ihr wart in der schimmernden Ebene, stimmt's?", completion = "Großartig, meine Sendung von Koalbeard! Danke, {name}. Diese Kiste enthält Munition eines ganz besonderen Kalibers, die uns im Dschungel sehr nützen wird!\n\nHier habt Ihr das Geld und sagt mir noch, wie geht's denn dem grantigen alten Kravel so? Führt bestimmt immer noch nichts Gutes im Schilde, möchte ich wetten ...", sourceObjectiveStatus = "unverified-source-field" }
quests[5763] = { id = 5763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd im Schlingendorntal", description = "Vor langer Zeit kam ein Zwerg in dieses Land. Sein Name war Hemet, und er kam, um große Wildtiere zu jagen. Sein Geschick mit Flinten war außergewöhnlich, und wir haben viele Tage zusammen auf der Jagd verbracht. Sogar die Feindschaft zwischen unseren Völkern war vergessen.\n\nAls er ins Schlingendorntal ging, schwor ich, ihn irgendwann einmal wieder willkommen zu heißen. Er ist jetzt zum Jagen in ferne Länder gegangen, aber sein Sohn hat seinen Platz eingenommen.\n\nBringt Hemet Jr. dieses Kodohorn als Geschenk. Ihr findet ihn im Schlingendorntal, nördlich des Basislagers von Grom'gol.", sourceObjective = "Bringt Roons Kodohorn zu Hemet Nesingwary Jr. ins Schlingendorntal.", progress = "Setzt Euch, {class}. Ihr werdet schon bald wieder in den Dschungel zurückmüssen.", completion = "Ah, dieses Horn gehört einem Tauren, Roon Wildmane. Wir hatten sehr viel Spaß, als wir zusammen die Wildtiere von Desolace jagten. Roon lädt mich also ein, ja?\n\nWir stecken zwar momentan bis zum Hals im Dschungel, aber trotzdem danke, {name}. Vielleicht führt mich meine nächste Expedition ja wieder nach Desolace, dem Land der Zentauren.", sourceObjectiveStatus = "unverified-source-field" }
quests[5781] = { id = 5781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von vergessenen Erinnerungen", description = "Wenn Ihr Taelan helfen wollt, zurückzubekommen, was er verloren hat, müsst Ihr Gegenstände aus seiner Vergangenheit zusammentragen.\n\nDer Erste dieser Gegenstände ist ein Spielzeug, das ich ihm zu seinem 7. Geburtstag schenkte. Es war sein wertvollster Besitz. Ein winziger Kriegshammer, die exakte Kopie meines eigenen.\n\nAls man mich wegen Verrats verbannte, erzählte ihm seine Mutter, dass ich gestorben sei. Man brachte ihn zu meinem angeblichen Grab beim Tiefgewölbe, wo er den Hammer zusammen mit seiner Erinnerung an mich begrub - für immer.\n\nIhr müsst Euch zum Tiefgewölbe begeben und Taelans Hammer holen.", sourceObjective = "Begebt Euch zum Tiefgewölbe im südlichsten Abschnitt der Östlichen Pestländer und sucht nach Taelans Hammer. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", progress = "Er muss erlöst werden.", completion = "<Tirion blinzelt, um seine Tränen zurückzuhalten.>\n\nEs war Schicksal, dass wir uns begegneten, {name}. Ihr wart so gut zu mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[5801] = { id = 5801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuersäulen geschmiedet", description = "Ihr braucht zwei Barren Thorium und eine kräftige und sehr heiße Wärmequelle, um den Schaft des Schlüssels zu schmieden. Das Thorium müsst Ihr Euch selbst besorgen, aber mit der Wärmequelle kann ich Euch helfen.\n\nWestlich von hier im Krater von Un'Goro liegt der Feuersäulengrat - ein brodelnder Vulkan. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. Ihr habt mit Eurem Gold eine Form erstanden, die Ihr einfach nur in den See tauchen müsst. Die Lava erledigt dann den Rest.\n\nDas war's von meiner Seite. Um Euren Schlüssel fertig zu stellen, müsst Ihr noch einmal mit Arbington sprechen.", sourceObjective = "Bringt die Dietrichform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Dietrichform am Lavasee, um den unvollendeten Dietrich zu schmieden.\n\nBringt den unvollendeten Dietrich dann zum Alchemisten Arbington an der Zugwindspitze in den Westlichen Pestländern.", progress = "Habt Ihr den Schaft des Skelettschlüssels fertig gestellt? Es tut mir Leid, dass Ihr das Meiste zum Kauf der Form beisteuern musstet, aber wir müssen alle unseren Beitrag leisten, um der Geißel Herr zu werden. Wenn Ihr mir den unvollendeten Schlüssel gebt, seid Ihr für den letzten Gegenstand bereit, der benötigt wird, um die Herstellung des Schlüssels abzuschließen.\n\nEs wird nicht gerade einfach werden, aber die ganze Arbeit, die Ihr bis jetzt zur Vorbereitung eines Angriffs auf Andorhal geleistet habt, wird sich schließlich auszahlen. Ihr werdet schon sehen.", completion = "Da haben wir aber einen ziemlich teuren Skelettschlüssel, was, {name}? Er ist jedoch noch nicht fertig. Jetzt wird es Zeit, uns näher mit unserem Werk zu befassen. Dazu werdet Ihr Euch dem Schlimmsten aller Feinde stellen müssen, mit denen wir auf dem Weg nach Andorhal zu tun hatten ... dem ruchlosen Wesen, das in der Ruine der Stadt die Fäden zieht.\n\nIch spreche von Araj dem Beschwörer ... das ist ein Lich und eines der mächtigsten Wesen aus den Reihen der Geißel.", sourceObjectiveStatus = "unverified-source-field" }
quests[5802] = { id = 5802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuersäulen geschmiedet", description = "Ihr braucht zwei Barren Thorium und eine kräftige und sehr heiße Wärmequelle, um den Schaft des Schlüssels zu schmieden. Das Thorium müsst Ihr Euch selbst besorgen, aber mit der Wärmequelle kann ich Euch helfen.\n\nWestlich von hier im Krater von Un'Goro liegt der Feuersäulengrat - ein brodelnder Vulkan. Der Lavasee an seiner Spitze ist heiß genug, um Thorium und Knochen miteinander zu verschmelzen. Ihr habt mit Eurem Gold eine Form erstanden, die Ihr einfach nur in den See tauchen müsst. Die Lava erledigt dann den Rest.\n\nDas war's von meiner Seite. Um Euren Schlüssel fertig zu stellen, müsst Ihr noch einmal mit Zitters sprechen.", sourceObjective = "Bringt die Dietrichform und 2 Barren Thorium zur Spitze des Feuersäulengrats im Krater von Un'Goro. Benutzt die Dietrichform am Lavasee, um den unvollendeten Dietrich zu schmieden.\n\nBringt den unvollendeten Dietrich zu Apotheker Zitters im Bollwerk in den Westlichen Pestländern.", progress = "Habt Ihr den Schaft des Skelettschlüssels fertig gestellt? Es tut mir wirklich Leid, dass Ihr das Meiste zum Kauf der Form beisteuern musstet, aber wir müssen alle unseren Beitrag leisten, um der Geißel Herr zu werden. Wenn Ihr mir den unvollendeten Schlüssel gebt, seid Ihr für den letzten Gegenstand bereit, der benötigt wird, um die Herstellung des Schlüssels abzuschließen.\n\nEs wird nicht gerade einfach werden, aber die ganze Arbeit, die Ihr bis jetzt zur Vorbereitung eines Angriffs auf Andorhal geleistet habt, wird sich schließlich auszahlen. Ihr werdet schon sehen.", completion = "Da haben wir aber einen ziemlich teuren Skelettschlüssel, was, {name}? Er ist jedoch noch nicht fertig. Jetzt wird es Zeit, uns näher mit unserem Werk zu befassen. Dazu werdet Ihr Euch dem Schlimmsten aller Feinde stellen müssen, mit denen wir auf dem Weg nach Andorhal zu tun hatten ... dem Wesen, das in der Ruine der Stadt die Fäden zieht.\n\nIch spreche von Araj dem Beschwörer ... das ist ein Lich und eines der mächtigsten Wesen aus den Reihen der Geißel.", sourceObjectiveStatus = "unverified-source-field" }
quests[5803] = { id = 5803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arajs Skarabäus", description = "Araj der Beschwörer herrscht von dem ruinierten Herzen der Stadt aus über Andorhal. Wir wissen, dass er der ehemalige Kopf der Scholomance war, bevor er die Stadt an sich riss. Um den Schlüssel fertig zu stellen, benötigen wir sein Signet - Skarabäus genannt. Es wird den Kopf des Schlüssels bilden.\n\nMacht Euch auf den Weg ins Herz von Andorhal und brecht mit seiner Herrschaft über die Stadt, jetzt wo er für uns erreichbar ist. Nehmt den Skarabäus aus seinem Phylakterium, sobald er vernichtet ist!\n\nDer Schlüssel zu Scholomance erwartet Euch, {name}!", sourceObjective = "Zerstört Araj den Beschwörer und bringt Arajs Skarabäus zum Alchemisten Arbington an der Zugwindspitze in den Westlichen Pestländern.", progress = "Ihr seid so weit gekommen, {name}... jetzt steht nur noch die Zerstörung der körperlichen Gestalt von Araj dem Beschwörer zwischen uns und der Fertigstellung des Schlüssels. Ihr müsst Arajs Skarabäus unter allen Umständen an Euch bringen und mir geben - ich werde daraus dann den Kopf des Schlüssels fertigen.", completion = "Ja, perfekt! Ich... ich bin wieder einmal absolut überwältigt, wie heldenhaft Ihr doch seid. Es ist kaum vorstellbar, wie weit zu gehen Ihr bereit seid, um einen Sieg über die Mächte der Finsternis zu erringen.\n\nErlaubt mir jetzt bitte, auch einen kleinen Beitrag dazu zu leisten. Ich habe eine spezielle Tinktur vorbereitet, mit der ich den Skarabäus als Kopf am Schlüssel befestigen kann. Das wird den Schlüssel mit der Kraft erfüllen, die zum Öffnen der verschlossenen Tür in der Scholomance benötigt wird.\n\nAlso dann...", sourceObjectiveStatus = "unverified-source-field" }
quests[5804] = { id = 5804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arajs Skarabäus", description = "Araj der Beschwörer herrscht von dem ruinierten Herzen der Stadt aus über Andorhal. Wir wissen, dass er der ehemalige Kopf der Scholomance war, bevor er die Stadt an sich riss. Um den Schlüssel fertig zu stellen, benötigen wir sein Signet - Skarabäus genannt. Es wird den Kopf des Schlüssels bilden.\n\nMacht Euch auf den Weg ins Herz von Andorhal und brecht mit seiner Herrschaft über die Stadt, jetzt wo er für uns erreichbar ist. Nehmt den Skarabäus aus seinem Phylakterium, sobald er vernichtet ist!\n\nDer Schlüssel zu Scholomance erwartet Euch, {name}!", sourceObjective = "Vernichtet Araj den Beschwörer und bringt Arajs Skarabäus zum Apotheker Zitters im Bollwerk, in den Westlichen Pestländern.", progress = "Ihr seid so weit gekommen, {name}... jetzt steht nur noch die Zerstörung der körperlichen Gestalt von Araj dem Beschwörer zwischen uns und der Fertigstellung des Schlüssels. Ihr müsst Arajs Skarabäus an Euch bringen, komme was da wolle, und mir geben - ich werde daraus dann den Kopf des Schlüssels fertigen.", completion = "Ja, perfekt! Ich... ich bin wieder einmal absolut überwältigt, wie geschickt und mutig Ihr doch seid. Es ist kaum vorstellbar, wie weit zu gehen Ihr bereit seid, um einen Sieg zu erringen.\n\nErlaubt mir jetzt bitte, auch einen kleinen Beitrag dazu zu leisten. Ich habe eine spezielle Tinktur vorbereitet, mit der ich den Skarabäus als Kopf am Schlüssel befestigen kann. Das wird den Schlüssel mit der Kraft erfüllen, die zum Öffnen der verschlossenen Tür in der Scholomance benötigt wird.\n\nDas wird nicht lange dauern...", sourceObjectiveStatus = "unverified-source-field" }
quests[5805] = { id = 5805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Merissa Stillbrunn in Goldhain einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Merissa Stillbrunn in Goldhain den Goldhaingeschenkgutschein.", progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[5821] = { id = 5821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leibwache zu mieten", description = "Unter normalen Umständen würden Rigger und ich unseren Kodo an den Kolkarzentauren vorbeiführen. Aber ab und zu sind Kriegstrommeln der Zentauren zu hören, und dann machen wir sofort Halt. Es ist nicht gut fürs Geschäft, tot zu sein!\n\nIch sag Euch was, {class}, wenn Ihr uns heil am Dorf der Kolkar vorbeibringt, soll es Euer Schaden nicht sein.\n\nEs ist nur eine kurze Strecke und Ihr müsst lediglich dafür sorgen, dass die Karawane intakt bleibt, dann könnt Ihr Euch Eure Belohnung bei Smeed Schraubenbuddel abholen. Ihr findet ihn ein Stück weiter die Straße runter. Wir haben geschäftlich miteinander zu tun.", sourceObjective = "Bringt Gizeltons Karawane am Dorf der Kolkarzentauren vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten.", completion = "Wisst Ihr, es scheint mir nicht besonders lukrativ zu sein, jemanden wie Euch dafür zu bezahlen, Gizeltons Karawane zu beschützen. {class}, wenn ich ein bisschen größer wäre, könnte ich einen Nebenjob annehmen und mit der größten Schusswaffe in der Hand auf Kodos reiten. Und dann würde ich den vermaledeiten Zentauren echt mal zeigen, wer hier der Boss ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[5841] = { id = 5841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Yori Bruchhelm in Kharanos einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Yori Bruchhelm in Kharanos den Geschenkgutschein von Kharanos.", progress = "Hallo! {name} ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[5842] = { id = 5842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Orenthil Wisperwind in Dolanaar einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Orenthil Wisperwind in Dolanaar den Geschenkgutschein von Dolanaar.", progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[5843] = { id = 5843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Magga in Klingenhügel einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Magga am Klingenhügel den Geschenkgutschein des Klingenhügels.", progress = "Hallo! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[5844] = { id = 5844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Vorn Himmelsdeuter im Dorf der Bluthufe einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Vorn Himmelsdeuter im Dorf der Bluthufe den Geschenkgutschein der Bluthufe.", progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[5845] = { id = 5845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von verlorener Ehre", description = "Der Orden der Silbernen Hand wurde gar sehr geschwächt, als Uther sein gewaltsames Ende fand.\n\nDer Junge hat durchgehalten, solange er konnte. Er wurde bis zum vom Krieg zerrissenen Weiler Nordtal zurückgetrieben, und dort stellte er sich zu seinem letzten Kampf.\n\nWar noch irgendjemand aus dem Orden am Leben, fragte er sich - und spielte das überhaupt noch eine Rolle?\n\nMit diesem Gedanken im Kopf schmetterte Taelan die Standarte des Ordens zu Boden und entsagte allem, was er gelernt hatte. Auf dem blutgetränkten Boden des Nordtals ließ er seine Ehre zurück.\n\nIhr müsst ins Nordtal reisen und das Symbol der verlorenen Ehre finden.", sourceObjective = "Reist ins Nordtal im nordöstlichsten Gebiet der Östlichen Pestländer und sucht nach dem Symbol der verlorenen Ehre. Kehrt zu Tirion Fordring zurück, sobald Ihr Eure Mission abgeschlossen habt.", progress = "Mein Glaube wird Euch leiten, {name}. Das Licht kennt keine Grenzen.", completion = "Sie ist noch genauso prachtvoll - sogar in diesem zerlumpten Zustand - wie an dem Tag, als ich sie sah und meinen Treueid darauf schwor.\n\nSeine Erlösung naht, und mit ihr vielleicht auch meine...", sourceObjectiveStatus = "unverified-source-field" }
quests[5846] = { id = 5846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Liebe und Familie", description = "Als Taelan noch ein Kind war, unternahmen wir mit der Familie oft Ausflüge nach Darrowehr. Bei unserem letzten Besuch malte eine Künstlerin namens Renfray ein Porträt von uns, wie wir am Strand posierten. Das ist die schönste Erinnerung, die ich an Taelan und Karandra habe. Denn es war just dieser Moment, wo ich meine Frau und meinen Sohn in den Armen hielt, dass ich eine Liebe und Verbundenheit mit meiner Familie spürte, die ich seitdem nie wieder erlebt habe.\n\nFalls dieses Gemälde noch existiert, müsst Ihr es finden.\n\nBegebt Euch zur in Trümmern liegenden Insel Darrowehr und seht nach, ob das Gemälde der Künstlerin noch da ist.", sourceObjective = "Begebt Euch zur Insel Darrowehr im südlich-zentralen Bereich der Pestländer und sucht nach Hinweisen, wo sich das Gemälde befinden könnte.", completion = "Wie konnte ich das nur vergessen? Viele der Geister auf dieser Insel sind dazu verdammt, ihre letzte glückliche Erinnerung vor ihrem tragischen Ende noch einmal zu durchleben.\n\nIch bin ebenfalls verdammt, aber auf andere Weise als sie - ich bin einer der wenigen, die sich an alles erinnern ...\n\nVielleicht ist das, worum Ihr mich batet, der Grund, warum ich in diesen Ruinen spuke. Vielleicht es das, was mich befreien kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[5847] = { id = 5847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Willkommen!", description = "Willkommen bei World of Warcraft!\n\nAls besonderes Dankeschön dafür, dass Ihr die World of Warcraft Collector's Edition erworben habt, erhaltet Ihr diesen Geschenkgutschein, den Ihr bei Claire Weidner in Brill einlösen könnt. Dort erhaltet Ihr dann ein Geschenk: einen kleinen Gefährten, der Euch bei Eurer Suche nach Abenteuer und Ruhm begleiten wird.\n\nNochmals vielen Dank und genießt Euren Aufenthalt in World of Warcraft!", sourceObjective = "Bringt Claire Weidner in Brill den Geschenkgutschein von Brill.", progress = "Seid gegrüßt! Es ist mir eine Freude, Eure Bekanntschaft zu machen!\n\nWie ich sehe, habt Ihr da einen besonderen Gutschein. Gebt ihn mir, dann bekommt Ihr von mir etwas dafür.", completion = "Ihr seid wirklich ein besonderer Held, {name}! Wir heißen Euch in der Welt Azeroth willkommen und möchten Euch eines dieser einzigartigen Geschenke überreichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[5848] = { id = 5848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Liebe und Familie", description = "Das Gemälde... Es hing jahrelang an der Wand meiner Werkstatt - in der Kaserne des Ordens.\n\nNachdem Tirions Prüfung vorüber war, wusste ich, dass ich das Gemälde nicht mehr dort für alle sichtbar hängen lassen konnte. So versteckte ich es an einem Ort, an dem es niemand vermuten würde.\n\nGeht nach Stratholme und begebt Euch tief in die heutige Scharlachrote Bastion. Sucht dort nach einem Gemälde, auf dem unsere Zwillingsmonde abgebildet sind. Kratzt die Farbe weg, bis mein Meisterwerk zum Vorschein kommt, 'Von Liebe und Familie'.\n\nMöge das Licht Eure Taten leiten.", sourceObjective = "Begebt Euch nach Stratholme im nördlichen Teil der Pestländer. In der Scharlachroten Bastion findet Ihr das Gemälde 'Von Liebe und Familie', das zwischen anderen Gemälden versteckt ist und auf dem die Zwillingsmonde unserer Welt abgebildet sind.\n\nBringt das Gemälde zu Tirion Fordring.", progress = "Das Gemälde, {name}. Habt Ihr das Gemälde?", completion = "<Tirion bricht beinahe zusammen, als er das Gemälde sieht.>\n\n<Er beginnt hemmungslos zu weinen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[5861] = { id = 5861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Myranda suchen", description = "Ihr habt alles getan, um das ich Euch bislang bat, {name}. Jetzt fehlt nur noch ein Schritt auf Eurem Weg zur Erlösung.\n\nIhr müsst die gesammelten Gegenstände Taelan aushändigen. Leider werden Euch Taelan und seine Scharlachroten Kreuzzügler angreifen, sobald sie Euer ansichtig werden.\n\nEs gibt nur eine Möglichkeit, meine Nachricht zu übermitteln, und zwar durch Täuschung.\n\nIm Süden findet Ihr Uthers Grabmal. Myranda, eine alte und getreue Vertraute von mir, lebt jetzt dort - geht zu ihr. Zeigt ihr die Gegenstände, dann wird sie Euch helfen.", sourceObjective = "Begebt Euch zu Uthers Grabmal in den Südlichen Pestländern. Zeigt Myranda der Vettel Tirions Geschenk.", progress = "Ich wusste, dass dieser Tag kommen würde.", completion = "Ich war Tirions engste Beraterin, als er noch Lord von Mardenholde war. Ich habe mich offen gegen das Urteil des Ordens der Silberhand ausgesprochen und wurde wegen meiner Unverschämtheit verbannt.\n\nEr hat in seinem Leben viel Herzeleid und viele Enttäuschungen erlitten, {race}. Seid Ihr bereit, das den Fordrings angetane Unrecht wieder gut zu machen?", sourceObjectiveStatus = "unverified-source-field" }
quests[5862] = { id = 5862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scharlachrote Täuschung", description = "Ich bin eine Illusionistin, wie Ihr das nennen würdet. Ich könnte zwar eine Illusion erschaffen, die es Euch ermöglichen würde, Herdweiler zu betreten, aber seid gewarnt, meine Kräfte haben Grenzen.\n\nSolltet Ihr Euch zu weit aus diesem Land entfernen, lassen die Effekte dieser Illusion nach. Der Zauber selbst bedarf Unmengen an Konzentration und Kraft meinerseits, und deshalb kann ich den Effekt nur für kurze Zeit aufrechterhalten.\n\nKommt wieder zu mir, wenn Ihr bereit seid.", sourceObjective = "Sprecht mit Myranda, um die Scharlachrote Illusion zu erhalten. Begebt Euch nach Herdweiler, während Ihr unter dem Einfluss der Scharlachroten Illusion steht, und übergebt dem Hochlord Taelan FordringTirions Geschenk.\n\nHerdweiler liegt im Norden, Taelan dürfte sich in der Burg Mardenholde aufhalten.", progress = "Seid Ihr die Verstärkung von Tyrs Hand?", completion = "Was ist das, Soldat?\n\n<Taelan öffnet den Kasten und beginnt, dessen Inhalt zu untersuchen.>\n\nDas... das kann nicht wahr sein. Aber all das, was Ihr mir gezeigt habt...\n\n<Taelan fällt auf die Knie, sein Herz schlägt schneller. Die Wut der Äonen wird über diese Stadt kommen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[5863] = { id = 5863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Truppenlager der Dünenbrecher", description = "Erst kürzlich ist eine große Gruppe nomadischer Oger in Tanaris eingetroffen. Südlich von hier haben sie einen großen Bereich der Wüste in Besitz genommen und ein Truppenlager aufgeschlagen. Mehrere kleinere Gruppen durchstreifen momentan die Wüste, einige davon sind in die alten Trollruinen eingedrungen.\n\nDas Truppenlager der Dünenbrecher muss zerstört werden! Wir dürfen nicht zulassen, dass diese Oger zu einer Streitmacht heranwachsen.\n\nDer Anführer der Gruppe heißt Gor'marok der Verheerer. Ich bin mir sicher, dass es den Anfang vom Ende für die Oger bedeuten würde, wenn man ihnen den Anführer nimmt.", sourceObjective = "Andi Lynn in Gadgetzan möchte, dass Ihr das Truppenlager der Dünenbrecher vernichtet, indem Ihr 10 Schläger der Dünenbrecher 10 Vollstrecker der Dünenbrecher sowie Gor'marok den Verheerer tötet.", completion = "Ich bin ja so froh, dass Ihr das für mich tun konntet, {name}! Ich danke Euch für Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[5881] = { id = 5881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinzurufen der Reserve", description = "Die Horde kümmert sich gut um ihre Truppen... seit dem großen Krieg ging es uns hier in Kalimdor sehr gut.\n\nIhr müsst mir einen Gefallen tun. Ich lasse einen Jungen namens Grish Fernläufer den Großen Aufzug im Südlichen Brachland bewachen. Gebt ihm diesen Brief, er wird ihn wissen lassen, dass ich einen Ersatzmann angefordert habe, um ihn von seinem Dienst zu entbinden, damit er seine Familie besuchen kann. Er bat mich vor einer Weile darum und wird sich über diese Nachricht freuen.", sourceObjective = "Maggran möchte, dass Ihr Grish Fernläufer am Großen Aufzug im Brachland einen Brief zustellt.", progress = "Ihr habt Nachricht von Maggran Earthbinder?", completion = "Dies sind großartige Neuigkeiten. Ich sitze schon viel zu lang hier herum und bewache diesen Holzblock. Jetzt kann ich endlich etwas Zeit mit meiner Familie verbringen... Jippie!", sourceObjectiveStatus = "unverified-source-field" }
quests[5882] = { id = 5882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Jagd", progress = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr Eure cenarischen Pflanzensalben. Durchsucht den Teufelswald nach verderbten Pflanzen, {name}! Wo auch immer sie sind, benutzt die Salbe, die ich Euch gab, um sie zu läutern." }
quests[5883] = { id = 5883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Bergbau", progress = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr etwas cenarische Pflanzensalbe. Wenn Ihr beim Bergbau im Teufelswald noch mehr Vitriol findet, dann hebt es auf jeden Fall für mich auf! Je mehr Ihr davon findet, desto mehr Salbe kann ich herstellen." }
quests[5884] = { id = 5884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Sammlung", progress = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", completion = "Ausgezeichnete Arbeit, {name}, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, {race}!" }
quests[5885] = { id = 5885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Kürschnerei", progress = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", completion = "Genau das brauche ich. Hier, nehmt diese Pflanzensalben und verwendet sie, um den Teufelswald der Verderbnis zu entreißen. Wir müssen beharrlich bleiben, {name}!" }
quests[5886] = { id = 5886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Entzauberung", progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, {name}. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!" }
quests[5887] = { id = 5887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Jagd", progress = "Wer ein cenarisches Leuchtfeuer besitzt, kann mit diesem die verderbten Seelensplitter in den besudelten Bestien sehen, die zum Wohl der Allgemeinheit vernichtet werden. Ich schleife Splitter zu einem nutzbaren Reagenz, das für die Herstellung von cenarischer Pflanzensalbe verwendet wird. Wir werden diese Salbe benutzen, um verderbte Pflanzen wieder in gesunde zu verwandeln.\n\nIm Austausch für diese Splitter werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr Eure cenarischen Pflanzensalben. Durchsucht den Teufelswald nach verderbten Pflanzen, {name}! Wo auch immer sie sind, benutzt die Salbe, die ich Euch gab, um sie zu läutern." }
quests[5888] = { id = 5888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Bergbau", progress = "Wenn Ihr im Besitz eines cenarischen Leuchtfeuers seid, während Ihr im Teufelswald Bergbau betreibt, könnt Ihr das besudelte Vitriol sehen, von dem eine Ader Rohmetall verderbt wird. Ich weiß, wie man dieses Vitriol läutert und zu einem Reagenz verarbeitet, aus dem cenarische Pflanzensalbe hergestellt wird. Diese Salbe verwendet Ihr dann an Pflanzen, die Ihr draußen in der Wildnis findet und die gerettet werden müssen.\n\nWenn Ihr verderbtes Vitriol gesammelt habt, werde ich Euch etwas cenarische Pflanzensalbe geben, die ich bereits vorbereitet habe.", completion = "Sehr gut, hier habt Ihr etwas cenarische Pflanzensalbe. Wenn Ihr beim Bergbau im Teufelswald noch mehr Vitriol findet, dann hebt es auf jeden Fall für mich auf! Je mehr Ihr davon findet, desto mehr Salbe kann ich herstellen." }
quests[5889] = { id = 5889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Sammlung", progress = "Mit einem cenarischen Leuchtfeuer können erfahrene Kräuterkundige die heimtückische Teufelsranke erkennen, ein bösartiges Produkt der Verderbnis des Teufelswalds. Dank meiner Arbeit verfüge ich über das Wissen, die Teufelsranke zu einem Säuberungsreagenz verarbeiten zu können. Dieses verwenden wir für etwas, das wir jetzt cenarische Pflanzensalbe nennen.\n\nWenn Ihr im Teufelswald Kräuter sammelt, dann solltet Ihr, solange Ihr das Leuchtfeuer bei Euch habt, auf Teufelsranken stoßen. Im Austausch gegen das, was Ihr mir bringt, werde ich Euch fertige cenarische Pflanzensalbe geben.", completion = "Ausgezeichnete Arbeit, {name}, jedes Teilchen hiervon wird, sobald wir es geläutert haben, dabei helfen, den Teufelswald zurückzugewinnen. Hier, nehmt einige Dosen der cenarischen Pflanzensalbe und begebt Euch in den Wald. Wir dürfen nicht damit zögern, das Land der Verderbnis zu entreißen, {race}!" }
quests[5890] = { id = 5890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Kürschnerei", progress = "Mit einem cenarischen Leuchtfeuer können gut ausgebildete Kürschner die Flecken besudelter Haut auf den im Teufelswald erbeuteten Fellen erkennen. Ich wandle diese scheinbar nutzlosen Flecken in eine dicke Paste um, mit der die cenarische Pflanzensalbe aktiviert wird. Wenn Ihr hier im Teufelswald Eure Beute häutet, dann solltet Ihr unbedingt immer ein Leuchtfeuer bei Euch haben.\n\nSobald Ihr besudelte Flecken gesammelt habt, bringt sie mir. Ich gebe Euch etwas cenarische Pflanzensalbe dafür, die ich bereits hergestellt habe.", completion = "Genau das brauche ich. Hier, nehmt diese Pflanzensalben und verwendet sie, um den Teufelswald der Verderbnis zu entreißen. Wir müssen beharrlich bleiben, {name}!" }
quests[5891] = { id = 5891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salbe durch Entzauberung", progress = "Die Macht eines entzauberten magischen Gegenstandes ist in der von ihm geschaffenen Essenz spürbar. Ich habe einen Weg gefunden, um die rohe Essenz, die von Verzauberern verwendet wird, in ein geeignetes Reagenz für die cenarische Pflanzensalbe umzuwandeln. Dazu braucht Ihr kein cenarisches Leuchtfeuer; jeder angemessen entzauberte Gegenstand, der geringe Netheressenzen abgibt, ist dafür geeignet.\n\nIch brauche nur eine einzige geringe Netheressenz; im Austausch dafür werde ich Euch cenarische Pflanzensalben geben. Die Essenz ist hochwirksam - ganz wenig davon genügt, um viel zu erreichen.", completion = "Hier sind einige cenarische Pflanzensalben - ich brauche nur eine geringe Netheressenz, um sie herzustellen, {name}. Die Essenz ist bei weitem der wirksamste Gegenstand, um Schwerter zu Pflugscharen zu machen, wenn man so sagen will. Wenn Ihr mehr Salbe braucht, dann kommt wieder zu mir!" }
quests[5892] = { id = 5892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisenschachtmine", description = "Bevor die Schlacht begann, lagerten wir Vorräte für Dun Baldar in der Eisenschachtmine. Die Troggs, die dort hausten, waren kein Problem solange wir Ersatztruppen hatten, die die Mine bewachen konnten, aber da wir nun gegen die Horde kämpfen, können wir sie nicht mehr kontrollieren.\n\nWir brauchen die Vorräte in der Eisenschachtmine, {name}. Betretet die Mine und bring mir eine Ladung.", sourceObjective = "Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Allianz in Dun Baldar.", progress = "Habt Ihr die Vorräte, {name}? Wir können nicht genug davon haben!", completion = "Danke, {name}! Ich werde sie einem guten Zweck zuführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5893] = { id = 5893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorräte der Eisbeißermine", description = "Die Eisbeißermine im Norden war einst ein idealer Ort, um zusätzliche Vorräte zu lagern, aber da die Kämpfe mit den Sturmlanzen nun härter werden, haben wir nicht immer die notwendigen Soldaten über, um sie an der Mine zu positionieren und diese zu bewachen. Daher fällt die Kontrolle über diese Mine oft an die Allianz oder an Untergrundvölker...\n\nAber wir benötigen dennoch unsere Vorräte, {name}! Geht zu der Eisbeißermine und bringt mir eine Ladung. Seid wachsam, was unsere Feinde anbelangt, die Übermacht in der Schlacht kann sich an jenem Ort schnell ändern...", sourceObjective = "Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Horde in die Burg Frostwolf.", progress = "Wart Ihr in der Coldtooth-Mine, {name}? Habt Ihr die Vorräte nach denen ich fragte?", completion = "Ah, Ihr habt Sie bekommen. Gute Arbeit, {name}! Die Vorräte sind schon etwas moderig, nachdem sie so lange in der Mine lagerten. Ich denke, sie werden uns dennoch sehr weiterhelfen.\n\nVielen Dank, {name}. Eure Anstrengungen sind lebenswichtig für die Versorgung unserer Streitkräfte.", sourceObjectiveStatus = "unverified-source-field" }
quests[5901] = { id = 5901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Also, um Schmerz und Unfrieden über den Scharlachroten Kreuzzug zu bringen, möchte ich ihnen ihr wertvolles Sägewerk wegnehmen. Ich bin mir sicher, der Verlust einer solchen Ressource wird ihnen ziemlichen Schaden in Bezug auf Verteidigung und Wiederaufbau der Stadt für ihre Zwecke zufügen. Werdet Ihr mir helfen, {name}?\n\nFangt an, indem Ihr diesen Krug zum Pestwald in den Östlichen Pestländern bringt. Füllt ihn mit den Termiten, die Ihr in ihren Hügeln überall im Wald findet. Kommt wieder, wenn Ihr eine ausreichende Menge habt.", sourceObjective = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück.", progress = "Habt Ihr die Termiten schon, {name}? Ich bin sicher, dass es für jemanden, der so schlau ist wie Ihr, {class}, ganz einfach ist.\n\nSobald wir genug davon haben, sorgen wir dafür, dass niemand dieses Sägewerk je wieder verwenden kann!", completion = "Die sind prima, {name}. Danke.\n\nWenn Ihr bereit seid, können wir uns dem nächsten Schritt zuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[5902] = { id = 5902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Da wir jetzt jede Menge Termiten haben, bringt dieses stahlverstärkte Fass zum Sägewerk des Nordkamms südlich von Herdweiler. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes, irgendwo weit oben, vielleicht auf eine Kiste oder so was.\n\nNachdem Ihr es geöffnet habt, sollte sich der Rest von selbst erledigen. Kommt einfach hierher zurück und ich werde Euch dafür belohnen, dass Ihr mir geholfen habt.", sourceObjective = "Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den Westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen.\n\nBereitgestellter Gegenstand:", completion = "Die Termiten werden offensichtlich unruhig, als Ihr das Fass auf die Kiste stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5903] = { id = 5903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Ich habe bereits viele Male versucht, den Scharlachroten Kreuzzug allein mit Gewalt auszulöschen, doch ohne Erfolg. Daher habe ich mich entschlossen, ihnen das Leben schwer zu machen.\n\nWenn Ihr bereit seid zu helfen, möchte ich, dass Ihr dieses Sägewerk mit der übelsten Termitenart verseucht, die je gefunden wurde.\n\nIm Pestwald, nahe dem einst großen Stratholme, gibt es eine Spezies, die die Seuche und auch die Geißel überlebt hat. Sucht ihre Hügel und füllt diesen Krug mit ihnen, damit wir sie darauf vorbereiten können, auf den Kreuzzug losgelassen zu werden.", sourceObjective = "Wendet den leeren Termitenkrug auf die Termitenhügel in den Östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Nathaniel Dumah im Zugwindlager in den Westlichen Pestländern zurück.", progress = "Habt Ihr die Termitenhügel gefunden, {name}? Ich habe gehört, es gibt sie überall im Pestwald.", completion = "Die sind prima, {name}. Danke. Schaut sie Euch nur an... so viele von ihnen, alle auf einem Haufen. Ich habe schon beinahe Mitleid mit dem Kreuzzug, aber es war ja schließlich niemals ihre Mühle, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[5904] = { id = 5904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Plage komme über Euch", description = "Da wir jetzt die Termiten haben, bringt dieses stahlverstärkte Fass zum Sägewerk des Nordkamms südlich von Herdweiler. Ihr werdet es westlich der Straße finden, die Euch in die Stadt hinauf führt.\n\nWenn Ihr dort seid, stellt Ihr das Fass in die Mitte des Sägewerkes. Findet einen geeigneten Ort, vielleicht eine Kiste, und öffnet es dann. Die Termiten dürften dann ihre Arbeit tun und die Mühle für den Kreuzzug unbrauchbar machen.", sourceObjective = "Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den Westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen.\n\nBereitgestellter Gegenstand:", completion = "Die Termiten werden offensichtlich unruhig, als Ihr das Fass auf die Kiste stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[5921] = { id = 5921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondlichtung", description = "Alle Druiden sind in den hochheiligen Landen der Mondlichtung willkommen, ungeachtet der derzeitigen Spannungen im Zirkel des Cenarius zwischen dem Erzdruiden Hirschhaupt und dem Bewahrer Remulos, dem Wächter der Mondlichtung. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr das Wissen der Mondlichtung oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr zur Mondlichtung reisen und mit Dendrite Sternenschauer in Nachthafen über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, <junger Druide/junge Druidin>.", sourceObjective = "Benutzt den Zauber 'Teleportieren: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen.", completion = "Und so beginnt es, Vater Cenarius. Und so beginnt es.\n\nDendrite macht eine schnelle, unsichtbare Geste in die Luft über ihm. Eine leichte Aura der Macht fällt über ihn.\n\nDie erste Perspektive der Natur, die Ihr Euch aneignen müsst, ist die des Bären. Ich werde Euch auf den Weg bringen, um diesen Aspekt des Druidenlebens zu verstehen, aber Ihr müsst ihn Euch zu Eigen machen und pflegen - von nun an und für immer!", sourceObjectiveStatus = "unverified-source-field" }
quests[5922] = { id = 5922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondlichtung", description = "Alle Druiden sind in den hochheiligen Landen der Mondlichtung willkommen, Tauren wie Nachtelfen. Bewahrer Remulos - der Wächter der Mondlichtung - wacht über alle Druiden, die hier ihren Winterschlaf halten. Jetzt, da Ihr den Weg der Klaue lernt, bringe ich Euch den Zauber bei, der es Euch ermöglicht, Euch selbst dorthin zu befördern. Wirkt ihn, wann immer Ihr das Wissen der Mondlichtung oder Zuflucht sucht.\n\nAls Eure erste Lektion müsst Ihr zur Mondlichtung reisen und mit Dendrite Sternenschauer in Nachthafen über den Pfad sprechen, auf dem Ihr jetzt wandelt. Viel Glück, <junger Druide/junge Druidin>.", sourceObjective = "Benutzt den Zauber 'Teleportieren: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen.", completion = "Und so beginnt es, Vater Cenarius. Und so beginnt es.\"\n\nDendrite macht eine schnelle, unsichtbare Geste in die Luft über ihm. Eine leichte Aura der Macht fällt über ihn.\n\n\"Die erste Perspektive der Natur, die Ihr Euch aneignen müsst, ist die des Bären. Ich werde Euch auf den Weg bringen, um diesen Aspekt des Druidenlebens zu verstehen, aber Ihr müsst ihn Euch zu Eigen machen und pflegen - von nun an und für immer!", sourceObjectiveStatus = "unverified-source-field" }
quests[5923] = { id = 5923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", sourceObjective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus.", completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[5924] = { id = 5924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", sourceObjective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus.", completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[5925] = { id = 5925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Mathrengyl Bärenfährte bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Mathrengyl ist der direkte Assistent des Erzdruiden selbst und einer der beflissensten und erhabensten Druiden, die Ihr in Teldrassil finden könnt.\n\nEr befindet sich in der Enklave des Cenarius von Darnassus, im zweiten Stock von Fandral Hirschhaupts Baum.", sourceObjective = "Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus.", completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[5926] = { id = 5926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[5927] = { id = 5927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5928] = { id = 5928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Ruf folgen", description = "Entschuldigung...\n\nEs ist mir zu Ohren gekommen, dass Turak Runentotem bekannt gegeben hat, dass er mit Euch sprechen möchte. Es scheint, dass Eure Ausbildung als Druide ein neues Gesicht bekommen soll und dass er Euch persönlich ausbilden will. Turak ist einer der Assistenten des Erzdruiden. Er ist als weiser und geduldiger Druide bekannt und wird Euch gut anleiten.\n\nEr befindet sich in Donnerfels, im Hauptzelt des Zirkels des Cenarius auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels.", completion = "Ich bin froh, dass Ihr heute Euren Weg hierher gefunden habt. Es ist an der Zeit für Euch, einen großen Schritt in eine noch viel größere Welt zu tun.\n\nIn jedem von Cenarius' Kindern steckt die Berufung, der Natur zu dienen. Tiere und Pflanzen sind unsere Freunde wie auch unsere Schützlinge. Wir haben uns entschlossen, sowohl zu ihrem wie auch unserem Wohl unsere Leben dem Erhalt des Gleichgewichts zu widmen. Euer erster Schritt in diese Welt wird es sein, etwas über den Weg des Bären und die Stärke von Körper und Herz zu erlernen.\n\nMacht Euch bereit!", sourceObjectiveStatus = "unverified-source-field" }
quests[5929] = { id = 5929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Bärengeist", description = "Im nordwestlichen Teil der Mondlichtung liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nachthafen zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", sourceObjective = "Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück.", progress = "Kehrt erst zurück, wenn der große Bärengeist Euch wieder zu mir zurückschickt. Eure Ausbildung kann ohne seinen Segen nicht weitergehen.", completion = "Dendrite macht eine weitere unsichtbare Geste in der Luft über ihm, als Ihr Euch ihm nähert. Eine erneute Aura der Macht legt sich auf ihn und er lächelt ein wenig.\n\n\"Ich spüre Weisheit in Euch, Weisheit, die nicht zugegen war, als wir uns das erste Mal trafen. Ihr blickt mit Stärke und verständnisvollem Eifer zu mir auf, auch wenn dieser Eifer noch nicht sehr zielgerichtet ist. Ihr werdet nun lernen, Eure Stärke zu fokussieren und das Wesen des Bären in Eure Arbeit anzuwenden.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[5930] = { id = 5930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großer Bärengeist", description = "Im nordwestlichen Teil der Mondlichtung liegt das Zuhause eines weisen und edlen Wesens, das wir den großen Bärengeist nennen. Er hat allen Druiden als Tutor und Mentor zur Seite gestanden, die das erste Mal wahres und natürliches Verständnis für den Bären entwickeln wollten. Alle Druiden suchen an irgendeinem Punkt ihres Lebens die Weisheit des Geistes und auch Ihr werdet keine Ausnahme sein.\n\nGeht nun zum großen Bärengeist und lernt, was er Euch beibringen wird. Wenn er mit Euch zufrieden ist, kehrt zu mir hier nach Nachthafen zurück. Wir werden dann sehen, ob Ihr die Lektionen, die er Euch gelehrt hat, wirklich verinnerlicht habt.", sourceObjective = "Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück.", progress = "Kehrt erst zurück, wenn der große Bärengeist Euch wieder zu mir zurückschickt. Eure Ausbildung kann ohne seinen Segen nicht weitergehen.", completion = "Dendrite macht eine weitere unsichtbare Geste in der Luft über ihm, als Ihr Euch ihm nähert. Eine erneute Aura der Macht legt sich auf ihn und er lächelt ein wenig.\n\n\"Ich spüre Weisheit in Euch, Weisheit, die nicht zugegen war, als wir uns das erste Mal trafen. Ihr blickt mit Stärke und verständnisvollem Eifer zu mir auf, auch wenn dieser Eifer noch nicht sehr zielgerichtet ist. Ihr werdet nun lernen, Eure Stärke zu fokussieren und das Wesen des Bären in Eure Arbeit anzuwenden.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[5931] = { id = 5931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Darnassus", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Mathrengyl Bärenfährte bewegt sich wirklich im Einklang mit der Natur, selbst wenn er gefährlich nahe der Orte ist, an denen das Gleichgewicht zusammengebrochen ist. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", sourceObjective = "Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius.", completion = "Willkommen, {name}. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.\n\nDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir verlassen uns heute auf seine Weisheit und seine Macht, um unseren Absichten Antrieb zu verleihen. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[5932] = { id = 5932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück nach Donnerfels", description = "Es ist an der Zeit für uns, getrennte Wege zu gehen, denn die Anwendung Eurer Lektionen bringt Euch zurück zu demjenigen, der Euch zu mir geschickt hat. Auch wenn die Tauren auf den Wegen des Cenarius als jung angesehen werden, wandelt Turak Runentotem doch mit großem Gleichgewicht in Gegenwart der Natur. Achtet auf seine Anweisungen und Ihr werdet bald die ersten Lektionen Eurer Rolle als Beschützer des Gleichgewichts beenden.\n\nGeht jetzt. Wir sehen uns wieder.", sourceObjective = "Kehrt nach Donnerfels zurück und sprecht mit Turak Runentotem auf der Anhöhe der Ältesten.", completion = "Willkommen, {name}. Ich spüre, dass Eure erste Begegnung mit dem großen Bärengeist genauso verlief wie bei allen Druiden, wenn sie die ersten Schritte auf dem Pfad der Klaue tun... etwas verwirrend, aber sehr eindrucksvoll. Ich weiß, dass es für mich damals auch so war.\n\nDer große Bärengeist ist schon so lange ein Teil von Azeroth wie Azeroth in den Himmeln existiert. Wir {race} hören solchen Geistern genau zu und wir alle profitieren von deren Absichten. Nun ist es an der Zeit für Eure erste Prüfung dieser Absichten. Hört mir gut zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[5941] = { id = 5941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Chromie", description = "Ihr habt viele Relikte der Schlacht von Darroheim gesammelt. Jedes Mal, wenn Ihr mit weiteren zurückgekehrt seid, sehnte sich mein Herz nach meinem Dorf... sehnte es sich danach, es vor seinem Schicksal zu bewahren.\n\nIch weiß, dass das nicht sein kann, aber Chromie, diese seltsame Gnomin in Andorhal, behauptet, es wäre möglich. Sie sagt, dass Ihr Darroheim retten könnt!\n\nSie hat mich gebeten, die Relikte zu sammeln und sie von Euch zu ihr bringen zu lassen. Sie sagte, dass sie Euch im zerstörten Gasthaus von Andorhal erwartet.", sourceObjective = "Bringt das Reliktbündel zu Chromie nach Andorhal.", progress = "Ich stand in Kontakt mit Eurem Freund Carlin. Er leidet sehr unter dem Untergang seines Dorfes, doch er spricht sehr gut von Euch und weiß, dass Ihr die Dinge richten könnt.\n\nOh, ich fürchte ich schweife vom Thema ab... {name}, habt Ihr die Relikte, um die ich gebeten habe?", completion = "Ach ja, da sind sie ja. Gemeinsam weben sie einen mächtigen Zauber, einen, der die Geister von Darrowshire wiedererwecken wird.\n\nMit diesem Zauber und etwas Glück können wir Joseph Redpath retten!", sourceObjectiveStatus = "unverified-source-field" }
quests[5942] = { id = 5942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versteckte Schätze", description = "Papa sagte, ich solle Euch diesen Schlüssel geben. Er sagte, er öffnet eine Truhe draußen hinter dem Haus.\n\nEr wollte außerdem, dass ich Euch danke. Habt Ihr ihm einen Gefallen getan? Habt Ihr ihm gesagt, dass Ihr meine Puppe gefunden habt?\n\nNun, hier ist jedenfalls der Schlüssel. Und habt Dank, {name}. Danke! Ihr seid <ein sehr netter Mann/eine sehr nette Dame>!", sourceObjective = "Bringt Josephs Schlüssel zu Josephs Truhe.", progress = "Diese Truhe ist alt und rußverschmiert.", completion = "Der Schlüssel passt in das Schloss, und die Truhe öffnet sich...", sourceObjectiveStatus = "unverified-source-field" }
quests[5943] = { id = 5943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gizeltons Karawane", description = "Ihr seht fähig aus, {race}. Vielleicht wollt Ihr Euch etwas Geld verdienen? Cork und ich haben mit dieser Karawane angefangen, um einen Haufen Geld zu scheffeln. Doch wir hatten keine Ahnung von den Gefahren, die das schnelle Geld mit sich bringen würde!\n\nDa vor uns liegt der Zirkel der Mannoroc...normalerweise ignorieren die Dämonen uns, aber dieses Mal verängstigt irgendetwas die Kodos. Ich werde Euch dafür bezahlen, wenn Ihr die Karawane auf dem Weg am Zirkel der Mannoroc vorbei beschützt. Sobald wir sicher daran vorbei sind, könnt Ihr Euch Eure Belohnung bei unserem Geschäftspartner Smeed in Schraubenbuddels Lager abholen.", sourceObjective = "Geleitet Gizeltons Karawane am Zirkel der Mannoroc vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten.", completion = "Ich bin mir nicht sicher, ob es zu ihrem Erfolg beiträgt, Euch so viel Geld für den Schutz von Gizeltons Karawane zu bezahlen. Cork und Rigger verdienen gerade mal ein Goldstück pro Woche, doch solange sie schön meine Kodos bezahlen, kann es mir eigentlich egal sein, wie sie ihre Geschäfte machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[5944] = { id = 5944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Träumen", description = "Über so lange Zeit war ich eine Marionette des Obersten Kreuzfahrers. Welchen Grund gab es, gegen das anzukämpfen, was aus dem Scharlachroten Kreuzzug geworden ist? Es ist Jahrzehnte her, doch die Erinnerungen an meinen Vater - diese kostbaren Erinnerungen - waren es, die mich am Leben erhielten.\n\nIch habe Träume, <Fremder/Fremde>. In diesen Träumen ist mein Vater bei mir. Er steht stolz an meiner Seite, während ich in den Orden aufgenommen werde. Wir bekämpfen Legionen der Geißel, Seite an Seite. Wir bringen der Allianz und Lordaeron Ehre.\n\nIch möchte nicht mehr träumen.\n\nBringt mich zu ihm.", sourceObjective = "Geleitet Taelan Fordring aus Herdweiler hinaus.", completion = "Der Tod meines Sohnes durch die Hand dieser Monster wird nicht ungestraft bleiben. Findet Trost in dem Wissen, dass der Orden wiedergeboren wurde.\n\nIch nehme jetzt meinen Platz als Hochlord des neuen Orden der Silberhand ein.\n\nNehmt diese Besitztümer aus meiner Vergangenheit ... sie sind alles, was ich Euch für all das anbieten kann, was Ihr getan habt. Bitte, nehmt sie als ein Zeichen meiner Dankbarkeit. Sie haben mir all die Jahre gut gedient.\n\nAuf dass wir uns in besseren Zeiten wiedersehen und uns lang vergangener Tage, hart erkämpfter Schlachten und verblasster Träume erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[5961] = { id = 5961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Champion der Bansheekönigin", description = "Es freut mich sehr, dass sich die Kampferprobten unserer Sache anschließen. Unsere Schar gewinnt mit jedem Tag an Größe und Stärke. Vielleicht seid Ihr bereit, Euren Mut auf die Probe zu stellen, {class}?\n\nZu den ersten meiner Helden gehörte Nathanos, der heute Pestrufer genannt wird. In unseren Reihen gibt es kaum einen mit mehr Entschlossenheit oder Eifer.\n\nSucht in den Östlichen Pestländern nach ihm. Er wohnt in Marris Siedlung; ab und an streift er durch die dezimierten Ödländer und tötet jeden Abschaum der Geißel und der Allianz, den er aufspüren kann.", sourceObjective = "Sprecht mit Nathanos Pestrufer in den Östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte.", completion = "Gewiss hält Euch die Dunkle Fürstin nicht für würdig, ihren Champion zu treffen. Seid Ihr hier, um meine Hunde zu füttern, ja? Einen anderen Grund für diese Unterbrechung kann es nicht geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[5981] = { id = 5981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tobende Riesen", description = "Vor rund 4.000 Jahren rettete Tyrande Wisperwind die Frostsäblerkönigin aus den Händen tobender Riesen. Seither sind die Frostsäbler Verbündete der Nachtelfen.\n\nDoch die Riesen, die einst eine Gefahr für die Frostsäbler waren, gibt es noch immer, und das nicht allzu weit von hier entfernt. Man nennt sie Frosthagelriesen und sie haben das große Tal südlich von hier für sich beansprucht.\n\nBeweist Eure Treue zu den Frostsäblern. Tötet diese Riesen im Namen der Frostsäblerkönigin Shy-Rotam!", sourceObjective = "Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt.", completion = "Exzellent, {name}. Eure Entschlossenheit blieb nicht unbemerkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6001] = { id = 6001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper und Herz", description = "Unmittelbar östlich von Auberdine liegen viele Mondkinhöhlen. In der Auberdine am nächsten gelegenen Höhle befindet sich ein Mondkinstein. Mondklaue, der Verteidiger des Steins, stellt sich Euch nur, wenn Mondstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Mondstaub des Cenarius zu benutzen, {name}... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", sourceObjective = "Benutzt den Mondstaub des Cenarius mit dem Mondkinstein von Auberdine, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Mathrengyl Bärenfährte in Darnassus, wenn Ihr fertig seid.", completion = "Endlich habt Ihr den Schritt in eine viel größere Welt getan, {name}. Ich spüre die Lehre des großen Bärengeistes in Euch, und auch, dass Ihr die Kraft erhalten habt, die Mondklaue besaß.\n\nKein weiteres Hindernis versperrt Euren Weg... lasst mich Euch jetzt lehren, was es bedeutet, ein {class} der Klaue zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[6002] = { id = 6002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Körper und Herz", description = "Im Land westlich von Taurajo im Brachland - kurz bevor es in Mulgore übergeht - liegt ein Mondkinstein. Mondkin sind besondere Tiere, die nicht in diesen Breiten heimisch sind. Mondklaue, der Verteidiger des Steins, stellt sich Euch, wenn Lunarstaub des Cenarius darauf angewendet wird. Mondklaue besitzt eine innere Stärke, die Ihr als einer der Klaue benutzen müsst.\n\nIhr habt Euch das Recht verdient, diesen Lunarstaub des Cenarius zu benutzen, {name}... jetzt zeigt mir, dass Ihr Euch das Recht verdient habt, die Kraft des Körpers und des Herzens zu besitzen, die man als Druide braucht!", sourceObjective = "Benutzt den Lunarstaub des Cenarius mit dem Mondkinstein zwischen Mulgore und dem Brachland, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.\n\nSprecht mit Turak Runentotem in Donnerfels, wenn Ihr fertig seid.", completion = "Endlich habt Ihr den Schritt in eine viel größere Welt getan, {name}. Ich spüre die Lehre des großen Bärengeistes in Euch, und auch, dass Ihr die Kraft erhalten habt, die Mondklaue besaß.\n\nKein weiteres Hindernis versperrt Euren Weg... lasst mich Euch jetzt lehren, was es bedeutet, ein {class} der Klaue zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[6004] = { id = 6004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Ich wurde als Späher ausgeschickt, um etwas Schaden anzurichten und die Kraft von Herdweilers Verteidigung auszukundschaften. Einige Leute der Allianz sind der Meinung, die kleine Stadt habe mehr als nur eine historische Bedeutung. Meine Aufgabe ist es nicht, diese Bedeutung in Frage zu stellen, aber dennoch sollte ich mich in meiner Verfassung erst erholen, bevor ich weitermache.\n\nWenn Ihr wollt, zahle ich Euch ein hübsches Sümmchen für Eure Hilfe. Fangt südlich von hier in dem Lager an, das sie in der Nähe des kleinen Bollwerks aufgeschlagen haben. Wenn Ihr stark genug seid, könnt Ihr mir vielleicht bei meinem vordringlichen Ziel helfen.", sourceObjective = "Tötet 2 Scharlachrote Sanitäter, 2 Scharlachrote Jäger, 2 Scharlachrote Magier und 2 Scharlachrote Ritter, bevor Ihr zu Kirsta Grubenschatten in den Westlichen Pestländern zurückkehrt.", progress = "Wie läuft es, {name}? Sind sie stärker, als Ihr dachtet? Ich hoffe nicht. Wenn ich das hier durchziehen soll, dann erfordert das eine ganze Menge mehr Kraft als das, was ich bisher von Euch verlangt habe.", completion = "Gut gemacht, {name}. Ich bin erstaunt, dass Ihr so schnell mit ihnen fertig geworden seid. Danke.\n\nIch habe noch niemanden getroffen, der den Scharlachroten Kreuzzug und dessen Methoden gutgeheißen hätte. Ich glaube so sehr wie jeder andere in Stormwind an das Licht, sie aber haben bewiesen, dass sie nur alle töten wollen, die nicht treu zu ihrer Bewegung stehen ... selbst Unschuldige.", sourceObjectiveStatus = "unverified-source-field" }
quests[6021] = { id = 6021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaeldarr der Ausgestoßene", description = "Könnt Ihr Euch vorstellen, dass wir uns nach dem ganzen Ärger in den Pestländern... jetzt auch noch um Diebe sorgen müssen? Nicht einfach gewöhnliche Diebe, Trolldiebe.\n\nUnd nicht einfach gewöhnliche Trolldiebe. Tote Trolldiebe!\n\nSie werden von diesem großen toten Troll namens Zaeldarr dem Ausgestoßenen angeführt, kommen nachts hierher und stehlen Leichen aus der Grube unten. Dann schaffen sie sie zu ihrem üblen Versteck für tote Trolle - dem Tiefgewölbe im Westen.\n\nGeht dorthin und schaltet Zaeldarr aus, {name}. Ich habe seine Schandtaten satt!", sourceObjective = "Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des Hoffnungsvollen Lichts.", progress = "Habt Ihr das Versteck gefunden, {name}? Habt Ihr Zaeldarr ausgeschaltet?", completion = "Sehr schön, Ihr habt ihn! Und ich hoffe, Ihr habt auch seiner Bande eine Lektion erteilt!", sourceObjectiveStatus = "unverified-source-field" }
quests[6022] = { id = 6022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Töten zu einem bestimmten Zweck", description = "Ihr tötet zu einem bestimmten Zweck, solange Ihr in meiner Siedlung seid.\n\nEure erste Aufgabe ist es, meine Hunde zu füttern.\n\nNehmt diesen Mörser nebst Stößel und begebt Euch zu Corins Kreuzung. Dort angekommen findet Ihr Mitglieder der Geißel, die Ihr töten könnt, in recht großer Anzahl.. Aus ihren frischen Kadavern benötige ich lebendige Fäulnis. Nehmt diese lebendige Fäulnis, zermahlt sie im Mörser und lasst sie ruhen, bis sie gerinnt. Bringt die geronnene Fäulnis hierher.\n\nUnd bedenkt, Schwachkopf, dass lebendige Fäulnis der Untoten nicht lange 'lebendig' bleibt. Ihr müsst sie schnell töten!", sourceObjective = "Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis.", progress = "Weint Ihr etwa? Wenn Euch das zu 'anstrengend' ist, oh 'Held', dann rate ich Euch, kehrt zur Dunklen Fürstin zurück und erzählt ihr von der schrecklichen Behandlung, die Euch auf meinem Bauernhof zuteil wurde.\n\nUnd jetzt geht mir aus den Augen!", completion = "Enttäuschend. Ich hatte gehofft, ich würde stattdessen Euch an meine Hunde verfüttern können.\n\n<Nathanos seufzt.>\n\nNa, wenigstens haben sie etwas zu fressen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6023] = { id = 6023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Meine wahre Mission bestand darin, die äußeren Kräfte des Scharlachroten Kreuzzugs zu schwächen und dann Herdweiler zu infiltrieren, damit ich ihre Zahl abschätzen kann. In meiner Verfassung kann ich das immer noch nicht allein, vielleicht dürfte ich Euch ja erneut um Eure Unterstützung bitten, {name}? Bevor ich entdeckt wurde, konnte ich die Informationen sammeln, dass der Kreuzzug zwei wichtige Mitglieder hat, die das Rückgrat ihrer Streitkräfte außerhalb der Stadt bilden: Jägerin Radley und Dragoner Durgen. Tötet sie, das bringt uns schon weiter. Sie müssten am Pass von Herdweiler außerhalb der Stadtgrenze sein.", sourceObjective = "Besiegt Jägerin Radley und Dragoner Durgen, bevor Ihr zu Kirsta Grubenschatten in den Westlichen Pestländern zurückkehrt.", completion = "Danke, {name}. Ihr habt mir mehr geholfen als ich hoffen durfte. Die Luft hier scheint mir die Willenskraft auszusaugen. Ich bin müde und spüre, dass es sich nicht bessern wird, solange ich hier bin.\n\nIch habe wirklich keine Ahnung, wie ich nach Hearthglen hineingelangen und melden soll, wie stark die Präsenz des Scharlachroten Kreuzzugs dort ist.\n\nAber das ist ein anderes Thema. Bevor Ihr geht, hier, nehmt dies... als Bezahlung für Eure Hilfe. Nochmals danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[6024] = { id = 6024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hameyas Bitte", description = "Tötet mich. Bevor es zu spät ist.\n\nIch bin Hameya. Auf der Reise nach Zul'Mashar aßen meine Geschwister und ich verdorbenes Fleisch... und wir veränderten uns. Wir sind infiziert.\n\nIch spüre bereits die Worte des Lichs, der mich bedrängt, dass ich nach Zul'Mashar gehen und noch mehr von meinem Volk infizieren soll. Ich kann nicht widerstehen, daher verfasste ich diese Schriftrolle, ehe es um meine Willenskraft geschehen ist.\n\nIch habe hinter dieser Gruft eine Truhe neben einem Wagen in der Erde vergraben, aber nur mein Schlüssel kann sie öffnen. Ich habe den Schlüssel. Wenn Ihr meinen Schatz möchtet, sucht mich.\n\nTötet mich. Bevor es zu spät ist.", sourceObjective = "Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe.", progress = "Die hier vergrabene Truhe ist fest verschlossen.", completion = "Hameyas Truhe wurde geöffnet!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[6025] = { id = 6025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Was? Wirklich? Ihr möchtet noch mehr wissen? Aber Ihr habt bereits so viel für mich getan, {name}. Ich kann Euch unmöglich darum bitten, an meiner statt nach Herdweiler zu gehen.\n\nSeid Ihr sicher, {name}? Herdweiler ist viel gefährlicher als der Pass - ich kann Euch weder Schutz noch Informationen geben, was Ihr da vorfinden könntet.\n\nAlso, wenn Ihr wirklich bereit seid, mir zu helfen, dann geht in die Stadt und sucht eine erhöhte Stelle, von der aus Ihr einen guten Überblick habt. Dort könnt Ihr ihre Zahl abschätzen und mir dann Bericht erstatten. Aber seid vorsichtig...", sourceObjective = "Geht nach Herdweiler, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Grubenschatten in den Westlichen Pestländern zurück.", completion = "Ihr habt es geschafft, {name}! Danke!\n\nIch kehre zu Elling zurück... Ich meine nach Stormwind, so schnell ich kann. Hier, nehmt diese Münze, das ist das Mindeste, was ich für Euch tun kann. Ihr macht Eurem Volk Ehre, {name}. Habt Dank, und viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[6026] = { id = 6026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist viel verlangt", description = "Diese Leute von der Argentumdämmerung haben den alten Smokey beauftragt, ein paar Abrissarbeiten für sie durchzuführen. Smokeys Mama hat keinen Trottel großgezogen. Wenn bares Gold auf den Tisch gelegt wird, ist Smokey stets zu Diensten. Das ist mein Motto!\n\nIch wäre bereit, den Profit mit Euch zu teilen, wenn Ihr mir ein wenig zuarbeiten wollt. Das ist der Plan: Ich geh rüber in den Pestwald und kennzeichne die Gebäude, die abgerissen werden müssen. Ihr sammelt die Komponenten für die Bomben. Wir treffen uns hier wieder, wenn Ihr alles habt. Abgemacht?", sourceObjective = "Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.\n\nFür diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden.", progress = "Vertraut dem alten Smokey, {race}. Es wird sich lohnen. Die Leute von der Argentumdämmerung machen kein Gewese, was Bezahlung angeht.", completion = "Ich bezahle Euch eine Hälfte gleich und die andere, wenn die Aufgabe erledigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[6027] = { id = 6027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Buch der Uralten", description = "{name}, ich vertraue Euch den Edelstein der Schlange an. Legt diesen Edelstein auf der Insel Ranazjar nordwestlich von hier in die Hand der Schlangenstatue. Dadurch wird jener gerufen, der das 'Buch der Uralten' beschützt. Dieses Buch birgt die Geheimnisse der Naga. Geheimnisse, die seit Jahrhunderten gewahrt werden. Bringt mir dieses Buch, dann werden wir mehr über unsere schuppigen Widersacher erfahren!", sourceObjective = "Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück.", progress = "Ah, {name}! Schön, Euch zu wiederzusehen. Habt Ihr das 'Buch der Uralten'?", completion = "Das lange verschollene 'Buch der Uralten'! Ich werde dafür sorgen, dass der Hohe Rat dieses Buch bekommt. Ihr habt heute Großes vollbracht, und dafür muss man Euch danken... wie man einem Helden dankt!", sourceObjectiveStatus = "unverified-source-field" }
quests[6028] = { id = 6028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bericht der Ewigen Warte", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung der Ewigen Warte. Ich muss Argentumoffizier Reinherz im Zugwindlager einen Fortschrittsbericht zukommen lassen. Das ist weit entfernt von hier am südlichen Rand der Westlichen Pestländer.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meiner Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihr zu bekommen!", sourceObjective = "Bringt den Bericht der Ewigen Warte zu Argentumoffizier Reinherz im Zugwindlager in den Westlichen Pestländern.", progress = "Seid gegrüßt, {class}. Im Namen der Argentumdämmerung biete ich Euch Sicherheit und Unterkunft, solange Ihr hier im Chillwind-Lager seid. Vielleicht habe ich auch ein bisschen Arbeit für Euch...", completion = "Gregor ist außerordentlich findig. Er hat schon seit geraumer Zeit mit dem Steamwheedle-Kartell zu tun und ist ein Experte in der 'Kunst' von Goblin-Verhandlungen geworden. Es stimmt zwar, dass die Goblins weitgehend denen mit den größten Geldbörsen gegenüber loyal sind, aber sie kennen und achten auch den Wert der Diplomatie. Sie bringt ihnen immerhin Kunden ein, die wiederkommen ...\n\nWie auch immer, die Argentumdämmerung dankt Euch für Eure Bemühungen. Bitte nehmt dies mit unserem Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[6029] = { id = 6029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Bericht der Ewigen Warte", description = "Ich suche ein verantwortungsbewusstes Individuum, das mir in einer kleinen, aber dennoch wichtigen Angelegenheit hilft. Ich bin hier als Vertreter der Argentumdämmerung und ihrer Interessen in der Lokalverwaltung der Ewigen Warte. Ich muss Argentumoffizier Garush beim Bollwerk einen Fortschrittsbericht zukommen lassen; das ist weit entfernt von hier am westlichen Rand der Westlichen Pestländer, östlich von Tirisfal.\n\nWenn ich so kühn sein darf - dies wäre eine perfekte Möglichkeit, Euch meinem Vorgesetzten vorzustellen und vielleicht etwas Arbeit von ihm zu bekommen!", sourceObjective = "Bringt den Bericht der Ewigen Warte zu Argentumoffizier Garush im Bollwerk in den Westlichen Pestländern.", progress = "Seid gegrüßt, {class}. Im Namen der Argentumdämmerung biete ich Euch Sicherheit und Unterkunft, solange Ihr hier im Bollwerk seid. Ich könnte Euch auch die Möglichkeit bieten, für eine Sache zu kämpfen, für die es sich zu kämpfen lohnt!", completion = "Gregor ist außerordentlich findig für einen Menschen. Er hat schon seit geraumer Zeit mit dem Steamwheedle-Kartell zu tun und ist ein Experte in der 'Kunst' von Goblin-Verhandlungen geworden. Es stimmt zwar, dass die Goblins weitgehend denen mit den größten Geldbörsen gegenüber loyal sind, aber sie kennen und achten auch den Wert der Diplomatie. Sie bringt ihnen immerhin Kunden ein, die wiederkommen ...\n\nWie auch immer, die Argentumdämmerung dankt Euch für Eure Bemühungen. Bitte nehmt dies mit unserem Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[6030] = { id = 6030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürst Nicholas Zverenhoff", description = "Ein einsiedlerisches Medium namens Umbranse, das in dieser Gegend ansässig ist, hat der Argentumdämmerung ein literarisches Meistwerk geschenkt... es handelt sich vermutlich um die größte Sammlung mündlicher Überlieferungen, die je zu Papier gebracht wurde.\n\nFürst Nicholas Zverenhoff, einer der angesehensten Anführer der Dämmerung, ist ein brillanter Sprachwissenschaftler. Könntet Ihr ihm das für mich bringen - natürlich gegen eine Belohnung? Bei der Kapelle des Hoffnungsvollen Lichts, tief im östlichen Teil der Östlichen Pestländer - da hält er sich gerade auf.", sourceObjective = "Bringt das Buch 'Studien über das Geistsprechen' zu Fürst Nicholas Zverenhoff in der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", progress = "Möge das Licht Euch in diesen gefährlichen Zeiten leiten, {class}. Was führt Euch zu diesem Fanal der Hoffnung inmitten von Dunkelheit und Verzweiflung?", completion = "Das... ist ein ganz besonderes Buch, das Ihr mir da gebracht habt. Ich würde Euch gern sagen, dass 'besonders' in diesem Fall 'einzigartig und höchstwahrscheinlich lehrreich' bedeutet, doch das wird man sehen.\n\n\"Ooooooh?\" Wer sich so etwas ausdenkt, kann doch nicht bei klarem Verstand sein?\n\nAber ich habe von diesem Umbranse gehört, von dem Gregor sprach, daher ist das hier nicht ganz wertlos. Ich tue mein Bestes, es zu entziffern. Und was Euch angeht... bitte nehmt dies... mit freundlichen Grüßen der Argentumdämmerung. Da Ihr schon mal hier seid, vielleicht könnt Ihr uns noch bei anderen Dingen unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6031] = { id = 6031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runenstoff", description = "Wir in der Holzschlundfeste sind eigentlich ganz zufrieden. Wir mögen keine Fremden. Das ist gut für uns, aber schlecht für das Geschäft.\n\nEs ist noch nicht lange her, da kam eine Nachtelfenfreundin, die einen Runenumhang trug, auf die Holzschlundfeste. Runenstoff ist bei uns selten, aber der Umhang war so edel, dass mein Volk jetzt von mir verlangt, mehr Runenstoffkleidung zu fertigen.\n\nWerdet Ihr mir Runenstoff bringen? Wenn Ihr mir ausreichend beschafft, gebe ich Euch etwas im Tausch dafür.", sourceObjective = "Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste.", progress = "Habt Ihr den Runenstoff? Mein Volk ist ganz gierig nach weiteren Kleidungsstücken aus Runenstoff!", completion = "Ah, Ihr habt den Stoff. Was für ein herrliches Material!\n\nDanke, {name}. Ihr seid ein wahrer Freund. Bitte nehmt dies als Gegenleistung.", sourceObjectiveStatus = "unverified-source-field" }
quests[6032] = { id = 6032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochheiliger Stoff", description = "Die Einwohner der Holzschlundfeste mögen das Gefühl von Runenstoff auf der Haut, aber er ist nichts Hochheiliges für uns. Mondstoff dagegen ist hochheilig.\n\nBringt mir einen kleinen Vorrat dieses heiligen Stoffs und ich lehre Euch eine geheime Schneidertechnik.", sourceObjective = "Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste.", progress = "Habt Ihr den Mondstoff dabei, {name}?", completion = "Ah, sehr gut. Dieser Mondstoff wird für Gewänder benutzt, die für unser Volk hochheilig sind. Danke, {name}. Jetzt werde ich Euch ausbilden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6041] = { id = 6041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Smokey Sings, I Get Violent", description = "Während Ihr die Vorräte gesammelt habt, habe ich einige meiner Leute die Geißelbauwerke kennzeichnen lassen, die wir abreißen müssen.\n\nSo ist der Plan: Ich gebe Euch zehn Stecken meines speziellen Präparats. Ihr bringt sie rüber in den Pestwald und platziert sie in den Geißelbauwerken, die für die Sprengung markiert wurden.\n\n<Smokey schnippt mit den Fingern.>\n\nBing! So einfach ist das.", sourceObjective = "Reist in den Pestwald, nordwestlich der Kapelle des Hoffnungsvollen Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.\n\nWenn Ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.\n\nÜbrigens, Smokeys spezielles Präparat ist recht...instabil.", completion = "Ihr seid viel dunkler als ich in Erinnerung habe. Der Look steht Euch nicht schlecht, ein Look, der sagt: 'Ich wurde von einer hochexplosiven Bombe angesengt.'\n\n<Smokey lacht.>\n\nNa, egal! Hier ist Euer Anteil an der Beute. Ich habe noch eine Kleinigkeit dazu gelegt, die die Verbrennungen lindert.", sourceObjectiveStatus = "unverified-source-field" }
quests[6042] = { id = 6042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die kleinen Ärgernisse des Un-Lebens", description = "Man kann keine zwei Schritte von diesem Hof runter, ohne auf eine dieser grässlichen Fledermäuse zu stoßen. Ich möchte die Hunde ausführen und die Geißel abschlachten können, ohne dass mich diese elenden, schmutzigen Fledermäuse behelligen. Ich habe Wichtigeres mit meiner Zeit anzufangen, als tagein, tagaus sinnlos Fledermäuse zu töten. Ihr allerdings nicht.\n\nWas? Eure Ausbildung? Das ist Eure Ausbildung! Jetzt geht mir aus den Augen und kommt erst zurück, wenn Ihr eine ordentliche Menge dieser geflügelten Dämonen getötet habt! Enttäuscht mich nicht.", sourceObjective = "Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr fertig seid.", completion = "Unglaublich, was ein wenig Zorn und Wut doch bewirken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[6061] = { id = 6061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Für uns als Tauren ist es wichtig, dass wir den Traditionen unserer Vorfahren folgen und gegen mächtige Kreaturen kämpfen. Wenn wir diese Kreaturen bezwingen, können wir ihre Geister aufnehmen und näher bei der Erdenmutter sein.\n\nAuf dieselbe Weise hilft es uns, eins mit der Natur zu werden, wenn wir ein Tier zähmen, damit es an unserer Seite kämpft. Ihr werdet auch irgendwann lernen, ein Tier Eurer Wahl zu zähmen. Aber alles erfordert Übung und Ihr müsst noch viel lernen. Nehmt als erstes diese Zähmrute. Ihr müsst einen ausgewachsenen Ebenenschreiter zähmen.", sourceObjective = "Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", progress = "Übt Eure Fertigkeiten, {name}. Zähmt den ausgewachsenen Ebenenschreiter.", completion = "Die Erdenmutter hat mir Zeichen geschickt. Ihr habt Eure Sache gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[6062] = { id = 6062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Es ist eine bewundernswerte Fertigkeit, wenn man über die Natur gebietet. Als Jäger müsst Ihr lernen, wie man Macht und Kraft benutzt, die jeder Kreatur Eurer Wahl innewohnt.\n\nEs ist nicht einfach, Kontrolle über ein Tier zu erlangen. Ihr müsst diese Aufgabe mit großer Entschlossenheit verfolgen.\n\nAls erste Aufgabe nehmt diese Zähmrute und zähmt damit einen scheckigen Terroreber. Ihr findet sie in der Nähe von Klingenhügel. Übt Eure Fertigkeiten im Kampf mit dem Eber an Eurer Seite und kommt dann zu mir zurück.", sourceObjective = "Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", progress = "Viel Glück, junger {class}.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Ich glaube, Ihr seid bereit für die nächste Aufgabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[6063] = { id = 6063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Als Jäger dürft Ihr niemals die Verantwortung vergessen, die Ihr tragt. Die Natur ist eine Kraft, die sich nicht Euren Wünschen beugt. Man muss sie respektieren und anerkennen als etwas Stärkeres als die eigene Existenz.\n\n{name}, Ihr müsst beweisen, dass Ihr das verstanden habt, bevor Ihr die Fähigkeit erwerben könnt, Euch ein Tier als Gefährten zu zähmen.\n\nEure erste Aufgabe ist es, diese Zähmrute zu nehmen. Mit ihr könnt Ihr einen Waldweberlauerer zähmen. Zähmt ihn und übt Eure Fertigkeiten als Jäger.", sourceObjective = "Benutzt die Zähmrute, um einen Waldweberlauerer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", progress = "Ihr werdet lernen, {name}, und eines Tages ein großer {class} sein.", completion = "Exzellent, {name}! Ihr lernt wirklich sehr schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[6064] = { id = 6064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Hallo, <Bursche/Mädchen>! Ihr wollt also wissen, wie Ihr ein eigenes Tier bekommen könnt?\n\nGut, dann lasst uns anfangen. Wenn es um das Jagen geht, dann ist nichts wichtiger als Eure Ausrüstung, aber wir können ein andermal über meinen neuen Schrapnell-Blaster sprechen. Konzentrieren wir uns vorerst auf etwas, das Euch gewiss interessiert: ein Tier!\n\nAm besten lernt Ihr, wenn Ihr verschiedene Kreaturen als Gefährten ausprobiert und herausfindet, welche Ihr mögt. Sucht also einen großen Klippeneber und benutzt dann diese Zähmrute, um ihn zu zähmen.", sourceObjective = "Benutzt die Zähmrute, um einen großen Klippeneber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos.", progress = "Keine Bange, Bursche! Ihr könnt ein paar ausprobieren, ehe Ihr Euch für eines entscheiden müsst.", completion = "Ich weiß, ich weiß, Ihr fragt Euch, was als nächstes kommt, was?!", sourceObjectiveStatus = "unverified-source-field" }
quests[6065] = { id = 6065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", sourceObjectiveStatus = "unverified-source-field" }
quests[6066] = { id = 6066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", sourceObjectiveStatus = "unverified-source-field" }
quests[6067] = { id = 6067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Yaw Scharfmähne im Dorf der Bluthufe aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Yaw Scharfmähne im Dorf der Bluthufe in Mulgore.", sourceObjectiveStatus = "unverified-source-field" }
quests[6068] = { id = 6068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Thotar in Klingenhügel in Durotar.", completion = "Ja, ich glaube auch, Ihr seid bereit...", sourceObjectiveStatus = "unverified-source-field" }
quests[6069] = { id = 6069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Thotar in Klingenhügel in Durotar.", completion = "Ja, ich glaube, Ihr seid bereit für die Ausbildung...", sourceObjectiveStatus = "unverified-source-field" }
quests[6070] = { id = 6070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Thotar in Klingenhügel besuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Thotar in Klingenhügel in Durotar.", sourceObjectiveStatus = "unverified-source-field" }
quests[6071] = { id = 6071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", completion = "Ja, es ist an der Zeit, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6072] = { id = 6072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", sourceObjectiveStatus = "unverified-source-field" }
quests[6073] = { id = 6073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, so jung und schon auf der Jagd. Ihr seht mir talentiert genug aus, um ein Tier zu führen und es zu Eurem Gefährten abzurichten.\n\nIhr müsst Dazalar in Dolanaar aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Dazalar in Dolanaar in Teldrassil.", completion = "Ja, es ist an der Zeit, Euch auszubilden...", sourceObjectiveStatus = "unverified-source-field" }
quests[6074] = { id = 6074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", sourceObjectiveStatus = "unverified-source-field" }
quests[6075] = { id = 6075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", completion = "Ja, ich glaube, es ist an der Zeit, dass Ihr ausgebildet werdet...", sourceObjectiveStatus = "unverified-source-field" }
quests[6076] = { id = 6076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Jägers", description = "Hallo, junger Jäger. Ihr seht mir aus, als wärt Ihr geschickt genug, ein Tier zu Eurem Gefährten auszubilden.\n\nIhr müsst Grif Wildherz in Kharanos aufsuchen. Er kann Euch auf den Weg zu einem eigenen Tier führen.", sourceObjective = "Sprecht mit Grif Wildherz in Kharanos in Dun Morogh.", completion = "Ja, {class}, es ist Zeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[6081] = { id = 6081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es auszubilden.\n\nReist nach Orgrimmar. Dort müsst Ihr mit Ormak Grimmschlag sprechen, einem unserer angesehensten Jäger. Er wird Euch die Fähigkeit verleihen, Euer neues Tier auszubilden. Ihr findet ihn im Tal der Ehre.\n\nViel Glück, {name}.", sourceObjective = "Sprecht mit Ormak Grimmschlag in Orgrimmar.", completion = "Ein junger {class} seid Ihr, ich verstehe. Ja, ich gewähre Euch die Fertigkeiten, die Ihr braucht, um Euer neues Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nGeht jetzt, {class}. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[6082] = { id = 6082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Die letzte Kreatur, die Ihr zähmen müsst, wird dasselbe mit Euch versuchen: der gepanzerte Skorpid. Er schlägt schnell und selbstbewusst zu. Eine solche Macht zu kontrollieren ist Euer Schicksal als Jäger.\n\nWenn Ihr zurückkehrt verleihe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird Euren Befehlen gehorchen. Unter Eurer Kontrolle wird Euer Tier an Eurer Seite Erfahrung sammeln. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", sourceObjective = "Benutzt die Zähmrute, um einen gepanzerten Skorpid zu zähmen. Übt Eure Fertigkeiten und kehrt zu Thotar in Klingenhügel zurück.", progress = "Konntet Ihr den Skorpid zähmen?", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, {name}. Es ist Zeit, dass Ihr das Gelernte anwendet und Euch ein eigenes Tier wählt.\n\nHier, bitte schön, {name}. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz; Ihr habt sie Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[6083] = { id = 6083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Der Vorteil, den Euch ein Tier gegen Eure Rivalen bietet, wird zur Kenntnis genommen, {name}! Wenn Ihr Kontrolle über eine andere Kreatur erlangt, erhöht Ihr Eure eigene Kraft. Euer Tier muss sozusagen Euer verlängerter Arm werden.\n\nDie nächste Aufgabe führt Euch vom Land weg. Ihr findet die nächste Kreatur in den Gewässern vor der Küste. Sucht jenseits von Sen'jin nahe den Echoinseln. Sucht nach einem lebhaften Krebs, der Brandungskriecher genannt wird. Benutzt die Zähmrute, um ihn zu zähmen und übt dann Eure Fertigkeiten.", sourceObjective = "Benutzt die Zähmrute, um einen Brandungskriecher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel.", progress = "Ihr müsst üben, damit Ihr die Fertigkeiten erlangt, die Ihr braucht, um Euer Tier wirksam zu kontrollieren. Habt Ihr schon einen Brandungskriecher gezähmt?", completion = "Ihr lernt schnell, {name}. Das habt Ihr gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[6084] = { id = 6084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Diese Klippeneber sind recht bullig. Vielleicht möchtet Ihr etwas mit ein wenig mehr Grazie? Na gut, da hab ich genau das Richtige. Südlich und östlich von hier findet Ihr große weiße Katzen, die man Schneeleoparden nennt. Genau wie bei einem elegant geschnitzten Gewehr verbirgt sich hinter dem wunderschönen Äußeren ein kräftiger Kämpfer, der extremen Schaden zufügen kann. Ihr werdet feststellen, dass sie wesentlich agiler und schneller als Euer gezähmter Eber sind.\n\nNehmt diese Zähmrute und findet heraus, wie Euch der Schneeleopard gefällt.", sourceObjective = "Benutzt die Zähmrute, um einen Schneeleoparden zu zähmen. Übt Eure Fertigkeiten und kehrt dann zu Grif Wildherz in Kharanos zurück.", progress = "Was haltet Ihr von dem Schneeleoparden, {name}?", completion = "Wenn ich glaube, dass Ihr genug gelernt habt, gewähre ich Euch die Fähigkeit, jedes Tier zu wählen, das Euch gefällt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6085] = { id = 6085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Vielleicht hättet Ihr gern eine Kreatur, die etwas mehr besitzt als nur rohe Kraft? Der Eisklauenbär ist ein ausgezeichneter Gefährte für einen angehenden Jäger wie Euch und östlich von Kharanos zu finden. Hier ist die Zähmrute. Probiert dieses Geschöpf als Euer Tier aus und findet heraus, wie es Euch gefällt!\n\nWenn Ihr zurückkehrt, gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man sie ganz nach Belieben ruft und wegschickt.", sourceObjective = "Benutzt die Zähmrute, um einen Eisklauenbären zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Grif Wildherz in Kharanos.", progress = "Habt Ihr den Eisklauenbären schon gezähmt?", completion = "Hier, bitte schön, {name}. Ich geb Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken.\n\nSucht Euch ein gutes, treues Tier und genießt die Jagd!", sourceObjectiveStatus = "unverified-source-field" }
quests[6086] = { id = 6086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung des Tiers", description = "{name}, Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr müsst die Fertigkeiten erlangen, es auszubilden.\n\nReist nach Eisenschmiede und sucht die Halle der Waffen. Dort müsst Ihr mit Belia Donnerstein sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Macht, Euer neues Tier auszubilden, also macht Euch auf den Weg, <Bursche/Mädchen>.\n\nBelia ist recht umgänglich, Ihr findet gewiss ihre Zustimmung. Viel Glück, {name}.", sourceObjective = "Sprecht mit Belia Donnerstein in Eisenschmiede.", completion = "Ein neuer Rekrut, hm? Ich sehe, Ihr seid auf dem Weg, ein großer {class} zu werden.\n\nJa, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nVergesst nicht, Euer neues Tier wird Euch stets zu Diensten sein, wenn Ihr es respektiert und gut behandelt. Dann wird Euer Tier Euer treuester Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[6087] = { id = 6087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Ihr besitzt einen feurigen Geist, Jäger, und brennt schon auf Eure nächste Herausforderung.\n\nAls nächste Aufgabe müsst Ihr einen Wolf, der als Präriepirscher bekannt ist, zum Gefährten gewinnen. Diese Kreatur ist flink und furchtlos. Wenn Ihr diese Bestie als Euer Tier wollt, müsst Ihr diese Eigenschaften ebenfalls erlangen.\n\nIm Kampf werdet Ihr lernen, wie Ihr und Euer Tier ein Team werdet. Letztendlich müsst Ihr wie ein Wesen handeln, Muskel an Muskel.\n\nHier habt Ihr die Zähmrute, {name}. Zähmt einen Präriepirscher und übt Eure Fertigkeiten.", sourceObjective = "Benutzt die Zähmrute, um einen Präriepirscher zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", progress = "Habt Ihr schon einen Präriepirscher gefunden?", completion = "Ja... Die Erdenmutter glaubt, Ihr seid bereit für die nächste Lektion.", sourceObjectiveStatus = "unverified-source-field" }
quests[6088] = { id = 6088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Die letzte Aufgabe, die ich für Euch habe, verlangt von Euch, dass Ihr eine Kreatur zähmt, die den Himmel bewohnt. Der Sturzflieger ist ein schwieriger Gegner, aber als Euer Verbündeter gibt er Euch seine scharfen Angriffe und seine bedrohliche Präsenz.\n\nWenn Ihr zurückkehrt gebe ich Euch durch den Willen der Erdenmutter die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", sourceObjective = "Benutzt die Zähmrute, um einen Sturzflieger zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe.", progress = "Ihr werdet bald bereit sein, {name}.", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, {name}. Möge der Segen der Erdenmutter Euch bei der Wahl Eures Tiers leiten.\n\nHier, bitte schön, {name}. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz und ehrt die Erdenmutter.", sourceObjectiveStatus = "unverified-source-field" }
quests[6089] = { id = 6089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Donnerfels. Dort müsst Ihr mit Holt Donnerhorn sprechen, einem unserer angesehensten Jäger. Wenn er Euch für würdig befindet, gibt er Euch die Fähigkeit, Euer neues Tier auszubilden.\n\nHolt hat die mächtigsten und gefürchtetsten Bestien von Azeroth bezwungen und befehligt selbst viele starke Kreaturen. Seine Verbundenheit mit der Erdenmutter ist stark. Ihr könnt viel von ihm lernen. Viel Glück, {name}.", sourceObjective = "Sprecht mit Holt Donnerhorn auf der Anhöhe der Jäger in Donnerfels.", completion = "Ein junger {class} seid Ihr, ich verstehe. Ja, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nGeht jetzt. Möge die Erdenmutter Euch auf Eurem Weg geleiten. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[6101] = { id = 6101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Auf die Vielfalt der Natur kann man sich verlassen, {name}. Sie ist insofern vorhersehbar, dass sie niemals gleich bleibt. Sie ist in konstantem Wandel.\n\nDie Aufgaben, die ich Euch gebe, werden Euch helfen, die enormen Unterschiede der Kreaturen zu erkennen, die Ihr als Eure Gefährten wählen könnt.\n\nNehmt diese Zähmrute und zähmt damit einen der pirschenden Nachtsäbler, die im Süden zu finden sind. Übt Eure Fertigkeiten als Jäger. Dann werdet Ihr die Übereinstimmungen und Unterschiede der Natur begreifen.", sourceObjective = "Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", progress = "Es liegt in der Natur jedes Nachtelfen, dass er das Gleichgewicht zwischen der Natur und sich selbst begreift.", completion = "Ich sehe, dass Ihr entschlossen seid und verstanden habt, was ich Euch gelehrt habe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6102] = { id = 6102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zähmung der Bestie", description = "Ihr habt zwei Kreaturen gezähmt, die am Boden leben, jetzt müsst Ihr eine zähmen, die am Himmel dahinzieht. Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen, die man westlich von hier findet. Übt Eure Fertigkeiten mit dieser mächtigen Eule an Eurer Seite.\n\nWenn Ihr zurückkehrt gebe ich Euch die Fertigkeiten, die Ihr braucht, um ein Tier Eurer Wahl als Gefährten zu zähmen. Diese Kreatur wird denselben Herausforderungen trotzen wie Ihr und an Eurer Seite Erfahrung gewinnen. Ich zeige Euch auch, wie man es nach Belieben ruft und wegschickt.", sourceObjective = "Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar.", progress = "Ich bin stolz auf Eure Leistungen, {name}. Habt Ihr die letzte Aufgabe vollendet, die ich Euch gab?", completion = "Ihr habt gelernt, was ich Euch beibringen konnte, {name}. Lasst mich Euch noch einen Rat geben: Seid umsichtig, wenn Ihr Euer erstes Tier wählt. Soll es eine Kreatur des Landes, des Wassers oder des Himmels sein? Was auch immer, Euer Tier wird zweifellos eine ganze Weile bei Euch sein.\n\nHier, bitte schön, {name}. Ich gebe Euch jetzt die Macht, ein Tier zu zähmen und es nach Belieben zu rufen und wegzuschicken. Benutzt Eure neuen Fertigkeiten voller Stolz; Ihr habt sie Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[6103] = { id = 6103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung des Tiers", description = "Ihr habt jetzt die Macht, ein Tier zu zähmen, aber Ihr benötigt auch die Fertigkeiten, es zu trainieren.\n\nReist nach Darnassus. Dort müsst Ihr mit Jocaste sprechen, einer unserer angesehensten Jägerinnen. Sie gibt Euch die Fähigkeit, Euer neues Tier auszubilden, also sputet Euch.\n\nJocaste mag einen strengen Eindruck machen, freut sich aber stets, wenn sie den Aufstieg eines neuen Jägers verfolgen kann. Behandelt sie mit Respekt, dann wird sie Euch ebenso begegnen. Viel Glück, {name}.", sourceObjective = "Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus.", completion = "Ein angehender {class} seid Ihr, ich verstehe. Ja, ich kann Euch die Fertigkeiten verleihen, die Ihr braucht, um Euer Tier auszubilden und zu führen. Ihr werdet Eurem Tier nicht nur neue Fähigkeiten beibringen können, sondern Ihr könnt es auch füttern und wiederbeleben, sollte es im Kampf fallen.\n\nDenkt daran, {name}, respektiert stets das Gleichgewicht und lebt in Ehrfurcht vor der Natur ringsum. Geht jetzt. Wir sprechen uns zu einem späteren Zeitpunkt wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[6121] = { id = 6121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Lektionen", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, {name}. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um... und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist zur Mondlichtung und sprecht mit Dendrite Sternenschauer. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", sourceObjective = "Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen.", completion = "Seid gegrüßt, junger {class}, ich sehe mit Freuden, dass Ihr begierig seid, etwas über die Heilung von Vergiftungen zu lernen.\n\nFrüher wurden die meisten Druiden vorab geplanten Prüfungen unterzogen, doch das trifft auf Euch nicht zu. In Auberdine traten vermehrt Fälle von Tiervergiftungen auf und die Dorfbewohner konnten sie nicht heilen. Aus diesem Grund bat ein Repräsentant Moonglade um Hilfe. Wir schicken Euch zu ihrer Unterstützung dorthin. Dies ist keine Übung - es handelt sich um eine echte Aufgabe. Vergesst das nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[6122] = { id = 6122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die eigentliche Ursache", description = "Die Klippenquellfälle in Dunkelküste dienen als wichtigste Trinkwasserquelle in der Region. Ich fürchte, jetzt ist es die primäre Ursache des Gifts, das der dortigen Fauna schadet, besonders dem Wild. Holt mit diesem Gefäß etwas Wasser vom Höhleneingang, aber seid vorsichtig, inzwischen hausen gefährliche Naga in einer Höhle bei den Wasserfällen.\n\nWenn Ihr es gefüllt habt, bringt es zu Alanndarian Nachtweise in Auberdine. Sie bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihr dieses Übels annehmen.", sourceObjective = "Benutzt das leere Gefäß bei den Klippenquellfällen und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.\n\nBringt die gefüllte Probe der Klippenquellfälle zu Alanndarian Nachtweise nach Auberdine in Dunkelküste.", progress = "Seid Ihr vom Zirkel des Cenarius in Moonglade geschickt worden? Das ist wunderbar! Wir haben hier eine echte Krisensituation, was das Wild angeht, und sind dankbar für jedwede Hilfe.\n\nHabt Ihr die Probe des Wassers, wie Dendrite Starblaze sagte? Er informierte mich, dass Ihr eine besorgen würdet, damit wir gemeinsam ein Heilmittel finden ...", completion = "Bei Elune, dieses Wasser ist widerwärtig! Kein Wunder, dass das Wild krank ist.\n\nEtwas verunreinigt das Wasser und damit Dunkelküstes gesamten Wasservorrat. Man hat überall in der Gegend krankes Wild gesehen, nicht nur am Fluss. Das Wasser ist wahrscheinlich der Hauptgrund für die Ausbreitung der Krankheit, aber hier wirkt noch etwas anderes.\n\nDieses Wasser wird uns, ob Ihr es glaubt oder nicht, ein Heilmittel finden helfen. Während ich dieses Wasser untersuche benötige ich einige Zutaten für ein Heilmittel...", sourceObjectiveStatus = "unverified-source-field" }
quests[6123] = { id = 6123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Heilmittel sammeln", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für das Wild anrühre. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn wir Pech haben und Ihr keiner seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nUnd der besseren Wirksamkeit wegen brauche ich etwas Lunarfungus. Es ist recht leicht, Lunarfungusblüten zu finden. In den Höhlen östlich von hier gedeihen sie reichlich. Mondkin, die neuerdings recht gereizt sind, hausen in diesen Höhlen, also seid vorsichtig.", sourceObjective = "Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nachtweise in Auberdine, damit sie eine Heilsalbe machen kann.", progress = "Habt Ihr die Reagenzien bekommen, die ich für meine Salbe brauche? Das Wild wird von allein ganz bestimmt nicht wieder gesund, daher sollten wir uns besser beeilen!", completion = "Das ist gut, {name}, so sehr, dass es für eine gehörige Portion Salbe reichen müsste - wenigstens so viel, dass eine Wirkung zu spüren ist.\n\nManchmal kann es recht schwer sein, ein Heilmittel für Gifte herzustellen, da nicht selten jedes einzelne ein ganz bestimmtes Gegenmittel erfordert. Stellt Euch vor, man könnte ein Gift durch Willenskraft heilen, ohne dass man sich Gedanken über die exakte Zusammensetzung des Gegenmittels machen müsste!\n\nUnd jetzt lasst mich daran arbeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[6124] = { id = 6124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung der Kranken", description = "Die Salbe, die ich aus den Reagenzien herstellen konnte, die Ihr mir gebracht habt, reicht für zehn Dosen, {name}. Ich arbeite weiter mit den Dorfbewohnern zusammen und versuche mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um Dunkelküste wimmelt es von krankem Wild. Heilt es mit der Salbe von seinem Übel.\n\nDendrite Sternenschauer bei der Mondlichtung wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius Auberdines Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", sourceObjective = "Benutzt die heilende Tiersalbe bei 10 kränklichen Rehen in ganz Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass kränkliche Rehe südlich des Klippenquells, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo das Eschental beginnt, aufgetaucht ist.", completion = "Ihr habt bei der Heilung des kranken Wilds von Dunkelküste wahre Wunder gewirkt. Es war das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. In Darnassus gibt es welche, die die Bedrohung ernst nehmen... und es gibt welche, die ignorieren die zunehmenden Zeichen... Ich hoffe, Ihr werdet nicht die Augen vor dem Offensichtlichen verschließen, {name}.\n\nWie auch immer, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[6125] = { id = 6125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht über Gift", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Mathrengyl Bärenfährte in Darnassus zurückkehren, {name}. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", sourceObjective = "Kehrt zu Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus zurück.", completion = "Willkommen - ich verfolge Eure Fortschritte in dieser Lektion seit Eurem Aufbruch und muss gestehen, ich war überrascht, als ich von der Situation in Auberdine erfuhr. Dies erfordert weitere Untersuchungen, da die Freisetzung solcher Gifte in die Umwelt das Gleichgewicht empfindlich stört.\n\nIhr habt Euch unter großem Druck wacker gehalten. Dafür finde ich keine bessere Möglichkeit, als Euch mit permanenter Macht über Gift zu belohnen. Verwendet sie weise, {name}... verwendet sie weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[6126] = { id = 6126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neue Lektionen", description = "Ihr seid jetzt bereit, alles über Gifte und die Macht zu lernen, die wir Druiden darüber haben, {name}. Cenarius hat uns mit der Fähigkeit gesegnet, selbst die abscheulichsten Gifte mit einer Beschwörung auszutreiben. Mit dieser Gabe geht man nicht leichtfertig um...und damit Ihr diese Lektion lernt, müsst Ihr die Wirkung von Giften behandeln wie es ein Laie tun würde.\n\nReist zur Mondlichtung und sprecht mit Dendrite Sternenschauer. Er erwartet Eure Ankunft, um die Lektion zu beginnen.", sourceObjective = "Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen.", completion = "Seid gegrüßt, junger {class}, ich sehe mit Freuden, dass Ihr begierig seid, etwas über die Heilung von Vergiftungen zu lernen.\n\nFrüher wurden die meisten Druiden vorab geplanten Prüfungen unterzogen, doch das trifft auf Euch nicht zu. Bei Crossroads im Brachland traten vermehrt Fälle von Tiervergiftungen auf, die nicht unter Kontrolle zu bringen sind. Jemand dort bat Moonglade um Hilfe. Wir schicken Euch zu ihrer Unterstützung dorthin. Dies ist keine Übung - es handelt sich um eine echte Aufgabe. Vergesst das nicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[6127] = { id = 6127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die eigentliche Ursache", description = "Der Glutnebelgipfel nordwestlich des Wegekreuzes ist höchstwahrscheinlich die Quelle, von wo aus sich das Gift verbreitet. Auf seinen luftigen Höhen gibt es Teiche, die das Wetter beeinflussen. Dieses Wasser wurde vermutlich durch Dämonen anbetende Kultisten der Brennenden Klinge verunreinigt.\n\nEntnehmt dem Teich auf der Spitze des Gipfels mit diesem Behältnis eine Probe. Wenn es gefüllt ist, bringt es zu Tonga Runentotem beim Wegekreuz. Er bat um unsere Hilfe und Ihr werdet Euch gemeinsam mit ihm dieses Übels annehmen.", sourceObjective = "Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.\n\nBringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runentotem beim Wegekreuz im Brachland.", progress = "Seid Ihr vom Zirkel des Cenarius in Moonglade geschickt worden, ja? Das ist ein Glück für uns! Unsere Bemühungen, den kranken Gazellen im nördlichen Brachland Gleichgewicht zu bringen, haben nichts genutzt. Wir sind für jede Hilfe dankbar.\n\nHabt Ihr die Probe des Wassers, wie Dendrite Starblaze sagte? Er informierte mich, dass Ihr eine besorgen würdet, damit wir gemeinsam ein Heilmittel finden...", completion = "Bei meinen Vorfahren, dieses Wasser ist widerwärtig! Kein Wunder, dass die Gazellen krank sind.\n\nEtwas verunreinigt das Wasser und zerstört damit langsam das Ökosystem im nördlichen Brachland. Überall nördlich der Ost-West-Straße wurden kranke Gazellen gesehen. Das Wasser ist wahrscheinlich der Hauptgrund für die Ausbreitung der Krankheit, aber hier wirkt noch etwas anderes.\n\nDieses Wasser wird uns, ob Ihr es glaubt oder nicht, ein Heilmittel finden helfen. Während ich dieses Wasser untersuche benötige ich einige Zutaten für ein Heilmittel...", sourceObjectiveStatus = "unverified-source-field" }
quests[6128] = { id = 6128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Heilmittel sammeln", description = "Das Wasser wird Grundlage einer Heilsalbe sein, die ich für die Gazellen herstelle. Für die Heilwirkung benötige ich etwas Erdwurzel. Kräuterkundige wissen, wo man sie finden kann. Wenn Ihr nicht mit dieser Kunst vertraut seid, müsst Ihr einen suchen, der uns weiterhilft.\n\nDer Wirksamkeit wegen brauche ich zuletzt Kodohörner – Splitter und Bruchstücke reichen aber nicht aus. Kodos, mit denen Ihr fertigwerdet, streifen durch den nördlichen Teil des Brachlands. Erlegt welche zum Wohle des Gleichgewichts, {name}, und bringt mir die Hörner.", sourceObjective = "Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runentotem beim Wegekreuz, damit er eine Heilsalbe machen kann.", progress = "Habt Ihr die Reagenzien bekommen, die ich für meine Salbe brauche? Die Gazellen werden von allein ganz bestimmt nicht wieder gesund, daher sollten wir nicht zaudern im Bemühen, sie zu retten!", completion = "Das ist gut, {name}, so sehr, dass es für eine gehörige Portion Salbe reichen müsste - wenigstens so viel, dass eine Wirkung zu spüren ist.\n\nManchmal kann es recht schwer sein, ein Heilmittel für Gifte herzustellen, da nicht selten jedes einzelne ein ganz bestimmtes Gegenmittel erfordert. Stellt Euch vor, man könnte ein Gift durch Willenskraft heilen, ohne dass man sich Gedanken über die exakte Zusammensetzung des Gegenmittels machen müsste!\n\nUnd jetzt lasst mich daran arbeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[6129] = { id = 6129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilung der Kranken", description = "Ich konnte genügend Salbe für zehn heilende Dosen machen, {name}. Ich arbeite weiter mit den hiesigen Behörden zusammen und versuche, mehr Salbe herzustellen. Derweil möchte ich, dass Ihr uns einen Vorsprung verschafft. Rund um das Nördliche Brachland wimmelt es von kranken Gazellen. Heilt sie mit der Salbe von ihrem Übel.\n\nDendrite Sternenschauer bei der Mondlichtung wird ganz sicher mit Euch reden wollen, wenn Ihr fertig seid. Bitte übermittelt dem Zirkel des Cenarius unseren Dank... und lasst mich Euch persönlich für Eure Hilfe danken!", sourceObjective = "Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße beim Wegekreuz gesehen.", completion = "Ihr habt bei der Heilung der kranken Gazellen des Brachlands wahre Wunder gewirkt. Sie waren das arglose Opfer einer größeren Besudelung und Verderbnis geworden, die sich über das Land ausbreitete. Ihr {race} brennt darauf, die Wege des Cenarius zu verstehen. Ihr habt, wie Eure Ältesten in Thunder Bluff, den Beweis angetreten, dass die Notwendigkeit des Gleichgewichts künstliche Barrieren zwischen den Völkern überwindet.\n\n{name}, Ihr habt Euren Wert als Freund der Natur und des Zirkels unter Beweis gestellt - nehmt dies als Symbol dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[6130] = { id = 6130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Macht über Gift", description = "Ihr habt gelernt, was es heißt, Vergiftungen ohne spirituelle Unterstützung zu heilen. Vergesst nicht, was andere auf sich nehmen müssen, wenn sie gegen Vergiftungen ankämpfen, wenn Ihr Eure neu erlangte Macht über Gift erhaltet.\n\nIhr solltet jetzt zu Turak Runentotem in Donnerfels zurückkehren, {name}. Zweifellos hat er Euch wichtige Zauber beizubringen, da Ihr nun die Lektionen begriffen habt, die Ihr erhieltet.\n\nLebt wohl, junger Druide. Wir sprechen uns wieder.", sourceObjective = "Kehrt zu Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels zurück.", completion = "Willkommen - ich verfolge Eure Fortschritte in dieser Lektion seit Eurem Aufbruch und muss gestehen, ich war überrascht, als ich von der Situation in Crossroads erfuhr. Dies erfordert weitere Untersuchungen, da die Freisetzung solcher Gifte in die Umwelt das Gleichgewicht empfindlich stört.\n\nIhr habt Euch unter großem Druck wacker gehalten. Dafür finde ich keine bessere Möglichkeit, als Euch mit permanenter Macht über Gift zu belohnen. Verwendet sie weise, {name}... verwendet sie weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[6131] = { id = 6131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbündeter der Holzschlundfeste", description = "Die Einwohner der Holzschlundfeste sind die einzigen Furbolgs, die von der Verderbnis verschont blieben. Aber viele andere Völker töten die Furbolgs jetzt blindwütig und scheren sich nicht darum, ob sie Freund oder Feind sind. Deswegen trauen die Furbolgs der Holzschlundfeste auch kaum jemandem.\n\nSeid Ihr daran interessiert, Euch zu beweisen? Treibt den verderbten Stamm der Totenwaldfelle vom Teufelswald zurück, dann betrachten wir Euch eines Tages vielleicht als Verbündeten. Ihr findet den ersten Stamm der Totenwaldfelle - Krieger, Pfadfinder und Gärtner - westlich von hier.", sourceObjective = "Grazle möchte, dass Ihr Euch beweist, indem Ihr 5 Krieger der Totenwaldfelle, 5 Pfadfinder der Totenwaldfelle und 5 Gärtner der Totenwaldfelle besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6132] = { id = 6132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt mich hier raus!", description = "Holt mich hier raus!\n\nIch kam ins Tal der Speere, um mit den Maraudines zu sprechen. Ich dachte, ich könnte Geschäfte mit ihnen machen... aber sie reden einfach nicht mit mir! Ich glaube, sie möchten mich eher verspeisen!\n\nHolt mich hier raus, mein Bruder Hornizz wird es Euch reich vergelten! Er ist in unserem Lager neben dem Kodofriedhdof im Osten.\n\nBeeilen wir uns, {name}. Es ist keine zwei Minuten her, da hörte ich einige Zentauren sagen, dass sie Holz für ihren Kochtopf sammeln möchten...", sourceObjective = "Eskortiert Melizza Brummsumms und sprecht anschließend mit Hornizz Brummsumms beim Kodofriedhdof Desolace.", completion = "Meine Schwester Melizza sagte, dass Ihr kommen würdet. Danke, dass Ihr sie aus dieser misslichen Lage befreit habt. Vermutlich steckt sie leider schon wieder in einer neuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6133] = { id = 6133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ersuchen des Waldläuferlords", description = "Die Hochelfen der Jagdhütte von Quel'Lithien haben etwas, das mir gehört, {class}: Ein Dokument, das mein Leben als Sterblicher schildert.\n\nBevor Ihr fragt, Ihr seid wahrscheinlich nicht befugt, derlei Informationen zu bekommen. Macht einfach, was ich Euch sage, Wurm: Holt den Lebenslauf zurück.\n\nUnd, Schwachkopf, richtet so viel Not und Elend an, wie Ihr könnt. Lasst sie leiden...", sourceObjective = "Begebt Euch zur nördlichsten Grenze der Östlichen Pestländer und bringt die Registratur von Quel'Thalas zurück. Der Gegenstand befindet sich irgendwo in der Jagdhütte von Quel'Lithien.\n\nAußerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten.", progress = "Lasst mich nicht warten, {class}.", completion = "Ich gehe davon aus, dass Ihr den Lebenslauf nicht gelesen habt. Nicht einmal Ihr würdet etwas so Idiotisches machen...", sourceObjectiveStatus = "unverified-source-field" }
quests[6134] = { id = 6134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geisterplasmasuche", description = "Im Südosten liegt ein Tal, das Tal der Knochen, das von den Geistern der Magram heimgesucht wird. Klingt gruselig, nicht wahr? Stellt Euch mal vor, wie sich die Magram erst gruseln müssen! Wenn wir Geisterenergie an jenem Ort einfangen könnten, wäre das den Zentauren sicher einiges wert.\n\nHier, nehmt diese Kiste mit Geistermagneten. Wenn Ihr einen zwischen den beiden großen Skeletten im Tal aufstellt, den toten Goliaths, dann werden sich Geister materialisieren und dorthin gehen. Nehmt Abstand, schaltet die Geister aus und holt Euch ihr Geisterplasma - das verkaufen wir den Magram.", sourceObjective = "Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brummsumms in Desolace.", progress = "Wo ist mein Geisterplasma, {name}?", completion = "Da ist es! Sieht aus, als hättet Ihr auch etwas davon abbekommen. Irgendwie schleimig, hm?\n\nJedenfalls vielen Dank für Eure Mühe, {name}. Dieses Zeug ist ein Vermögen wert... wenn ich die Zentauren überzeugen kann, dass es echt ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[6135] = { id = 6135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämmerschwinge, oh, wie ich Euch hasse...", description = "Bisher habt Ihr die Missionen abgeschlossen, die ich Euch aufgab, wenn Ihr auch nicht unbedingt ein Ausbund an Pünktlichkeit seid.\n\nIhr denkt wahrscheinlich, dass Ihr bereit für eine Herausforderung seid. Ja... ja, Schwachkopf, vielleicht seid Ihr wirklich für anspruchsvollere Missionen bereit.\n\nDämmerschwinge, der Albinofledermausdämon, streift nördlich von hier durch das Land. Spürt ihn auf und besiegt ihn. Kehrt mit einem Büschel seines weißen Fells zu mir zurück und Ihr sollt eine Belohnung erhalten.", sourceObjective = "Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Pestrufer.\n\nMan sagt, dass Dämmerschwinge nördlich von hier durch das Land streift.", progress = "Ich würde Euch nicht raten, dass Ihr Euch dieser Herausforderung allein stellt, {class}.", completion = "Gut gemacht, Schwachkopf. Ich fertige aus diesem Fell etwas an, das Ihr brauchen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6136] = { id = 6136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Korpulente", description = "Hinter der Kapelle des Hoffnungsvollen Lichts, dem Lager der Argentumdämmerung, und westlich vom Nordtal, findet Ihr die wohlbeleibte Madenbestie Blutschlinger.\n\nIch habe ganze Regimenter an dieses Monster verloren. Sein Leibesumfang ist gewaltig! Und je mehr er frisst, um so größer wird er...\n\nEs würde mir keine schlaflosen Nächte bereiten, sollte die Bestie Euch verschlingen, dennoch sähe ich es lieber, wenn Ihr der Sieger wärt. Man weiß, dass Blutschlinger schon andere verschlungen hat, die töricht genug waren, ihn anzugreifen.", sourceObjective = "Sucht in den nördlichen Wüsten der Östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Pestrufer zurück, sobald Ihr diese Mission erledigt habt.", completion = "Macht weiter so und ich muss Euch vom Schwachkopf zum Hirnamputierten erster Klasse befördern.", sourceObjectiveStatus = "unverified-source-field" }
quests[6141] = { id = 6141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder Anton", description = "Bruder Anton, mein Waffenbruder, hörte Gerüchte über einen Angriff der Untoten im fernen Kalimdor, in einem Land, das Desolace genannt wird. Anton buchte sofort eine Überfahrt dorthin, um die Bedrohung durch die Untoten zu lokalisieren und zu beseitigen!\n\nEr sucht Leute mit viel Tapferkeit und Entschlossenheit, die ihm dabei helfen. Wenn Ihr aufrichtigen Herzens seid, dann sprecht mit Anton. Er befindet sich in Desolace in einer Stadt der Allianz namens Nijelspitze.", sourceObjective = "Sprecht mit Bruder Anton in Desolace.", completion = "Ich habe Kunde erhalten, dass Unterstützung von Osten kommt. Stammen diese Gerüchte vielleicht von Euch? Seid Ihr hierher gekommen, um dem Scharlachroten Bruder bei seinem Kreuzzug zu helfen?\n\nWenn ja, dann hört gut zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[6142] = { id = 6142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muschelköder", description = "Ihr seht wahrlich aus wie ein Angler, {class}! Ich angle zu gern - schon mein Leben lang. Als Köder eignet sich das Fleisch der weichschaligen Muschel am besten. Die Fische können ihm einfach nicht widerstehen. Wisst Ihr, was ich meine?\n\nOben im Norden findet Ihr ein Schiffswrack vor der Küste. In der Gegend wimmelt es von weichschaligen Muscheln. Wenn Ihr mir 10 Teile Fleisch der weichschaligen Muschel bringt, werde ich Euch etwas dafür geben.", sourceObjective = "Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Schattenflucht.", progress = "Ich kann es kaum erwarten, mit etwas frischem Fleisch der weichschaligen Muschel angeln zu gehen. Habt Ihr mir die 10 Teile gebracht, die ich brauche?", completion = "Perfekt, Mann, genau das hat mir der Hexendoktor gegen meine Kopfschmerzen verschrieben. Er sagt: 'Mai'Lahii - geh angeln. Dann geht es dir besser.'\n\nAlso, mir geht es jetzt schon besser, danke, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[6143] = { id = 6143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andere Fische zu grillen", description = "Vielleicht habt Ihr es ja gehört, vielleicht auch nicht... meine Besatzung und ich waren vor der Insel Ranazjar fischen, nördlich des Schiffswracks vor der Küste im Norden. Wir haben immer dort gefischt, jetzt suche ich nur eine Möglichkeit, wie ich meine gefallenen Kameraden rächen kann.\n\nDie Naga haben uns eines Morgens angegriffen und alle außer mir getötet.\n\nDie Schuld lastet mir schwer auf der Seele, {class}; ihr müsst losziehen und diese Naga für mich grillen. Ich werde Euch für die Mühe belohnen. Meint Ihr, Ihr könnt mir behilflich sein?", sourceObjective = "Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Schattenflucht.", completion = "So süß die Neuigkeit ist, dass die Naga ausgelöscht wurden, mein Herz ist immer noch schwer. Ich werde den Rest meines Lebens danach trachten, sie alle auszurotten.\n\nHier, wie versprochen Eure Belohnung. Eine Kleinigkeit im Vergleich zu der Genugtuung, dass die Naga für ihre abscheuliche Untat an meiner Mannschaft büßen mussten.", sourceObjectiveStatus = "unverified-source-field" }
quests[6144] = { id = 6144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl", description = "Der Befehl ist gekommen, {class}. Bragor Blutfaust selbst hat verlangt, dass ich meine 'tüchtigsten' Agenten auf eine höchst diffizile taktische Mission nach Unterstadt schicke.\n\nLeider wurden meine tüchtigsten Agenten alle vor drei Jahren getötet. An ihrer Stelle habe ich eine Bande hirntoter Trottel.\n\n<Nathanos schaut Euch kalt an.>\n\nReist sofort nach Unterstadt und erstattet Bragor Blutfaust Bericht. Macht mir keine Schande, {class}!", sourceObjective = "Reist nach Unterstadt und sprecht mit Bragor Blutfaust.", completion = "Der oberste Kreuzzügler sitzt wohlbehalten in der Scharlachroten Bastion, während seine Streitkräfte in unser Land einfallen, unsere Gebäude und Denkmäler entweihen und unser Volk ermorden.\n\nDie Dunkle Fürstin hat befohlen, dass ich mich ein für alle Mal um dieses Insekt kümmere. Ihr sollt zum Instrument der Abrechnung mit den Verlassenen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[6145] = { id = 6145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Purpurrote Kurier", description = "So wie niemand ohne den Kopf überleben kann, kann der Kopf nicht ohne den Körper überleben. Die Verteidigungsanlagen des Scharlachroten Kreuzzugs in Stratholme sind fast unüberwindbar. Stattdessen müssen wir den Körper unter dem Kopf abschneiden.\n\nMeine Todespirscher haben Daten über die Aktivitäten des Kreuzzugs außerhalb von Stratholme gesammelt. Jeden Tag wird ein Bericht aus ihrer Befehlszentrale nach Tyrs Hand geschickt. Dieser Bericht ist der Schlüssel, {race}! Sucht den Purpurroten Kurier und beschafft diesen Bericht. Bringt ihn zu Nathanos.", sourceObjective = "Kehrt in die Östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des Obersten Kreuzfahrers.\n\nBringt den Befehl zu Nathanos Pestrufer und wartet auf weitere Anweisungen.", progress = "Wenn Euch das gelingt, habt Ihr Euch fast meinen Respekt verdient, {class}.", completion = "<Nathanos lacht.>\n\nExzellent! Endlich! Eine Gelegenheit, das Scharlachrote Orakel zu vernichten!", sourceObjectiveStatus = "unverified-source-field" }
quests[6146] = { id = 6146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nathanos' List", description = "Ich habe diesen Befehl etwas modifiziert. Sollte unsere kleine List wirken, wird das Scharlachrote Orakel schutzlos sein und wir schlagen zu!\n\nPasst jetzt genau auf, {class}. Ihr werdet diesen Befehl dem Kreuzzüglerlord Valdelmar überbringen.\n\nWie? Ihr drückt ihm das Ding in die Hand, Schwachkopf.\n\nBringt den Befehl und diesen faulen Apfel nach Tyrs Hand. Wenn Ihr in der Stadt seid, dann esst den Apfel. Ihr werdet Euch in etwas verwandeln, das für Menschen...verträglicher ist. Nehmt den Befehl und übergebt ihn dem Kreuzzüglerlord Valdelmar.", sourceObjective = "Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des Obersten Kreuzfahrers.", progress = "Das ist nicht akzeptabel, Soldat!", completion = "Wo seid Ihr gewesen? Wir dachten schon, die Geißel hätte Euch erwischt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6147] = { id = 6147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Nathanos zurück.", description = "Der oberste Kreuzzügler bringt eine ungewöhnliche Bitte vor. Hrm, wie dem auch sei... was er verlangt, soll geschehen. Kehrt zur Scharlachroten Bastion zurück und lasst ihn wissen, dass das Orakel sich bald auf den Weg machen wird.\n\nWir werden alle Vorsichtsmaßnahmen treffen, damit sie es unbeschadet nach Stratholme schafft.", sourceObjective = "Kehrt mit der neuen Information zu Nathanos Pestrufer zurück.", completion = "Diese Narren! Meine Täuschung ist nicht aufgefallen! Macht Euch bereit, {class}. Wir müssen mit kalter List zuschlagen!", sourceObjectiveStatus = "unverified-source-field" }
quests[6148] = { id = 6148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das scharlachrote Orakel Demetria", description = "Demetria ist die oberste Beraterin des Obersten Kreuzfahrers. Ihrer 'überirdischen' Sinne wegen nennt man sie das Orakel. Sie hat den Kreuzzug erfolgreich zu mehreren Siegen gegen die Geißel geführt.\n\nWir konnten sie zwar mit dieser List herauslocken, aber wenn sie wirklich eine übersinnliche Begabung besitzt, wird sie zweifellos mit Ärger rechnen. Ihr werdet für diesen 'Ärger' sorgen.\n\nSpürt das Orakel auf und beendet ihre Existenz. Sie müssten in diesem Moment von Tyrs Hand aufbrechen. Macht mich stolz, Wurm.", sourceObjective = "Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr erfolgreich wart.", completion = "Von diesem Schlag werden sie sich jahrelang nicht erholen! Gut gemacht, {name}! Ihr habt Euch nicht nur meinen Respekt verdient, sondern auch diese Belohnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[6161] = { id = 6161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt Rackmores Schatz!", description = "Aus Rackmores Logbuch geht hervor, dass sein Schiff zur Mondfederfeste segelte, als es von seefahrenden Kreaturen angegriffen wurde. Er versteckte seine Truhe auf der Insel Ranazjar, damit sein Schatz dem Feind nicht in die Hände fallen sollte.\n\nZwei Schlüssel, ein silberner und ein goldener, sind erforderlich, um die Truhe zu öffnen. Diese Schlüssel gingen verloren, doch wenn Schlüssel und Truhe gefunden werden, winkt ein Schatz!", sourceObjective = "Sucht Rackmores Silberschlüssel. Sucht Rackmores goldenen Schlüssel. Sucht und öffnet Rackmores Truhe.", progress = "Diese Truhe ist sicher verschlossen.", completion = "Die Truhe geht auf und gibt Rackmores Schatz preis!", sourceObjectiveStatus = "unverified-source-field" }
quests[6162] = { id = 6162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eines Ehemanns letzter Kampf", description = "Mein Gatte reiste unserem Klan zu Ehren durch den Teufelswald und kämpfte gegen den Schattenrat und andere verderbte Monstrositäten!\n\nAls er dem Tod viele Male entronnen war, erhielt ich einen Brief von ihm, in dem stand, dass ein Druide ihn um Beistand gegen einen großen beschmutzten Furbolg namens Oberanführer Ror gebeten hatte - man hörte nie wieder etwas von ihnen.\n\nIch möchte die Klauenhand dieses Ror, {name}. Er soll dafür büßen, dass er mich zur Witwe gemacht hat! Ich glaube, die Kreatur ist im Süden... nahe der Grenze des Eschentals.", sourceObjective = "Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald.", progress = "Habt Ihr den Kopf der Bestie schon, {name}? Sie wird für ihre Verbrechen büßen. Mir ist egal, ob sie verderbt oder nur wütend ist, weil sie in diesem garstigen Wald hausen muss. Kein Furbolg, der solche Verbrechen an meiner Familie begeht, darf überleben!", completion = "Ihr macht mir Ehre, indem Ihr zu Eurem Wort steht. Mein Mann fiel im Kampf - er wäre stolz darauf gewesen. Aber ich könnte keine Ruhe finden, wenn ich nicht wüsste, dass die Kreatur, die mich zu meinem Witwendasein verdammte, nicht für ihre Tat bezahlt hätte.\n\nNochmals danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6163] = { id = 6163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramstein", description = "Ich war überwältigt. Ich stand in dieser Siedlung... und blieb standhaft bei der Verteidigung von Lordaeron. Der Hof und alles darauf wurde von einer gigantischen Welle der Geißel belagert.\n\nDer Dreck. Der Schmutz. Er stand über mir und die Eingeweide hingen ihm aus einem klaffenden Loch in der Brust.\n\nIch erwachte als Geißel. Lange Zeit war ich hilflos. Meine Gedanken waren mit denen des Lichkönigs verschmolzen.\n\nSie kam zu mir... irgendwo, irgendwie wusste ich es. Frei.\n\nDoch jetzt muss ich meine Rache haben - Rache an dem, der mir das Leben genommen hat. Vernichtet ihn.", sourceObjective = "Reist nach Stratholme und tötet Ramstein den Verschlinger. Bringt seinen Kopf als Souvenir zu Nathanos.", progress = "Als Sylvanas mich befreit hatte, jagte ich die Bestie monatelang durch diese Wüste. Er floh ins sichere Stratholme. Der Bastard...", completion = "Ich frage mich... hat es um Gnade gewinselt? Wusste es überhaupt, was Gnade ist?\n\n<Nathanos spuckt aus.>\n\nIch werde den Kopf dieser Bestie an meine Wand hängen.\n\nIhr habt Euch einen Platz unter meinen Helden verdient, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6164] = { id = 6164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augustus' Quittungsbuch", description = "Ich bin jetzt bereit fürs Geschäftliche! Was wollt Ihr?\n\nOh, Moment mal... ohne mein Quittungsbuch kann ich kein Geschäft eröffnen. Wie soll ich ohne mein Quittungsbuch den Überblick behalten?\n\nIch muss es in der Stadt gelassen haben. Ich hatte ein Zimmer im Gasthaus... dort muss das Buch sein.\n\nBringt mir mein Buch. Bitte, bringt es mir! Bringt mir mein Buch und Ihr werdet sehen! Ich eröffne mein Geschäft und Ihr werdet sehen, dass meine Preise der WAHNSINN sind!", sourceObjective = "Beschafft Euch Augustus' Quittungsbuch aus dem Gasthaus im Schreckenstal.", progress = "Habt Ihr mein Quittungsbuch? Ich will endlich wieder an die Arbeit gehen!", completion = "Da ist es! Oh meine Güte! Ich hatte vergessen, wie voll es war!\n\nDies ist ein glorreicher Tag, {name}! Toll! Wahnsinnig gut, sage ich Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[6181] = { id = 6181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine eilige Nachricht", description = "Wir bekommen zwar nicht viel Unterstützung von Sturmwind direkt, aber ich habe einen Kontaktmann in der Stadt, der uns mit Rüstungen versorgt. Sein Name ist Osric Strang. Sein Geschäft, Begrenzte Immunität, liegt in der Altstadt von Sturmwind.\n\nUnser Vorrat an Rüstung schwindet, ich muss bei Osric mehr bestellen. Könnt Ihr ihm diese Notiz bringen?\n\nDer schnellste Weg nach Sturmwind führt über Thor, unseren Greifenmeister. Er ist unten am Hügel; bringt ihm meine Notiz und nehmt dann einen Greifen nach Sturmwind.", sourceObjective = "Bringt Lewis' Notiz zu Thor dem Greifenmeister.", progress = "Ihr seht aus, als hättet Ihr es eilig. Tja, dann seid Ihr hier genau richtig!", completion = "Ihr müsst diese Notiz nach Stormwind bringen? Das ist kein Problem, Ihr könnt einen meiner Greifen nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[6182] = { id = 6182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Erste und Letzte", description = "Nathanos Marris war der erste und letzte Waldläuferlord der Menschen. Ein Schüler von Sylvanas Windläufer, die heute Bansheekönigin der Verlassenen ist.\n\nWir dachten, Nathanos sei fünf Jahre zuvor bei der Verteidigung von Lordaeron in der Schlacht gefallen. Sein Leichnam wurde zwar nie gefunden, aber man ging davon aus, dass er es nicht aus den Östlichen Pestländern hinaus geschafft hatte.\n\nMathias Shaw hat sein Verschwinden untersucht und könnte neue Informationen haben. Meldet Euch sofort bei ihm. Er lebt in der Altstadt, in der Kaserne.", sourceObjective = "Sprecht mit Meister Mathias Shaw in der Altstadt von Sturmwind. Er wohnt in der Kaserne.", completion = "Nach einigen Berichten über ungewöhnliche Aktivität der Verlassenen in den östlichen Pestländern wurden Agenten von SI:7 zu Ermittlungen hingeschickt. Die Resultate dieser Ermittlungen sind beunruhigend.", sourceObjectiveStatus = "unverified-source-field" }
quests[6183] = { id = 6183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehret die Toten", description = "Fünf meiner besten Agenten wurden dem Fall Marris zugeteilt. Einer kam zurück und starb drei Tage später im Schlaf.\n\nDie wenigen Informationen, die wir aus ihm herausbekamen, waren unverständliches Gestammel. Wir haben zwei Worte verstanden: 'Nathanos' und 'Pestrufer'.\n\nIch habe nicht genügend Leute, um die Ermittlungen fortzusetzen, und Rabenholdt ist uns nicht behilflich. Wir müssen der Sache auf den Grund gehen, und wenn es nur ist, damit wir den Familien der Verstorbenen Trost spenden können. Werdet Ihr helfen?", sourceObjective = "Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt.", completion = "<Mathias nickt.>\n\nIch war gewiss, dass Bolvar mir ehrenhafte Männer und Frauen schicken würde - die treuesten Soldaten der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[6184] = { id = 6184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flint Schattenmoor", description = "Die einzige Information, die wir bislang haben, ist die, dass Nathanos Marris von diesem Pestrufer ermordet worden sein könnte. Wir gehen davon aus, dass Pestrufer derselbe Teufel ist, der meine Agenten beseitigt hat.\n\nFlint Schattenmoor, ein weiterer Agent des SI:7, ist im Lager der Allianz an der Zugwindspitze in den Westlichen Pestländern stationiert. Sucht ihn auf. Er wird Euch in die aktuelle Situation in den Pestländern einweihen und Euch einen Auftrag erteilen.\n\nViel Glück, {name}.", sourceObjective = "Reist zum Zugwindlager in den westlichen Pestländern und trefft Euren Kontaktmann Flint Schattenmoor.", completion = "Eure erste Mission ist kurz und knapp, {name}. Ihr geht rein, ihr geht raus. Aufklären...", sourceObjectiveStatus = "unverified-source-field" }
quests[6185] = { id = 6185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Östlichen Pestländer", description = "Wie gesagt, Eure erste Mission ist eine Aufklärungsmission. Nichts Kompliziertes, {name}. Ihr müsst in die Östlichen Pestländer reisen und nach Hinweisen auf diesen Pestrufer suchen.\n\nHaltet nach Informationen über unsere vermissten Agenten Ausschau. Wir müssen davon ausgehen, dass sie tot sind, und wenn sie tot sind, muss es Leichen geben...irgendwo.\n\n<Flint schluckt schwer.>\n\nAlle SI:7-Agenten tragen diese Insignien.\n\n<Flint zeigt Euch seine SI:7-Insignien.>\n\nBringt alle zu mir zurück, die Ihr finden könnt.", sourceObjective = "Sucht in den östlichen Pestländern nach Hinweisen auf den 'Pestrufer' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Schattenmoor am Zugwindlager.", progress = "G... Glück gehabt???", completion = "Rutger. Fredo. Turyen. Alle... tot...\n\n<Flint umklammert die Insignien.>\n\nWo waren sie? Habt Ihr weitere Informationen über diesen Dreckskerl, diesen Blightcaller, gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[6186] = { id = 6186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pestrufer kommt", description = "<Flints Gesicht wird schlagartig leichenblass.>\n\nNa... Nathanos ist das gewesen? Nathanos ist der Pestrufer?\n\nWarum? Er war... war so edel – ein Waldläuferlord, den alle geachtet haben. Der einzige Mensch, der je bei den Hochelfen ausgebildet wurde. Der soll jetzt ein ruchloser Agent der Verlassenen sein?\n\nIch... Ich bin untröstlich, dass ich das von Euch verlangen muss, {name}, aber König Wrynn muss unverzüglich über diese Wendung der Ereignisse informiert werden. Bitte kehrt nach Sturmwind zurück und überbringt diese Nachricht.", sourceObjective = "Kehrt nach Sturmwind zurück und informiert König Varian Wrynn über das Schicksal von Nathanos Marris.", completion = "Nein. Es... NEIN! Wie? Ein Agent der Verlassenen? Der HELD der Bansheekönigin???\n\n<Hochlord Bolvar Fordragon sackt geknickt in sich zusammen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[6187] = { id = 6187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ordnung muss wiederhergestellt werden", description = "Wisst Ihr, wie viele Waldläuferlords es auf dieser Welt gibt? Wie viele menschliche Waldläuferlords jemals existiert haben?\n\nNathanos' Errungenschaften waren beispiellos. Er war ein taktisches Genie und führte die Allianz in einem Jahrzehnt der Konflikte zu vielen Siegen.\n\nUnd jetzt... der Held der Verlassenen.\n\nNein. Das darf nicht sein. Die Ordnung muss wiederhergestellt werden.\n\nVersammelt eine Armee, {name}. Kehrt mit Eurer Armee in die Pestländer zurück und vernichtet den Pestrufer.\n\nIch wünsche Euch Glück, {name}. Das werdet Ihr für diesen Kampf wahrlich brauchen.", sourceObjective = "Stellt eine Armee auf und reist zu den Östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Pestrufer und jeden Abschaum der Horde, der ihn beschützen mag.\n\nBewahrt einen klaren Kopf, {name}. Die Horde wird den Waldläuferlord mit dem Leben verteidigen.", completion = "Das ist eine Tragödie. Ich glaube... Ich glaube, unsere Art ist verflucht, {name}. Wir sind verflucht, unsere größten Krieger zu verlieren, unsere edelsten Helden, unsere begabtesten Gelehrten.\n\nWir stehen in Eurer Schuld und ich versichere Euch, {name}, dass Nathanos Marris auf Euch herablächeln wird, wo immer er jetzt sein mag.", sourceObjectiveStatus = "unverified-source-field" }
quests[6221] = { id = 6221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totenwaldfelle des Nordens", description = "Direkt südwestlich von hier liegt ein Furbolglager der Totenwaldfelle. Ich bin nicht sicher, was sie vorhaben, aber ich würde dem gern einen Riegel vorschieben, ehe es zum Problem wird.\n\nDer Stamm der Totenwaldfelle ist böse, aber die Verderbnis ist es, die ihre Hirne verseucht. Ihre Feindseligkeit ist keine angeborene Eigenschaft, doch da kann man nichts machen. Aus diesem Grund stimmt es mich zutiefst traurig, dass ich gegen meine Geschwister kämpfen muss.\n\nBitte, {name}, tut, was getan werden muss, aber erspart mir die Einzelheiten. Sie beunruhigen mich zu sehr.", sourceObjective = "Nafien möchte, dass Ihr 5 Höhlenbehüter der Totenwaldfelle, 5 Rächer der Totenwaldfelle und 5 Schamanen der Totenwaldfelle besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6241] = { id = 6241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktivität der Winterfelle", description = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, {name}. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber wenn möglich andere Furbolgstämme.\n\nIn letzter Zeit ist mir aufgefallen, dass der Winterfellstamm uns gegenüber immer größere Feindseligkeit zeigt. Sie scheinen in Rage zu sein, und ganz von ihrem Hass auf alles beseelt, das sie nicht verstehen.\n\nWenn Ihr ihre Anzahl reduzieren könntet, würde uns das sehr helfen, {name}.", sourceObjective = "Salfa möchte, dass Ihr 6 Totemiker der Winterfelle, 6 Höhlenbehüter der Winterfelle und 6 Pfadfinder der Winterfelle erledigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6261] = { id = 6261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungar Trinkfest", description = "{name}, ich habe alles, worum Lewis gebeten hat, in diese Kiste gepackt. Würdet Ihr sie ihm bringen?\n\nWenn Ihr bereits mit Thor in Westfall gesprochen habt, dann könnt Ihr einen Greif zurück zu ihm nehmen. Dungar Trinkfest ist unser Greifenmeister drüben im Handelsdistrikt.\n\nSprecht mit Dungar, dann bringt diese Kiste auf dem schnellsten Weg zu Lewis. Wir möchten nicht, dass unsere kämpfenden Männer und Frauen in Westfall ohne neue Ausrüstung sind!", sourceObjective = "Bringt Osrics Kiste zu Dungar Trinkfest dem Greifenmeister.", progress = "Ist das Schweiß auf Eurer Stirn, der Herr? Ihr habt Euch beim Laufen zu sehr verausgabt. Nehmt nächstes Mal einen Greifen!", completion = "Eine Kiste für Westfall, eh? Seid Ihr schon mal in Westfall gewesen? Falls ja, ist das kein Problem. Ich habe viele Greifen ausgebildet, damit sie diese Route fliegen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[6281] = { id = 6281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiter nach Sturmwind", description = "Gegen eine geringe Gebühr könnt Ihr einen Greifen nach Sturmwind nehmen und so Lewis' Notiz zu Osric bringen. Einen schnelleren Weg gibt es nicht.\n\nWenn Euch das akzeptabel erscheint, sprecht mich wieder an, sobald Ihr bereit seid für den Flug. Das kostet eine Kleinigkeit, aber glaubt mir, es lohnt sich!", sourceObjective = "Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in der Altstadt von Sturmwind.", progress = "Ihr seid gereist, ja? Seid Ihr an irgendwelchen interessanten Orten gewesen?", completion = "Ah, eine Notiz von Quartiermeister Lewis? Es überrascht mich gar nicht, dass er mehr Ausrüstung braucht. Die Späherkuppe ist weit entfernt in einem Land, das Stormwind fast vergessen hat.\n\nIch danke Euch, {name}. Hier habt Ihr etwas Geld für Eure Reisespesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6282] = { id = 6282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpyien drohen", description = "Tauren sind die stolzen Beschützer dieser Länder. Zweifellos könnt Ihr erraten, warum mich die Anzahl der Harpyien hier im Steinkrallengebirge so beunruhigt.\n\nDie Blutfurien sind die Ursache für die zunehmende Zahl von Harpyien in Kalimdor. Sie bedrängen jede Lebensform und hindern Unschuldige daran, ihre Grenzen zu verlassen.\n\nIhr müsst die Harpyien für mich dezimieren, {name}!", sourceObjective = "Maggran Erdbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", completion = "Das sind wirklich ganz ausgezeichnete Nachrichten! Erzählt mir noch einmal, wie Ihr in den kalten Herzen dieser schändlichen Harpyien Furcht gesät habt. Die Blutfurien haben einen schweren Schlag erlitten!", sourceObjectiveStatus = "unverified-source-field" }
quests[6283] = { id = 6283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutfuriengeschlecht", description = "Es genügt nicht, die Anzahl der Blutfurienharpyien zu verringern. Die einzig wahre Kur für ihre Krankheit wäre es, ihre Anführerin zu beseitigen, die Zerfetzerin der Blutfurien!\n\nFür diese dreckigen Kreaturen ist sie so etwas wie eine Königin. Tötet sie und ihre Zahl wird ganz gewiss abnehmen.\n\nGeht zurück zum Verbrannten Tal, dort findet Ihr sie in den westlichen Hügeln. Sie wird nicht leicht zu bezwingen sein, aber die Belohnung ist groß.", sourceObjective = "Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt.", progress = "Die Zerfetzerin der Blutfurien ist ein garstiges Geschöpf! Ihr findet sie bestimmt entlang der westlichen Hügelkette im verbrannten Tal.\n\nDie Blutfurien werden ohne sie hilflos sein... gewiss können wir sie für alle Zeiten loswerden!", completion = "Ich spüre bereits, wie die Wut von mir weicht. Was soll ich mit meiner Zeit anfangen? Das Wissen, dass das Böse um mein Land schleicht, hielt meine Gedanken wach, doch nun sind sie verstummt. Vielleicht ist das ja gut so... vielleicht kann ich mich jetzt auf das Gute konzentrieren, was alle Tauren tun sollten.\n\nBitte nehmt das als Belohnung für Eure Mühe an.", sourceObjectiveStatus = "unverified-source-field" }
quests[6284] = { id = 6284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arachnophobie", description = "Warnung: Betretet den Sishircanyon westlich von hier auf eigene Gefahr.\n\nBesseleth und ihre achtbeinigen Kinder des Waldes haben diesen Canyon zu ihrem eingesponnenen Unterschlupf erkoren.\n\nMaggran Erdbinder in Sonnenfels hat ein Kopfgeld auf Besseleth ausgesetzt. Tötet sie und bringt einen Beweis Eurer Tat zu Maggran. Dort werdet Ihr eine Belohnung erhalten, wenn Ihr der achtbeinigen Gefahr ein Ende gemacht habt.", sourceObjective = "Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels.", progress = "Besseleth ist ein ruchloses Raubtier... Ich fürchte um alle, die nachts auf dem Weberpass reisen. Dann nämlich lauern sie und ihre Kinder arglosen Reisenden auf. Ich selbst wurde schon Opfer ihres tödlichen Fangzahns, der eine Elle lang ist, aber zum Glück konnte ich sie abwehren und mich in Sicherheit bringen. Ich würde alles dafür geben, wenn dieses Monster vernichtet würde.", completion = "Gute Jagd, {name}! Besseleth ist ein altes Raubtier in dieser Gegend... Ich werde sie nicht vermissen. Nehmt diese Belohnung als Zeichen dafür, dass Ihr der Held des Waldes seid.\n\n\n\nVielleicht werden jetzt viele nach Sonnenfels kommen und sich nicht mehr vor dem fürchten müssen, was in der Dunkelheit lauert.", sourceObjectiveStatus = "unverified-source-field" }
quests[6285] = { id = 6285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Lewis", description = "Der Greifenmeister in Westfall heißt Thor. Falls Ihr schon mit ihm gesprochen habt, dann könnt Ihr einen meiner Greifen zu ihm bringen.\n\nDas hier sollte man unbedingt wissen: Greifen sind stets so ausgebildet, dass sie in ihre Hauptstadt fliegen, aber sie bringen Euch nur zu einem außerörtlichen Greifenmeister, wenn Ihr schon einmal dort gewesen seid.\n\nIhr seid bereits bei Thor gewesen, sprecht daher einfach wieder mit mir, wenn Ihr bereit seid, einen Greifen nach Westfall zu nehmen. Dort könnt Ihr Osrics Kiste bei Rüstmeister Lewis abliefern.", sourceObjective = "Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Lewis an der Späherkuppe.", progress = "Ihr seid aus Stormwind zurück? Hat Osric die Rüstungen geschickt?", completion = "Großartig, Ihr habt die Rüstungen! Wir verteilen sie unverzüglich an alle, die sie brauchen.\n\nDanke, {name}. Ihr wart uns mit Euren Bemühungen eine große Hilfe. Jetzt, da Euch Greife nicht mehr fremd sind, kommt Ihr hoffentlich öfter und helft den Bewohnern der Späherkuppe!", sourceObjectiveStatus = "unverified-source-field" }
quests[6301] = { id = 6301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zyklus der Wiedergeburt", description = "Industrielle Gier und ständige Kriege haben die Länder des Steinkrallengebirges verwüstet. Nur der Segen der Erdenmutter kann solch eine Verletzung heilen.\n\n{name}, Ihr müsst für mich ein spezielles Samenkorn suchen, Gaeasamenkorn. Man findet diese Samenkörner nur hier im Steinkrallengebirge, nördlich von Sonnenfels am Mirkfallonsee, in der Nähe des Ufers.\n\nWenn Ihr mir die Samenkörner bringt, werde ich sie auf magische Weise mit schamanistischer Macht erfüllen, um ihr Wachstum zu beschleunigen.", sourceObjective = "Tammra Windfeld in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt.", progress = "Die ständige Zerstörung durch den Krieg und alle, die mit Holz Profit machen möchten, bekümmert mich zutiefst. Um den Zyklus der Wiedergeburt zu unterstützen und die Länder wieder zu bewalden, benötige ich Gaeasamenkörner. Habt Ihr sie, {class}?", completion = "Ah, {name}, Ihr habt die Gaeasamenkörner. Schaut zu und seht, wie der Segen der Erdenmutter sogar diese kleinen Samenkörner des Lebens blühen und gedeihen lassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[6321] = { id = 6321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für Brill", description = "Exekutor Zygand bat mich, eine Inventur unserer Ausrüstung hier in Brill durchzuführen. Da die Geißel und Schlimmeres in den Wäldern lauert, möchte er nicht, dass den Todeswachen Ausrüstung fehlt, die sie brauchen.\n\nIch habe festgestellt, dass wir im Großen und Ganzen gut bestückt sind, aber wir brauchen mehr Waffen als Ersatz für die, die wir auf dem Feld verloren haben.\n\nHier eine Anforderungsliste der benötigten Dinge für den Waffenhändler Gordon Wendheim in Unterstadt. Bringt die Anforderungsliste zur Fledermausführerin Anette und sprecht mit ihr über den Transport nach Unterstadt.", sourceObjective = "Bringt Morris' Anforderungsliste zu Fledermausführerin Anette.", progress = "Ihr scheint in einer offiziellen Angelegenheit hier zu sein...", completion = "Ah, eine Anforderungsliste für Vorräte. Die solltet Ihr wohl in die Undercity bringen. Und zwar rasch, denn das Grabmal darf nicht unterversorgt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[6322] = { id = 6322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Michael Garrett", description = "Ich habe den Nachschub für Brill in diese Kiste getan. Wenn Ihr Brill schon besucht und mit der Fledermausmeisterin gesprochen habt, könnt Ihr auf einer Fledermaus zu ihr reiten.\n\nSprecht mit Michael Garrett, dem Fledermausmeister von Unterstadt. Er kann Euch eine Fledermaus nach Brill zur Verfügung stellen.", sourceObjective = "Bringt Gordons Kiste zu Michael Garrett.", progress = "Wenn Ihr weite Strecken reisen müsst, dann ist eine Fledermaus das ideale Transportmittel.", completion = "Diese Kiste muss zum Grabmal im Silberwald? Nichts leichter als das, unsere Fledermäuse fliegen täglich dorthin.", sourceObjectiveStatus = "unverified-source-field" }
quests[6323] = { id = 6323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Unterstadt", description = "Eine meiner Fledermäuse kann Euch nach Unterstadt bringen. Normalerweise kosten diese Flüge eine geringe Gebühr, aber der Flug nach Unterstadt ist für <einen tapferen Streiter/eine hübsche Dame> wie Euch kostenlos, {race}. Sprecht mich wieder an, wenn Ihr bereit seid, damit wir Euren Transport arrangieren können.\n\nIhr findet Gordon Wendheim im Handwerksviertel von Unterstadt. In diesem Viertel landet auch meine Fledermaus.", sourceObjective = "Bucht einen Fledermausritt zur Unterstadt bei Fledermausführerin Anette und bringt dann Morris' Anforderungsliste zu Gordon Wendheim in Unterstadt.", progress = "Ich halte meine Waffen in einem Top-Zustand. Sie sind gereinigt und einsatzbereit.", completion = "Eine Anforderungsliste vom Grabmal? Wohlan denn. Es ist eine Ehre, denen zu dienen, die unserer Dunklen Fürstin dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6324] = { id = 6324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Morris", description = "Der Fledermausmeister in Brill ist Fledermausführerin Anette. Wenn Ihr schon bei ihr gewesen seid, dann gebe ich Euch eine Fledermaus, damit Ihr zu ihr fliegen könnt.\n\nUnsere Fledermäuse fliegen stets nach Unterstadt, aber um zu entlegeneren Orten zu reisen, muss ihr Reiter zuerst die Gegend besuchen und mit dem dortigen Fledermausmeister sprechen.\n\nIhr habt Anette in Brill getroffen, daher könnt Ihr jetzt mit Fledermäusen dorthin fliegen. Sprecht wieder mit mir, wenn Ihr bereit seid.", sourceObjective = "Bucht einen Fledermausritt nach Brill bei Fledermausmeister Michael Garrett und bringt dann Gordons Kiste zu Todeswache Morris in Brill.", progress = "{name}, Ihr kehrt zurück. Habt Ihr unseren Nachschub aus Undercity?", completion = "Gute Arbeit, {name}. Diese Waffen gewährleisten, dass unsere Todeswachen nicht unvorbereitet überrascht werden.\n\nIhr habt der Dunklen Fürstin einen wertvollen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[6341] = { id = 6341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf nach Darnassus", description = "Alle in Dolanaar sind so stolz auf Schwester Aquinne. Ich bin sicher, sie wird sich sehr freuen, dieses aufmerksame Geschenk von Nyoma zu erhalten.\n\nWenn Ihr bereit seid, nach Darnassus zu reisen, sprecht einfach wieder mit mir und für ein paar Münzen könnt Ihr einen Hippogryphen mieten, der Euch dorthin bringt. Man sagte mir, Schwester Aquinne genießt die Abgeschiedenheit eines kleinen Platzes südlich vom Hippogryphenmeister in Darnassus. Sucht dort nach ihr, wenn Ihr angekommen seid.", sourceObjective = "Sprecht mit Fidelio, um einen Flug nach Darnassus zu erstehen, und bringt dann die Rezeptsammlung von Dolanaar zu Schwester Aquinne in Darnassus.", progress = "Wie kann ich Euch helfen? Benötigt Ihr ein Transportmittel?", completion = "Ah, Ihr möchtet, dass dies nach Auberdine gebracht wird? Nun gut...", sourceObjectiveStatus = "unverified-source-field" }
quests[6342] = { id = 6342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwartetes Geschenk", description = "Das ist wundervoll! Genau das Richtige, um mich während meiner Studien im Tempel des Mondes an mein Zuhause zu erinnern. Ich werde eins der Rezepte heute Abend ausprobieren. Ich kann es kaum abwarten!\n\nWürdet Ihr diese kurze Dankesnachricht zu Nyoma zurückbringen? Ihr könnt einen Hippogryphen zurück nach Dolanaar mieten. Besucht einfach unsere Hippogryphenmeisterin, Leora, wenn Ihr zum Abflug bereit seid. Sie wird Euch mit einem Rückflug nach Dolanaar helfen.", sourceObjective = "Bringt Schwester Aquinnes Notiz zu Leora, der Hippogryphenmeisterin in Darnassus.", progress = "Kommt Ihr aus Teldrassil? Erzählt mir, wie angelt es sich dort?", completion = "Ein Päckchen von Nessa? Danke, {name}! Sie sagte mir, sie würde mir Exemplare der Fische schicken, die in der Nähe von Rut'theran gefangen werden. Sie glaubt, die könnten sich von den hiesigen Fischen unterscheiden...\n\nHerrje! Der Kieferknochen ist fast doppelt so groß wie beim gleichen Fisch hier. Und diese Schuppen sind so groß wie eine geballte Faust! Erstaunlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[6343] = { id = 6343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Nyoma", description = "Euch einen Flug zurück nach Dolanaar zu besorgen, wird einfach sein. Da Ihr Fidelio in Dolanaar bereits kennt, könnt Ihr ohne Probleme dorthin zurückfliegen.\n\nImmer wenn Ihr in einer neuen Stadt ankommt, solltet Ihr daran denken, mit dem Flugmeister zu sprechen, damit Ihr zu und von diesem neuen Ort fliegen könnt.\n\nSprecht mit mir, wenn Ihr bereit seid, einen Hippogryphen für den Rückflug nach Dolanaar zu mieten.", sourceObjective = "Sprecht mit Leora, um einen Hippogryphen zu mieten, der Euch nach Dolanaar zurückbringt. Sobald Ihr in Dolanaar angekommen seid, bringt Schwester Aquinnes Nachricht zu Nyoma.", progress = "{name}, Ihr seid aus Auberdine zurück? Habt Ihr mit Laird gesprochen?", completion = "Das ist sehr interessant. Die Fische hier sind riesig, aber ich hätte nicht gedacht, dass der Unterschied der Arten zwischen hier und dem Festland so groß ist. Dafür muss es einen Grund geben...\n\nIch danke Euch, {name}. Ich werde die Nachrichten, die Ihr gebracht habt, mit den Dorfbewohnern besprechen. Vielleicht finden wir eines Tages die Ursache dieser Kuriosität. Doch bis dahin wollen wir nutzen, was sie uns beschert!", sourceObjectiveStatus = "unverified-source-field" }
quests[6344] = { id = 6344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andenken an Zuhause", description = "Eine Freundin von mir, Schwester Aquinne, ist in der Ausbildung zur Mondpriesterin in Darnassus. Sie hat Dolanaar letztes Jahr verlassen, um im Tempel zu lernen. Laut ihren Briefen geht es ihr gut und sie lernt viel, aber sie vermisst ihr Zuhause und ihre alten Freunde. Ich habe ein Buch mit ihren Lieblingsrezepten aus Dolanaar zusammengestellt.\n\nWenn Ihr die Zeit findet, könntet Ihr es ihr nach Darnassus bringen? Ihr könnt einen Hippogryphen von Fidelio mieten. Er befindet sich in der Mitte der Stadt, gegenüber vom Gasthaus.", sourceObjective = "Bringt die Rezeptsammlung von Dolanaar zu Fidelio in Dolanaar.", progress = "Wie kann ich Euch helfen?", completion = "Ja, ich brauche einen Kurier, der ein Päckchen nach Dunkelküste bringt. Werdet Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[6361] = { id = 6361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündel Bälge", description = "Ich habe ein Bündel Bälge von Tieren Mulgores und muss es nach Donnerfels bringen. Dort fertigt Ahanu, ein Kollege, Lederwaren aus diesen Häuten an.\n\nBringt Ihr ihm die Bälge für mich?\n\nDer schnellste Weg nach Donnerfels ist auf dem Rücken eines Windreiters. Bringt das Bündel Bälge zu Tak, unserem Windreitermeister am Wegekreuz, und sprecht mit ihm über den Transport nach Donnerfels.", sourceObjective = "Bringt das Bündel Bälge zu Windreitermeister Tak im Dorf der Bluthufe.", progress = "Seid Ihr wegen eines Windreiters hier? Habt Ihr etwas zu transportieren?", completion = "Wenn Ihr diese Bälge nach Donnerfels bringen müsst, dann seid Ihr hier goldrichtig!", sourceObjectiveStatus = "unverified-source-field" }
quests[6362] = { id = 6362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flug nach Donnerfels", description = "Für ein kleines Entgelt gebe ich Euch einen Windreiter nach Donnerfels. Es gibt kein schnelleres Transportmittel in die Stadt!\n\nSollte das akzeptabel sein, sprecht wieder mit mir, wenn Ihr abreisefertig seid.\n\nWenn Ihr diese Bälge zu Ahanu bringen wollt, ich schätze, er ist in Hewas Waffenkammer am Fundament des Windreiterturms in Donnerfels. Und genau dort werdet Ihr landen!", sourceObjective = "Bucht einen Windreiter nach Donnerfels bei Windreitermeister Tak und bringt dann das Bündel Bälge zu Ahanu in Donnerfels.", progress = "Ihr habt Staub auf den Schultern, der aus dem Brachland sein muss. Habt Ihr mit meinem Freund Jahan gesprochen?", completion = "Ah, ein neues Bündel Bälge. Ich werde mich sofort damit an die Arbeit machen!\n\nDanke, Bruder. Ihr habt mir einen großen Dienst erwiesen. Hier habt Ihr ein paar Münzen für eure Zeit und Reisekosten.", sourceObjectiveStatus = "unverified-source-field" }
quests[6363] = { id = 6363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal der Windreitermeister", description = "Ich habe Lederwaren für Varg zum Verkauf im Dorf der Bluthufe vorbereitet. Würdet Ihr sie ihm bringen?\n\nWenn Ihr schon im Dorf der Bluthufe gewesen seid und mit dem dortigen Windreitermeister gesprochen habt, dann könnt Ihr mit einem unserer Windreiter zu ihm zurück.\n\nBringt die Lederwaren zu Tal, unserem Windreitermeister in Donnerfels, und sprecht mit ihm über den Transport zum Dorf der Bluthufe.", sourceObjective = "Bringt Ahanus Lederwaren zu Tal in Donnerfels.", progress = "Seid gegrüßt, {class}. Was kann ich für Euch tun?", completion = "Ihr müsst das nach Crossroads bringen, hm? Das ist kein Problem. Wenn Ihr schon einmal dort gewesen seid und mit Devrak gesprochen habt, dann könnt Ihr einen meiner Windreiter zurück zu ihm nehmen.", sourceObjectiveStatus = "unverified-source-field" }
